"""形态引擎：从日线序列里找出符合经典技术形态的票。

## 输入必须是**前复权**序列

`build_bars` 负责把不复权原始价 + 真实涨跌幅复利成前复权序列，本模块只处理
复权后的价格。除权跳空会让「缩量回踩」「平台突破」这类形态在错误的位置触发 ——
这是最容易埋雷的地方：形态图上看着不像，但引擎认为命中了，而且没人能一眼看出来。

## 输出是评分而不是布尔值

「像不像」比「是不是」有用得多：排序、筛选、复盘全靠它。每个形态给 0~100 的
连续分，外加关键位（突破价 / 支撑价）与明细指标（平台振幅、放量倍数…），
后者用于在页面上解释「为什么它入选了」—— 没有明细的分数字毫无说服力。

## 阈值集中在本文件顶部

散落在各函数体里的话，调参时要翻遍全文才能拼出全貌。
"""

import logging
import math
from collections.abc import Callable
from dataclasses import dataclass, field
from datetime import date

import numpy as np

logger = logging.getLogger(__name__)

# 低于这个分不进库。全部形态都会先做布尔前提，再连续打分，所以它是「像不像」的门槛
MIN_SCORE = 50.0

# 理想区间两端的分值系数。见 `_band_score`：中心 1.0，边缘这个值
EDGE_SCORE = 0.8

# ---------------------------------------------------------------- 样本口径


def is_st(name: str | None) -> bool:
    """名称里带 ST 的（含 `*ST`）**不参与形态选股**。

    2026-09-28 用户要求「形态选股剔除 st 票」。判据放在这里、由扫描与回测共用，
    不各写一份 —— 两边口径一旦分叉，回测数字就不再代表生产（8.68 那批形态上
    正是这么错的）。

    为什么只看名字：A 股简称全是汉字，`ST` 只可能出现在风险警示前缀里
    （`ST` / `*ST` / 老式的 `SST` / `S*ST` 都含 `ST`）。库里实测没有「name 还是
    代码本身」的行（2026-09-28 查过：0 只），所以不会因为名字没解析出来而漏掉。

    实测规模（当天的池子）：池内 135 只带 ST，2026-09-24 那天的命中里有 111 条。
    """
    return "ST" in (name or "").upper()


# ---------------------------------------------------------------- 各形态阈值

# 均线多头排列：四条均线要同时向上，看 20 日斜率；排列够这么多天给满分
MA_PERIODS = (5, 10, 20, 60)
MA_SLOPE_LOOKBACK = 20
MA_STACK_FULL_DAYS = 20
# MA5 相对 MA60 的乖离：太小说明还没走出来，太大说明已经涨过头
MA_SPREAD_IDEAL = (0.005, 0.05)
MA_SPREAD_CAP = 0.08
# 收盘距 MA20 的乖离：贴着均线说明刚启动，太远是追高
MA_GAP_IDEAL = (0.01, 0.08)
MA_GAP_CAP = 0.15

# 回踩不破 —— **2026-09-27 已删除**（阈值随判定函数一起删）。
#
# 它是最典型的「教科书买点」，但全量回测（5100 只 × 250 个交易日、3083 条信号）
# 里 10 日超额 −0.86%、20 日 −1.31%、10 日胜率只有 35.9% —— 买进去就落后大盘。
# 数字与另外三个同批被删的形态见设计文档 §8.68.25。

# 创 N 日新高：从长周期往短周期试，取命中的最长那个
NEW_HIGH_WINDOWS = (250, 120, 60)
NEW_HIGH_BASE = {250: 92.0, 120: 75.0, 60: 55.0}
# 最长的窗口不能超过「可用 K 线数 - 1」：判 N 日新高要留出今天之外的 N 根。
# 实测库里的历史正好是 250 个交易日，所以 250 日新高实际按 249 日判 ——
# 差这一天对「创近一年新高」这个语义毫无影响，但代码与 detail 里要说实话
NEW_HIGH_MIN_WINDOW = 60

# 平台突破
PLATFORM_DAYS = 30
# 30 日振幅上限。实测全市场分位：10% 分位 = 12.9%、20% 分位 = 17.2%，
# 取 15% 只留 421 只候选、当天只有 6 只命中，偏严；放宽到 18% 留 681 只
PLATFORM_MAX_RANGE = 0.18
# 平台宽度 ≤ 这个值就算「够窄」、拿满那 40 分（越窄越好，单方向）。原写法把
# `PLATFORM_MAX_RANGE - width` 喂给 `_band_score`，宽度 ≤3% 时正好落在 cap 上拿 0 分 ——
# 与注释「平台越窄越好」相反（2026-10-10 改成单方向的 `_gate_score`）。
PLATFORM_IDEAL_RANGE = 0.03
PLATFORM_VOL_MULT = 1.5
# 收盘高出平台上沿太多就不再是「突破」了，那是追高。
# 没有这条的话，一只票突破后会连着好几天留在榜上，越涨分越高（其实越危险）
PLATFORM_MAX_EXCESS = 0.08

# 放量突破前高
PRIOR_HIGH_DAYS = 60
PRIOR_HIGH_VOL_MULT = 2.0
PRIOR_HIGH_VOL_WINDOW = 20

# 海龟突破（2026-10-17 移植自 sngyai/Sequoia-X 的 `TurtleTradeStrategy`）
#
# 四条必要条件与原策略逐字对应：收盘创 20 日**最高价**新高、成交额过亿、
# 实体阳线、真涨（收盘高于昨收）。原式按流通市值降序出名单；本站是统一评分，
# 所以「谁排前面」由下面的加权分承担（成交额 / 量比 / 突破幅度 / 涨幅）。
#
# 与邻居的分工：`new_high` 只比**收盘**、且不看量；`volume_breakout` 突破的是
# **收盘**的 60 日前高、要求量比 ≥2；海龟突破比的是**最高价**（20 日），且额外要求
# 「阳线 + 真涨」—— 高开低走的大阴线即使盘中创了新高也不收，这是原策略的防诱多条款。
TURTLE_WINDOW = 20
TURTLE_MIN_AMOUNT = 1e8  # 成交额 ≥ 1 亿元（`stock_daily.amount` 单位就是元）
TURTLE_AMOUNT_IDEAL = 5e8  # 5 亿元拿满「流动性」那 20 分
TURTLE_VOL_IDEAL = (1.0, 3.0)
TURTLE_VOL_CAP = 8.0
TURTLE_EXCESS_IDEAL = (0.005, 0.03)
TURTLE_EXCESS_CAP = 0.10

# 均线放量金叉（2026-10-17 移植自 `MaVolumeStrategy`）
#
# 与 `_ma_golden_cross`（金叉共振）的分工：那条看 **MA5 × MA10**、要求 MA20 不走弱，
# 语义是「短周期刚转强」；这条看 **MA5 × MA20**、要求**放量**（20 日均量的 1.5 倍），
# 语义是「中期趋势切换 + 量能确认」。两条可以同一天命中同一只票，含义不同，不合并。
#
# ⚠️ 量比分母**含当日**（原式 `rolling(20).mean()` 把今天也算进去），与本文件通用的
# `_volume_ratio`（分母不含当日）不一样，别顺手换 —— 含当日会让门槛略难一点。
MA_VOLUME_FAST = 5
MA_VOLUME_SLOW = 20
MA_VOLUME_MIN_MULT = 1.5
MA_VOLUME_IDEAL_MULT = 3.0
MA_VOLUME_CAP_MULT = 8.0
MA_VOLUME_GAP_IDEAL = 0.02  # MA5 高出 MA20 的幅度到 2% 拿满「金叉强度」那 35 分

# 玉柱擎天（2026-09-27 用户点名要的形态）
#
# 一根**长实体大阳线顶破前期的压制位**，且明显放量。「玉柱」是那根柱子，
# 「擎天」指一天之内把上方压制买穿、且不让价格掉回来。
#
# 与三个邻居的分工（它们都不管 K 线**形状**，这是本形态真正的判据）：
# - `volume_surge`（放量上涨）：只看涨幅与量比，不管形状、也不管位置；
# - `volume_breakout`（放量突破前高）：按**收盘**突破 60 日收盘高点，不管形状；
# - `platform_breakout`（平台突破）：要求突破前先有一段**窄幅平台**。
# 玉柱擎天则要求「柱子够高 + 上影极短」，**且突破前不能已经涨了一大段** ——
# 涨完一大段再来的那根长阳是加速赶顶，不是玉柱擎天。
#
# 频率（滚动切片：794 只 × 最近 80 个交易日 = 6.35 万截面）：**0.135%/天/票**，
# 折合全市场每天约 7 只 —— 比「1~4%/天」那条经验线稀得多，但**这是定义使然**：
# 漏斗测下来没有哪一道门槛单独卡死（把任意一项放宽，也只从 0.135% 动到 0.14~0.20%），
# 各门槛的独立通过率是 收阳 49% / 实体≥5% 4.7% / 光头光脚 10% / 上影≤15% 16% /
# **顶破 60 日最高价 1.3%** / 量比≥2 2.8% —— 是「合取」稀有，不是某一条定得太死。
#
# 回测（`scripts/backtest_patterns.py --pattern jade_pillar`，2995 只 · 250 个交易日）：
#
# | 持有 | 信号 | 均值 | 中位 | 胜率 | 超额 |
# | --- | --- | --- | --- | --- | --- |
# | 5 日 | 972 | +0.10% | −1.67% | 42.2% | −0.05% |
# | 10 日 | 972 | −0.11% | −2.40% | 41.3% | −0.15% |
# | 20 日 | 972 | −1.86% | −5.16% | 35.5% | −0.45% |
# | 60 日 | 972 | −4.30% | −12.60% | 27.0% | −1.01% |
#
# ⚠️ **它没有超额**（短周期接近 0、20/60 日为负、中位一直为负、胜率不到 43%）。
# 参数稳健性也查过：把实体比放宽到 50%、上影放宽到 30%、实体高度放宽到 3%，
# 超额都在 ±0.2% 的噪声里打转，胜率始终 41~42% —— 没有可调出超额的空间，
# 所以**不要为了凑数字去调这几个阈值**。定位和别的形状类形态一样：
# 按这个形状捞一批票自己看。
#
# 一处确认（别顺手删掉）：去掉「突破前 60 日涨幅 ≤ 30%」这道位置门槛，信号从 972
# 涨到 1210，而 5 日超额从 −0.05% 掉到 −0.23%、20 日从 −0.45% 掉到 −0.75% ——
# 那道「排除加速段」的判断是对的，留着。
YZ_LOOKBACK = 60  # 「压制位」与「前期涨幅」都取这么多日
YZ_MIN_BODY_PCT = 0.05  # 实体相对昨收的下限：柱子要够高（大阳线）
YZ_MIN_BODY_RATIO = 0.7  # 实体占振幅的下限：接近光头光脚
YZ_MAX_UPPER = 0.15  # 上影占振幅的上限：冲高不能回落
YZ_MIN_VOL = 2.0  # 量比下限（与上面两个放量形态同一通行口径）
YZ_MAX_PRIOR_GAIN = 0.30  # 突破前 YZ_LOOKBACK 日的累计涨幅上限（排除加速段）

# 放量上涨（量比按 5 日均量算，这是通行口径）
SURGE_MIN_PCT = 3.0
SURGE_MIN_VOL_RATIO = 2.0
SURGE_PCT_IDEAL = (3.0, 10.0)
SURGE_PCT_CAP = 21.0
SURGE_RATIO_IDEAL = (2.0, 6.0)
SURGE_RATIO_CAP = 12.0

# 放量阳包阴（2026-10-19）：倍量 = 今日成交量 / 昨日成交量。
# 门槛 1.5 是用户定的（2026-10-19 从 1.2 提到这里）：1.2 时一天 250+ 条，
# 命中列表前 50 几乎被它占满；1.5 之后约 80 条，仍能覆盖「明显放量」的反包。
ENGULF_MIN_VOLUME_RATIO = 1.5

# 缩量回踩
DRY_PULLBACK_MIN_DAYS = 3
DRY_PULLBACK_MAX_DAYS = 10
DRY_PULLBACK_DROP = (0.03, 0.15)
DRY_PULLBACK_MAX_VOL_RATIO = 0.6
# 缩到这个比例以下算「缩量到位」，满分
DRY_PULLBACK_IDEAL_VOL_RATIO = 0.35
DRY_PULLBACK_UP_WINDOW = 10  # 回调之前用多少天算「上涨期均量」

# ---- 几何形态（共用摆动点骨架）----

# 摆动点的最小反向幅度，按该股近一年的**日均振幅中位数**自适应再乘这个倍数。
# 固定百分比的问题：3% 对低波动股是一个大摆动，对高波动股是日常噪声，
# 同一套阈值在两端的严格程度能差一个数量级
SWING_AMP_MULT = 3.0
SWING_MIN = 0.06
SWING_MAX = 0.18
# 算日振幅中位数用多少根 K 线
SWING_AMP_WINDOW = 250

# 杯柄
CUP_WINDOW = 110
CUP_LEFT_END = 0.40  # 前 40% 里找左杯沿
CUP_RIGHT_START = 0.70  # 后 30% 才开始算右杯沿，保证杯底在中间
CUP_DEPTH = (0.15, 0.35)
CUP_RECOVER = 0.85  # 右杯沿至少回到「杯深」的多少比例
CUP_HANDLE_MIN_DAYS = 2
CUP_HANDLE_MAX_DAYS = 25
# 柄部回撤不能超过杯深的多少。O'Neil 的原始说法是「柄部落在基底上半部」，
# 理论上限 1/2、理想值 1/3。实测全市场 331 只候选里，柄部回撤/杯深的中位数
# 高达 74%、只有 19 只在 1/3 以内 —— 用 1/3 当门槛会一只都不剩，
# 所以**门槛放到 1/2，把「越接近 1/3 分越高」交给打分**
CUP_HANDLE_DEPTH_RATIO = 0.5
# 回撤到杯深的这个比例以内算「柄部很浅」，满分
CUP_HANDLE_IDEAL_RATIO = 0.2
CUP_HANDLE_VOL_RATIO = 0.9  # 柄部均量 / 右杯沿上涨段均量
# 缩到这个比例以下算「柄部缩量到位」，满分
CUP_HANDLE_IDEAL_VOL_RATIO = 0.4

# W 底（双底）
DOUBLE_BOTTOM_WINDOW = 130
DOUBLE_BOTTOM_MIN_BARS = 90
DOUBLE_BOTTOM_TOLERANCE = 0.05  # 两个低点相差
DOUBLE_BOTTOM_GAP = (15, 70)  # 两底间隔的交易日数
DOUBLE_BOTTOM_REBOUND = 0.10  # 中间反弹幅度
DOUBLE_BOTTOM_MAX_EXCESS = 0.06  # 收在颈线上方太多就不算「刚突破」了

# 三角收敛 —— **2026-09-27 已删除**（阈值随判定函数一起删）。
#
# 全量回测（5100 只 × 250 个交易日、306 条信号）：10/20/60 日超额 −1.08% / −1.97%
# / −1.91%，10 日胜率 **31.0%**（当时全部形态里最低）。详见设计文档 §8.68.25。

# 头肩底
HS_WINDOW = 150
HS_MIN_BARS = 100
HS_SHOULDER_TOLERANCE = 0.10  # 两肩低点相差
HS_NECK_TOLERANCE = 0.08  # 两个颈线高点相差，也就是颈线有多「平」
HS_MIN_DEPTH = 0.08  # 头比颈线低多少才算一个头，低于这个数只是小抖动
HS_MAX_EXCESS = 0.06  # 收在颈线上方太多就不算「刚突破」
HS_MAX_TAIL = 20  # 右肩之后最多再等这么多根 K 线，再久这形态就翻篇了

# 旗形（急涨之后的窄幅整理）
FLAG_POLE_DAYS = 10  # 旗杆长度
FLAG_MIN_POLE = 0.15  # 旗杆至少涨这么多才算「急涨」
FLAG_MIN_DAYS = 3  # 旗面最短 / 最长——太短不叫整理，太长那叫趋势
FLAG_MAX_DAYS = 20
FLAG_MAX_RANGE = 0.12  # 旗面振幅，收窄才算整理
FLAG_MAX_RETRACE = 0.5  # 回撤占旗杆的比例
FLAG_MAX_VOL_RATIO = 0.85  # 旗面均量 / 旗杆均量
FLAG_MIN_POSITION = 0.55  # 收盘在旗面区间里的位置
FLAG_MAX_EXCESS = 0.05  # 收在旗面上沿上方太多就不算「贴着待突破」

# 三段式突破（缓涨 → 急涨 → 缩量整理 → 突破整理段上沿）
#
# 这一组阈值是**回测出来的**，不是照着某一只票定的。回测脚本见
# `scripts/backtest_patterns.py`：全市场 250 个交易日、2995 只票，
# 同一只票 20 个交易日内的重复信号已去重，收益按**同一天全市场平均**做基准。
#
# | 口径 | 信号数 | 5 日超额 | 10 日超额 |
# | --- | --- | --- | --- |
# | 宽（初版） | 87 | +3.4% | +4.7% |
# | **本组（中间）** | **36** | **+5.7%** | **+4.9%** |
# | 严（照抄单只票特征） | 8 | +7.9% | +2.9% |
#
# 取中间这组的原因：放宽到 87 个时超额明显下滑（阈值形同虚设），收紧到 8 个
# 时样本少到说明不了问题。
#
# ⚠️ **2026-09-19 复核：上面那张表已作废，别再引用它的数字。**
# 那张表是回测脚本**自带的一套草案实现**跑出来的 —— 阈值与这里的 THREE_* 各写各的，
# 两边早就漂移了；而且当时的取数窗口还被交易日历（预置到年底）截掉了最早三个月。
# 改成直接调生产函数 `_three_stage` 重跑后，真实数字是：
#
# | 口径 | 信号数 | 5 日超额 | 10 日超额 | 20 日超额 |
# | --- | --- | --- | --- | --- |
# | **生产（复核后）** | **72** | **+2.00%** | **+2.48%** | **+4.12%** |
#
# 也就是说原表把 10 日超额**高估了整整一倍**。
#
# ⚠️ 它的局限仍然要一起看，别只记超额：10 日**中位数 −0.10%**、20 日中位数
# **−2.44%** —— 赚的是少数大涨（最好 +102.7%、最差 −44.2%）。
# 这是低胜率高赔率的形态，不是「看到就买」。
THREE_SLOW_DAYS = 15  # 缓涨段取急涨之前的这么多天（不枚举长度，涨幅区间已能覆盖）
THREE_SLOW_GAIN = (0.06, 0.45)
THREE_SLOW_BULL = 0.52  # 缓涨段的阳线占比
THREE_SURGE_DAYS = (2, 3)
THREE_SURGE_GAIN = 0.11
THREE_SURGE_VOL = 1.5  # 急涨段均量 / 急涨前 5 日均量
THREE_FLAT_DAYS = (4, 15)
THREE_FLAT_RANGE = 0.14  # 整理段振幅，相对整理段均价
THREE_FLAT_VOL = 0.68  # 整理段均量 / 急涨段均量
THREE_FLAT_DROP = 0.50  # 从急涨段高点回落，不超过急涨涨幅的多少
THREE_BREAK_VOL = 1.3  # 突破日量 / 整理段均量

# 涨停爆量横盘（涨停爆量 → 突破前期平台 → 缩量横盘，当前仍在横盘段里）
#
# 来自用户举的一只真实票（共达电声 002655，2026-02 那段）：
#   02-10 涨停 + 7.55 倍量，收 14.08 越过 1 月下旬 13.65 的平台
#   02-13 冲到 16.00（自 12.80 起 +25%）
#   02-24~26 缩量横盘，区间 15.31~16.15（振幅 5.4%）、量能降到上冲段的 0.61 倍
#   02-27 再拉一个涨停
#
# 与「旗形」的区别：旗形只要「急涨 + 窄幅整理」，这里额外要求急涨**由涨停爆量
# 启动**、且**站上了前期平台** —— 多这两条把「一根阳线拉起、没有资金进场痕迹」
# 的票挡在外面。
# 与「三段式突破」的区别：三段式找的是**今天刚突破**的瞬间，这里突破已经完成，
# 找的是**正在横盘**的票（等二次启动），两者的买点完全不同。
#
# ⚠️ 下面这组阈值起步时是按**单只票**定的，靠全市场扫描 + 回测校准过
# （过程与实测数据见设计文档 8.16.3），别直接改成某只票身上的数字。
LS_LOOKBACK = 30  # 在最近这么多天里找涨停爆量日
LS_LIMIT_PCT = 9.5  # 「涨停」的下限，留出主板 10% 的统计余量（20cm 板也一并覆盖）
LS_SURGE_VOL = 2.5  # 涨停日量 / 前 5 日均量
LS_BREAK_DAYS = 3  # 涨停后这么多天内要完成对平台的收盘突破
LS_PLATFORM_DAYS = 40  # 「前期平台」回看多少个交易日
LS_MIN_RUN = 0.15  # 涨停前收盘 → 上冲段最高点，至少要涨这么多
LS_FLAT_DAYS = (2, 15)  # 横盘段长度（含今天）
LS_FLAT_RANGE = 0.12  # 横盘段振幅上限，相对横盘段均价
LS_FLAT_VOL = 0.75  # 横盘段均量 / 上冲段均量
LS_FLAT_KEEP = 0.5  # 横盘低点至少守住「平台上沿 → 上冲最高点」这段的多少

# 突破后横盘（放量突破 → 缩量横着 → 今天仍在横盘区间里，等二次启动）
#
# 与「涨停爆量横盘」的区别：那个要求突破**由涨停爆量启动**、且站上**前期平台**；
# 这里只要「放量突破 60 日新高」、之后横着不跌回突破位 —— 门槛低得多，
# 频率也低得多（涨停爆量横盘每天十几只，这里平均每 4 个交易日才一只）。
#
# 阈值与三段式一样是**回测出来的**（`scripts/backtest_patterns.py
# --pattern breakout_flat`，现在直接调本函数跑）。250 个交易日、2995 只票：
#
# | 口径 | 信号 | 5 日超额 | 10 日超额 | 20 日超额 | 10 日胜率 | 10 日中位 |
# | --- | --- | --- | --- | --- | --- | --- |
# | **本组（放宽）** | **63** | **+3.53%** | **+4.03%** | +1.58% | **61.9%** | **+2.04%** |
# | 收紧（振幅 8% / 缩量 50%） | 12 | −1.69% | −4.91% | −8.21% | 25.0% | −5.80% |
#
# 收紧那组是**负超额** —— 这个形态不是越严越好，所以取了上面这组。
# 它曾经被否掉过（当时的记录是「比三段式弱」），那是**取数窗口被日历表截断**
# 造成的误判，详见设计文档 8.16.3。
#
# ⚠️ 爆发力集中在 5~10 日，20 日之后开始回吐（60 日中位 −5.18%）—— 短打标的。
BF_MIN_FLAT = 3  # 横盘至少几天
BF_MAX_GAP = 12  # 突破日距今天最多几天
BF_MIN_GAIN = 0.08  # 突破日涨幅
BF_MIN_VOL = 2.0  # 突破日量 / 前 5 日均量
BF_PRIOR_HIGH = 60  # 突破要创这么多日的新高，否则只是「涨了一天」
BF_MAX_RANGE = 0.12  # 横盘振幅，相对横盘均价
BF_MAX_GIVEBACK = 0.03  # 横盘最低点允许比突破日收盘低多少
BF_MAX_SHRINK = 0.60  # 横盘均量 / 突破日量
# 今天仍在横盘区间里的容差：越过上沿 / 下沿这么多就不算了（已经突破或已经破位）
BF_EDGE_TOLERANCE = 0.02

# N 字选股（放量大涨 → 缩量回调到起涨点附近）
#
# 名字是用户起的，形态就是他说的那三步：**一笔上（放量大涨）→ 一折下（缩量回踩起点）
# → 等再一笔上**。起涨点取**大涨那天的起点**（开盘价与前一日收盘取低的，含跳空），
# 这是它与「缩量回踩」最大的区别 —— 那个看均线，这里看的是
# **涨势的起点有没有被回踩确认**。
#
# ⚠️ 它**不是回测出来的形态，也没有回测支持**：用户明确说「后续涨跌无所谓」，
# 要的就是一份清单。2026-09-27 全量回测（5100 只 × 250 日、4557 条信号）：
# 5/10/20/60 日超额 −0.65% / −1.23% / −1.61% / −2.00%、10 日胜率 39.5% ——
# 比早先 2995 只样本那次测出来的 −0.16% 更负，**它是明确跑输大盘的**。
# 保留它是因为用户点名要这个形状，不是因为它有效。
# 所以定位是「按这个形状捞一批票自己看」，**别按信号去理解它**。
NS_SURGE_PCT = 5.0  # 「放量大涨」：单日涨幅
NS_SURGE_VOL = 2.0  # 放量：量 / 前 5 日均量
NS_PULL_DAYS = (1, 5)  # 缩量回调的天数
NS_LOW_BAND = (0.95, 1.03)  # 回调最低点 / 起涨点：既不能破位太多，也得真踩到
NS_NOW_BAND = (0.96, 1.08)  # 今天的收盘 / 起涨点
NS_MAX_SHRINK = 0.95  # 回调期均量 / 大涨日量

# 爆量后缩量回踩（爆量日成交额 ≥ 前一日 2 倍且阳线 → 之后某天缩到爆量日一半以下）
#
# 用户举了 7 只票定义这个形态（昆船智能 / 奥佳华 / 内蒙新华 / 博通集成 / 新强联 /
# 继峰股份 / 金丹科技），规则完全一致：
#
#   爆量日：成交额 ≥ 上一交易日成交额 × 2（「为上一交易日两倍以上」），**且是阳线**
#   （收 > 开。2026-09-25 补：放量下跌的「爆量」是出货，不是「缩量回踩」）
#   缩量日：爆量日**之后**的某天，成交额 ≤ 爆量日成交额 × 0.5（「为爆量日一半以下」）
#   **要选出来的就是缩量日**（不是爆量日）
#
# 爆量日看成交额 + 阳线，缩量日只看成交额。爆量日到缩量日的间隔在案例里从 1 到
# 7 个交易日不等（继峰股份 1 天、博通集成 7 天）。
BURST_SHRINK_MULT = 2.0  # 爆量日成交额 / 前一日成交额 的下限（「两倍以上」）
BURST_SHRINK_RATIO = 0.5  # 缩量日成交额 / 爆量日成交额 的上限（「一半以下」）
BURST_SHRINK_LOOKBACK = 10  # 往前找爆量日最多看几个交易日（案例最长 7 天）
# 打分里「爆量倍数」的理想值：≥ 这个倍数的爆量算满分（越猛越醒目，越大不扣分）
BURST_SHRINK_MULT_IDEAL = 5.0
BURST_SHRINK_IDEAL_RATIO = 0.3  # 缩到爆量日的 30% 算「缩量到位」，满分
BURST_SHRINK_GAP_IDEAL = (1.0, 5.0)  # 爆量日到缩量日间隔（交易日）的理想区间
BURST_SHRINK_GAP_CAP = 10.0  # 隔得太久说明「缩量回踩」这层关系已经散了

# 堆量上涨后缩量（2026-10-14 用户要求；举了中红医疗 / 近岸蛋白 / 善水科技 三只样例）
#
# 形态：先有一段**持续的**放量推升（「堆量」，不是单日爆量），之后量能塌缩到那一轮的
# 一小部分、价格也从高点回落 —— **要选出来的是缩量那一天**。
#
# 三只样例的实测数（基线 = 堆量段开始之前 60 个交易日的均量）：
#
#   中红医疗 300981：7/30~8/7 堆量（均量 5.5× 基线，区间 +25%），8/25 缩到堆量峰值的 19.8%
#   近岸蛋白 688137：8/4~8/26 堆量（6.3×，+137%），9/7 缩到 38.0%
#   善水科技 301190：7/20~8/25 堆量（3.2×，+46%），9/18 缩到 19.7%
#
# ⚠️ **「缩量」的分母用堆量段的「峰值」而不是「均量」**：近岸蛋白那一轮的**均量**只
# 缩到 89%（几乎没缩），可它的缩量日确实存在 —— 用均量当分母会把这只票直接筛掉。
# 峰值才是「这一轮放量有多猛」的参照（而「是不是一段堆量」由上面那条均量倍数管）。
#
# ⚠️ **还要「今天是近 N 日最低量」**：只留「≤ 峰值的 45%」的话，横盘期量能一降就会
# 命中，等于在地板上来回出信号；加上这一条才把时点钉在**缩量的那一刻**（三只样例当天
# 都是近 10 日最低量）。代价是缩量若持续、量能天天创新低，会连着几天命中同一只票 ——
# 胜率统计那边已按 (代码, 形态, 信号日) 去重（见 `pattern_track._picks`），不会重复计数。
PILE_LOOKBACK = 45  # 往前找「堆量高点」最多看几个交易日
# 堆量高点距今最多几个交易日 —— **这是最关键的收紧项**。
#
# 不加这一条时（首版实测）一天命中 143 只、十天并集 392 只：绝大多数是「堆量发生在
# 35~44 个交易日之前」的老票，而那已经不是「这轮涨完在歇」了，是上个月的旧账。
# 三只样例的间隔只有 **8 / 12 / 17** 个交易日，取 20 留一点余量。
PILE_GAP_MAX = 20
PILE_BASE_DAYS = 60  # 基线窗口（堆量段开始之前）的长度
PILE_MIN_DAYS = 6  # 堆量段最短。比这还短就是单日爆量，那是 `burst_shrink_pullback`
# 堆量段最长放到 30：善水科技那一轮是 **27 个交易日**（7/20~8/25），卡在 25 会被砍掉 ——
# 而它的均量倍数只有 3.2（三只里最弱），一砍就把「涨幅 ≥ 18%」和「倍数 ≥ 2.8」两条
# 赶到互相打架的位置上（见下面 `PILE_VOL_MULT` 那段）。
PILE_MAX_DAYS = 30
PILE_VOL_MULT = 2.8  # 堆量段均量 / 基线均量 的下限（三只样例 3.2 / 5.6 / 6.9）
PILE_VOL_MULT_IDEAL = 5.0  # 到 5 倍算「够猛」，打分满分
PILE_MIN_RISE = 0.18  # 堆量段涨幅下限（样例 25% / 116% / 46%）
PILE_RISE_IDEAL = 0.60  # 涨幅到 60% 算满分
SHRINK_VS_PEAK = 0.40  # 缩量日量 / 堆量段最大量 的上限（样例 19.8% / 38.0% / 19.7%）
SHRINK_IDEAL = 0.20  # 缩到峰值两成算「缩量到位」，打分满分
SHRINK_LOWEST_DAYS = 10  # 缩量日必须是近 N 个交易日里量最小的那天
PILE_PULLBACK_MIN = 0.07  # 今天相对堆量段最高收盘的回撤下限（样例 8.0% / 26.7% / 12.2%）
PILE_PULLBACK_IDEAL = (0.10, 0.32)  # 回撤的理想区间：太浅没洗够、太深就近破位了
PILE_PULLBACK_CAP = 0.55  # 回撤超过它就与「缩量回调」无关了

# 欧奈尔突破（O'Neil 的「枢轴点买入」）—— **2026-09-27 连同整套 RS 机制一起删除**
#
# 它来自《笑傲股市》，但只取技术面（缺 C/A 盈利项与 I 机构持仓）。删它的两条理由
# 与实测数字见设计文档 §8.68.25，这里只留结论：
#
# 1. **它不出票**：库里 24 个交易日里一共命中过 1 只，全量回测 0 条信号 ——
#    筛选条上常年是 0，对用户等于一个坏按钮。
# 2. **它本来就不是信号**：筛出来的是银行 / 红利 / 公用事业这类稳健股，各口径超额
#    都在负区间；试过加「日均振幅 ≥2.5%」挡红利股，没挡住，反而把样本从 32 砍到 14。
#    **缺基本面，靠技术面补不上。**
#
# ⚠️ 它一删，`compute_rs` / `RS_WEIGHTS` / `RS_MIN_BARS` / `Bars.rs` 全成了死代码，
# 已一并删除 —— 那套横截面 RS 排名只服务于这一个形态。想要爆发股请看「突破后横盘」。

# 悟道之路 · 致富选股（样板 → 启动）
# 扫描侧：候选池 = **创业板 + 科创板**里当日冲高 ≥4.5% 的票（见 jobs/scan_patterns.py）
# 量比口径与本地悟道之路一致：当日量 / 近 20 日均量（不是 5 日）
WUDAO_SAMPLE_HIGH_PCT = 7.0
WUDAO_SAMPLE_VOL = 1.3
# 样板日「收盘离开最高」的上限（leave_high = (最高 − 收盘) / 最高）。
# 2026-10-09 用主库全池实测（每票 260 根 ≈ 近一年）加的一道**过线概率过滤**：
# 收盘离最高越近，明天越容易过今高 —— 四个四分桶的「次日过今高」一路单调
# 56.4% / 46.2% / 33.8% / 19.6%，配 5 日到线 57% / 54% / 46% / 41%、
# 破位 28% / 30% / 34% / 39%。取中位数 0.029 当门槛：
#   5 日到线 46.3%→54.3%、5 日破位 38.9%→29.8%
#   （**生产口径不去重** 19989→9524、保留 47.6%；同票 20 日去重后 12365→7500、保留 60.7%）。
# ⚠️ 这条线的收益改善是**温和**的（5 日超额 −0.28%→−0.10%），
# 大幅改善的是「过不过线」这件事本身，别把到线率当成收益承诺。
#
# ⚠️ 它**只作用在「明天盯 / 明天预案」两个出口**（`_wudao_leave_ok`），
# **没有**并进 `_wudao_is_sample` —— 那个判据还被「洗完可盯」与个股页阶段判定共用，
# 并进去会把它们一起砍掉约 43%（实测 2035→1161）、个股页 `sample` 标签 28→10。
WUDAO_SAMPLE_MAX_LEAVE = 0.029
WUDAO_START_VOL = 1.5
WUDAO_DIVERGE_VOL = 2.5  # 与悟道：爆量冲高不收 → 吵/出货，不当明天盯
WUDAO_MIN_BARS = 22  # 昨收 + 近 20 日均量 + 余量

# ---- 阶段判定（`classify_phase`）决策链的阈值（2026-10-10 集中到这里）----
#
# 这些数原先是散在函数体里的魔数。它们被回测脚本、《策略》与设计文档逐条引用过，
# 散着写必然「改一处、漏一处」。名字按「哪个分支、什么含义」起，别用缩写。
#
# ⚠️ 改动这里的任何一个数，回测/跟踪里的历史数字就不再代表生产（同 §8.88 那几条）。
WUDAO_WAKE_VOL = 1.2  # 「刚有人气」：量比 ≥ 这个，且涨幅/冲高达标
WUDAO_WAKE_PCT = 4.0  #   —— 涨幅 ≥ 这个
WUDAO_WAKE_HIGH_PCT = 6.0  #   —— 或冲高 ≥ 这个
WUDAO_THIN_UP_PCT = 9.5  # 缩量大涨兜底：涨幅 ≥ 这个也算「刚有人气」（涨停/一字量比常 0.3~0.8）
WUDAO_DIGEST_PCT_LO = -3.0  # 「休息中」：涨跌幅下界（下侧正好与「走弱」接上，不留缝）
WUDAO_DIGEST_VOL = 1.15  #   —— 量比 ≤ 这个
WUDAO_DIGEST_RET5 = 8.0  #   —— 且近 5 日至少涨过这么多，否则不叫「歇口气」
WUDAO_WEAK_PCT = -3.0  # 「走弱」：跌幅 ≤ 这个（2026-10-10 新增的一档，见 classify_phase）
WUDAO_SILENT_VOL = 0.85  # 「没动静」：量比 < 这个
WUDAO_DUMP_VOL = 1.4  # 「像出货」（在「吵/出货」里再分档）：量比 ≥ 这个
WUDAO_DUMP_PCT = 2.0  #   —— 且涨幅 < 这个
WUDAO_DUMP_UPPER = 0.3  #   —— 且上影 ≥ 这个
WUDAO_DIVERGE_UPPER = 0.25  # 爆量冲高不收：上影 ≥ 这个
WUDAO_DIVERGE_CLOSE_POS = 0.7  #   —— 或收盘位置 ≤ 这个

# 悟道之路 · 辉宾选股2「洗完 → 明天可进」（2026-10-08 移植，见 docs/plans/2026-10-08-yangban-port.md）
#
# 数字**照抄** `yangban-desk/app/pattern_wash2.py`（commit fe32f80）：洗盘日要像金丹 9/16 ——
# 锚点（启动低 / 样板高）还在、收盘温和、不是继续主升。
WUDAO_WASH_MAX_ABS_PCT = 3.0  # 洗盘日 |涨跌幅| 上限
WUDAO_WASH_MAX_BODY_PCT = 3.5  # 实体（相对启动收盘）上限；只在当日 pct > 2 时才否决
WUDAO_WASH_MAX_VS_START_CLOSE = 1.04  # 洗盘收盘 / 启动收盘 的上限倍数
WUDAO_WASH_MIN_BARS = 28  # 最远用到 bars[-3]（样板日 = i−2）；再留余量给样板日的 20 日均量
#
# 回测（2026-10-08，`scripts/backtest_patterns.py --pattern wudao_wash2 --board wudao`
# = 创业板 + 科创板 1908 只 × 2026-01~07，无未来函数、同票 20 日去重、基准 = 同日全市场平均）：
#
# ⚠️ **口径对上了**：wash2 现在只收**创业板 + 科创板**（`scan_patterns._signal_allowed`
# 的板块闸门，不带候选池），与 `--board wudao` 同一个口径 → 这张表重新代表生产。
# （2026-10-08 ~ 10-09 之间它一度是全池扫，那时这张表不算数。）
#
# | 持有 | 信号 | 均值 | 中位 | 胜率 | 超额 |
# | 5 日 | 638 | +0.55% | −0.36% | 48.0% | **+0.41%** |
# | 10 日 | 638 | −0.61% | −1.85% | 43.6% | −0.05% |
# | 20 日 | 638 | −1.81% | −5.85% | 40.3% | +0.30% |
# | 60 日 | 638 | −6.74% | −14.83% | 28.7% | −1.82% |
#
# ⚠️ **读法：短周期略有指向、中期没有**。5 日 +0.41% 是噪声量级（胜率 48% 接近抛硬币），
# 10/20 日超额在 ±0.3% 里打转，60 日为负、四档中位数全负 —— 它**不是高胜率信号**，
# 定位与「明天盯 / 明天预案」相同：按这个形状捞一批票自己看。它的价值在纪律上
# （洗盘日只观察、明天过洗高再进、破启动低作废），不在统计超额。
# ⚠️ 样本只有 2026-01~07 一段行情（同 §8.67 那条老提醒），只能横向比、不能当长期能力。
# ⚠️ **必须用 `--board wudao`**：拿全市场跑会得到另一批票的信号 —— 2026-10-08 实测
# 1200 只深市主板时是 −0.35% / +0.50% / −0.89% / −3.07%、胜率 35~39%，与上表不可比。

# 悟道之路 · 强达型「堆量吸筹 → 放量拉升 → 缩量洗盘」（2026-10-08 移植，见移植方案 §1.2）
#
# 多日结构（十几到几十个交易日），不是单日样板。数字**照抄** `yangban-desk/app/pile_wash.py`
# （commit fe32f80）：在近 55 根里滑窗找「放量拉升」段，再判前段有没有堆量、后段是不是缩量洗盘。
#
# ⚠️ 它那套有五个阶段，我们**只出两个能动手的**：
#   · `ready` 洗后可盯 → 形态 `pile_wash_ready`
#   · `wash` 缩量洗盘中 → 形态 `pile_wash_wash`
#   `pile`（堆量吸筹中）/ `surge`（刚放量拉升）它的纪律都是「只观察、别动手」，不值当占形态卡片；
#   `gone`（已经主升完 / 回撤吐光）更不该出信号。所以那两个 key 都不会出现在结果里。
PILE_MIN_BARS = 50
PILE_LOOK_BARS = 55  # 只在最近 55 根里找拉升窗口
PILE_SURGE_WIDTHS = (5, 6, 7, 8, 9, 10, 12)  # 滑窗宽度
PILE_PRE_MIN_BARS = 8  # 窗口前至少要有 8 根当基准
PILE_SURGE_MIN_RET = 16.0  # 拉升段：段内最高 / 前基 ≥ 16%
PILE_SURGE_MIN_CLOSE_RET = 10.0  # 拉升段：段末收盘 / 前基 ≥ 10%
PILE_SURGE_MIN_VOL_LIFT = 1.35  # 拉升段均量 / 前段均量
PILE_PILE_MIN_RATIO = 1.25  # 堆量：后段均量 / 前段均量 ≥ 1.25
PILE_PILE_MIN_PRE_RET = -12.0  # 堆量前不是单边暴跌（pre_ret > -12）
PILE_PILE_MAX_PRE_RANGE = 38.0  # 堆量前振幅上限（%）
PILE_WASH_MAX_VOL_RATIO = 0.72  # 洗盘均量 / 拉升均量 ≤ 0.72
PILE_WASH_KEEP_ABOVE_BASE = 1.05  # 洗盘末收盘 ≥ 前基 × 1.05
PILE_WASH_MAX_GIVEBACK = 0.62  # 回吐 / 整段涨幅 的上限
PILE_WASH_MAX_RANGE_PCT = 28.0  # 洗盘段振幅上限（%）
# 「缩量洗盘中」的**位置门槛**（2026-10-09 加）：现价 / MA60（含当日）。
# 加它的原因：单看「拉升 → 缩量横盘」这个结构，它就是**全市场平均** ——
# 主库全池实测（每票 260 根 ≈ 近一年；n=6707 条命中）基线 5/10/20/60 日超额
# +0.45/+0.37/+0.19/+0.92，也就是说这个标签**没有筛选力**（见设计文档 §8.87.6 第 ⑧ 条）。
# 按「位置」一拆就分开了（阈值扫描见 §8.88）：
#   收盘 ≥ MA60×1.08 的那一半（n=3284）：+1.08/+1.31/+1.31/+2.43
#   另一半（n=3423）                  ：−0.16/−0.53/−0.88/−0.52
# 门槛取 1.08（数据里的 3/4 分位 ≈1.077，取整到两位）。对半拆分（按日期）两半都为正：
#   前半 +0.77/+0.65/+0.87；后半 +1.61/+2.43/+2.06（5/10/20 日）。
PILE_WASH_MIN_POS_MA60 = 1.08
PILE_READY_NEAR = 0.97  # 收盘 ≥ 洗盘高 × 0.97 算「贴近」
PILE_READY_MIN_VOL = 1.15  # 贴近时要求的量比
PILE_GONE_ABOVE = 1.18  # 突破后远离洗盘高这么多、且 5 日涨幅大 → 已主升完
PILE_GONE_RET5 = 18.0
#
# 回测（2026-10-08，`scripts/backtest_patterns.py --pattern <key>`，全池 4945 只 × 2026-01~07，
# 无未来函数、同票 20 日去重、基准 = 同日全市场平均）。它是**没加板块闸门**那一版的数字
# （现在生产只收创业板 + 科创板，要比就得加 `--board wudao`）：
#
# | 形态 | 信号 | 5 日超额 | 10 日超额 | 20 日超额 | 60 日超额 | 胜率(5/10/20/60) |
# | --- | --- | --- | --- | --- | --- | --- |
# | 洗后可盯 | 2347 | +0.27% | +0.18% | −0.24% | +0.80% | 46.0 / 43.7 / 37.6 / 33.1% |
# | 缩量洗盘中 | 6707 | +0.45% | +0.37% | +0.19% | +0.92% | 48.4 / 44.7 / 38.4 / 33.6% |
#
# ⚠️ **读法与 wash2 一致：短周期略有指向、胜率不到 50%、四档中位数全负** —— 不是高胜率信号。
# 它的用法本来就写在纪律里（`wash` 主观察、`ready` 才是「可小仓试」），当清单用。
# ⚠️ 频率差异要知道：悟道那边只扫当天的强势候选（40~60 只）再截前 20/25 张卡片；
# 我们**不限候选池**（过了「创业板 + 科创板」这道板块关就全收），所以「缩量洗盘中」
# 一天仍有上百只 —— 它本身就是「安静了很多天的票」，拿「今天有动静」的候选去筛反而
# 会漏掉，这是我们**故意**跟它不一样的地方。
# ⚠️ 样本 2026-01~07 一段行情，只能横向比。

# 悟道之路 · 华宝早期（2026-10-08 移植，见移植方案 §1.3）
#
# 更早一档的观察池：连阳 + 贴 5 日线 + 量由缩转放 + MACD 抬头。数字**照抄**
# `yangban-desk/app/huabao_early.py`（commit fe32f80）。**只观察、不直接买** ——
# 它自己的纪律是「真正动手仍要等走出明天盯 → 明天预案」。
WUDAO_HUABAO_MIN_BARS = 30
WUDAO_HUABAO_MAX_RET_20 = 32.0  # 20 日累计涨幅上限（超过 = 已经主升完）
WUDAO_HUABAO_MAX_RET_5 = 22.0  # 5 日累计涨幅上限
WUDAO_HUABAO_LATE_RET_20 = 25.0  # 贴着 20 日高时，涨幅超过它才算「太晚」
WUDAO_HUABAO_MIN_YANG = 3  # 最少连阳根数
WUDAO_HUABAO_MAX_YANG_LOOK = 8  # 连阳最多往回数这么多根
WUDAO_HUABAO_HUG_LOW_GAP = (-2.8, 3.2)  # 最低价相对 MA5 的区间（%）
WUDAO_HUABAO_HUG_CLOSE_GAP = (0.0, 9.5)  # 收盘相对 MA5 的区间（%）
WUDAO_HUABAO_HUG_MAX_UPPER = 0.45  # 上影上限；超过它时当日涨幅必须 ≥4%
WUDAO_HUABAO_HUG_MAX_PCT = 9.5  # 单日涨幅上限（别天天接近一字板）
WUDAO_HUABAO_YANG_AVG = (0.4, 6.5)  # 连阳段平均涨幅区间（%）
WUDAO_HUABAO_YANG_MAX_VAR = 18.0  # 连阳段涨幅方差上限（别暴涨暴跌混着）
WUDAO_HUABAO_MACD_MIN_RATIO = -0.0015
# ⚠️ 2026-10-10 口径变更：原常量 `WUDAO_HUABAO_MACD_MIN = -0.05` 是**绝对元值**
# （MACD 由前复权序列算出、随价位等比缩放），于是「MACD 是否抬头」的判定跟股价水平
# 绑在一起：低价股 MACD 天然小，-0.05 相对它已是深水区，高价股则轻松过关。改成相对量
# `macd[-1] / close[-1]`（同一比值在整体等比缩放价格下不变），阈值 -0.0015。
# 依据（本机库 2026-09-28 全量实跑，`_huabao_early` 其余条件都过的 49 个候选）：
#   旧绝对口径放过 45 只；新相对口径 -0.0015 放过 44 只，仅 601825（close 8.61、
#   macd −0.0327）掉出 —— 它是被绝对口径「低价股宽进」放进来的。
#   换成相对口径能验证尺度不变：候选里整体 ×0.3 后绝对口径有 2 只翻转、相对口径 0 只。
#
# 回测（2026-10-08，`scripts/backtest_patterns.py --pattern huabao_early`，全池 4945 只
# × 2026-01~07，无未来函数、同票 20 日去重、基准 = 同日全市场平均）——
# 也是**没加板块闸门**那一版的数字（生产现在只收创业板 + 科创板）：
#
# | 形态 | 信号 | 5 日超额 | 10 日超额 | 20 日超额 | 60 日超额 | 胜率(5/10/20/60) |
# | --- | --- | --- | --- | --- | --- | --- |
# | 华宝早期 | 9917 | +0.02% | +0.35% | +0.43% | +0.35% | 47.1 / 48.5 / 42.4 / 30.4% |
#
# ⚠️ 与同批两个强达形态同读：**短周期略有指向、胜率不到 50%、四档中位数全负**。
# 它的定位本来就更早一档（只观察，真正动手要等走出「明天盯 → 明天预案」），
# 再加上我们**没做**它的资金流与分时两步（对方把「取不到资金流」当不淘汰处理），
# 所以一天能有近百只 —— 当观察池用，别当买点清单。
# ⚠️ 样本 2026-01~07 一段行情，只能横向比。

# 引擎至少要这么多根 K 线才动手（MA60 + 斜率窗口）
MIN_BARS = MA_PERIODS[-1] + MA_SLOPE_LOOKBACK

# ------------------------------------------------- 新增形态阈值（2026-09-25）
#
# 这一批按用户给的清单实现，**2026-09-25 补了回测**（`scripts/backtest_patterns.py
# --pattern all-new`：2995 只票 × 2026-01~07，无未来函数、同票 20 日去重、
# 以「同一天全市场平均收益」为基准）：
#
# ⚠️ **下表是 2995 只票那一版，已不是最新口径** —— 2026-09-27 扩到全池 5100 只
# 重跑后，有几个形态的结论变了（尤其量堆、地量见底）。**引用数字请看设计文档
# §8.68.25 那张全量表**，下表留着是为了对照「换口径前后差多少」。
#
# | 形态 | 信号 | 5日 | 10日 | 20日 | 60日 | 10日胜率 |
# | --- | --- | --- | --- | --- | --- | --- |
#
# ⚠️ **2026-10-18：量价底背离 / 矩形箱体 / 下降楔形已按用户要求删除** ——
# 下表里这三行的数字保留，只作「历史上跑出来过什么」的记录，不再代表在册形态。
# | 缩量涨停 | 138 | +5.38% | **+4.29%** | +0.83% | −9.82% | 49.3% |
# | V 型底 | 1766 | +1.54% | **+2.01%** | +0.49% | +0.70% | **53.3%** |
# | 周线多头 | 2622 | +1.00% | +1.74% | **+1.91%** | +1.07% | 48.5% |
# | 矩形箱体 | 2965 | +0.93% | +1.65% | **+2.13%** | +0.81% | 51.6% |
# | 向上跳空缺口突破 | 1619 | +1.10% | +1.61% | +1.00% | −1.96% | 48.1% |
# | 箱体突破 | 1466 | +0.74% | +1.35% | **+2.36%** | +0.96% | 47.3% |
# | 金叉共振 | 3533 | +0.73% | +1.26% | +0.81% | −1.15% | 47.1% |
# | 圆弧底 | 2384 | +0.56% | +1.05% | +1.52% | +0.05% | 48.7% |
# | 红三兵 | 2179 | +0.37% | +0.76% | +0.51% | −1.05% | 46.4% |
# | 上升通道 | 4619 | +0.76% | +0.75% | +0.46% | −0.81% | 43.1% |
# | 看涨吞没 | 2684 | +0.17% | +0.40% | +0.59% | −1.26% | 39.6% |
# | 启明星 | 5007 | +0.27% | +0.18% | +0.43% | −0.54% | 45.5% |
# | 阳包阴 | 7365 | +0.04% | +0.14% | +0.49% | −0.04% | 44.2% |
# | 倒锤子线 | 4728 | +0.35% | +0.11% | +0.27% | +1.27% | 44.4% |
# | 三重底 | 755 | +0.13% | +0.11% | −0.65% | −0.52% | 42.8% |
# | 下降趋势线突破 | 3197 | −0.27% | −0.27% | −0.60% | −2.08% | 49.2% |
# | 锤子线 | 4191 | −0.32% | −0.40% | +0.04% | +2.51% | 42.4% |
# | 地量见底 | 1901 | −0.36% | −0.43% | −0.81% | +0.37% | 53.1% |
# | ~~量堆~~ | 882 | −0.19% | −0.48% | −0.27% | −2.86% | 45.2% |  ← 2026-09-27 删除
# | 缺口回补 | 1742 | −0.29% | −0.54% | −1.07% | −1.01% | 45.3% |
# | 上升楔形 | 56 | +0.82% | −0.62% | −3.83% | −9.72% | 26.8% |
# | 均线粘合 | 980 | −0.54% | −0.87% | −0.55% | −3.68% | 41.5% |
# | 量价底背离 | 1979 | −0.48% | −1.15% | −1.45% | +0.24% | 39.2% |
# | 菱形 | 1337 | −0.55% | −1.52% | −2.61% | −2.83% | 40.6% |
# | 下降楔形 | 1191 | −0.81% | −1.67% | −2.43% | −2.89% | 46.7% |
# | 放量滞涨 | 58 | −2.38% | −2.54% | −5.71% | −7.08% | 32.8% |
#
# **怎么读这张表**（三档，别一刀切）：
#
# 1. **有超额、且胜率/中位也正**的 4 个：V 型底、矩形箱体、周线多头、箱体突破 ——
#    它们在自己那档持有期上是站得住的（周线多头与矩形箱体 20 日仍为正）。
#    ⚠️ 「周线多头」已于 2026-10-15 撤下、「矩形箱体」已于 2026-10-18 撤下（用户要求）
#    —— 这段里的名字**当时**是成立的，现在只剩 V 型底 / 箱体突破 两个。
#    缩量涨停的 10 日超额最高（+4.29%）但胜率只有 49%、中位 −0.35%，是**低胜率高赔率**，
#    且信号只有 138 条（最少），结论比其它几个脆，20 日之后开始回吐。
# 2. **超额接近 0（±0.5% 以内）**：启明星、看涨吞没、阳包阴、倒锤子线、三重底、锤子线 ——
#    蜡烛类单根/两根形态在这段样本里**没有预测力**（胜率普遍低于 50%、中位为负）。
#    它们当时仍留在清单里（用户点名要的），定位就是「按形状捞票」。
#    ⚠️ 其中 5 个**已于 2026-10-14 全部撤下**（启明星 / 锤子线 / 倒锤子线先撤，
#    看涨吞没 / 阳包阴同日再撤）；只有「三重底」留下 —— 它不属蜡烛类、另有指向性。
# 3. **负超额要分两种看**，混起来会得出相反结论：
#    - **警示类**（上升楔形 −0.62%/20日 −3.83%、放量滞涨 −2.54%/20日 −5.71%、菱形）：
#      负超额恰恰是「形态有效」的证据 —— 它们本来就该出现在高位/破位前，
#      用来提示风险，不是选买点。放量滞涨胜率 32.8%、上升楔形 26.8%，指向性很明确。
#      ⚠️ 原来的第四员「下降楔形」已 2026-10-18 撤下。
#    - **本该是买点的**（均线粘合 −0.87%、地量见底 −0.43%、量价底背离 −1.15%）：
#      这些的负超额说明「经典说法在这段样本里不成立」，看的时候要打折。
#      ⚠️ 其中「量价底背离」已 2026-10-18 撤下。
#
# ⚠️ **2026-09-27 重跑，口径变大，有几个结论跟着变**：上面那张表是 2995 只票的
# 样本；扩成**全池 5100 只 × 250 个交易日、165894 条信号**之后 ——
#
# | 形态 | 信号 | 10 日超额 | 10 日胜率 | 处置 |
# | --- | --- | --- | --- | --- |
# | 量堆 | 1522 | −1.74% | 40.5% | **删除** |
# | 三角收敛 | 306 | −1.08% | **31.0%** | **删除** |
# | 回踩不破 | 3083 | −0.86% | **35.9%** | **删除** |
# | 欧奈尔突破 | **0** | — | — | **删除**（一条信号都不出） |
#
# 判据：**负超额 + 本来就是买点定位 + 没有别的用途**，三条同时成立才删。所以
# 警示类（上升楔形 / 放量滞涨 / 菱形，负超额正是它们「有效」的证据）
# 与用户点名要的「按形状捞票」类（N 字选股、揉搓线、玉柱擎天、爆量后缩量回踩）
# 都留着 —— 后者的负超额是已知代价，不是新信息。形态数 48 → **44**。
# 完整表格与逐条理由见设计文档 §8.68.25。
#
# ⚠️ **样本局限必须一起看**：库里每只票只有 260 根日线，扣掉 80 根预热与 60 日前瞻，
# 实际只有 **2026-01 ~ 2026-07 这一段单一市场环境**（信号数虽大，但都在同一轮行情里）。
# 所以这些数字只能横向比较「哪个形态在这段行情里更有指向性」，不能当成长期能力。
# 要重跑见 `scripts/backtest_patterns.py`（`--pattern all-new` 跑这一批、`all` 跑全部）。
#
# 调参提醒：**别照着某一只票改这里的数字**。三段式与突破后横盘那两组是全市场扫描 +
# 回测校准出来的；这一批也走同一套流程 —— 先改阈值、再用上面的命令重跑，看表说话。

# 均线粘合（四条均线收敛到极窄区间、横住 → 蓄势）
SQUEEZE_DAYS = 5  # 要求粘合持续这么多天，只收敛一天是噪声
SQUEEZE_MAX_SPREAD = 0.03  # MA5/10/20/60 的 (max/min − 1) 上限
SQUEEZE_IDEAL_SPREAD = 0.008  # 收到这个宽度满分
SQUEEZE_SLOPE_MAX = 0.02  # 粘合期内 MA20 的涨幅上限（已经在拉就不是粘合）

# 金叉共振（MA5 上穿 MA10，且 MA10 / MA20 同向）
CROSS_LOOKBACK = 3  # 金叉要发生在最近这么多天内
CROSS_MIN_MA10_RISE = 0.0  # MA10 五日斜率下限
CROSS_MIN_MA20_RISE = -0.002  # MA20 允许略走平，但不能明显向下

# 下降趋势线突破
TRENDLINE_DAYS = 60
TRENDLINE_MIN_PIVOTS = 2  # 至少两个下降的摆动高点才画得出趋势线
TRENDLINE_MAX_EXCESS = 0.08  # 突破幅度上限：追太多就不是买点

# 向上跳空缺口突破
