#  `BOX_TOUCH_TOL` / `BOX_MIN_TOUCHES` 仍被「箱体突破」使用，保留）。

# 楔形（收敛三角形；上升楔形偏空）
WEDGE_DAYS = 50
WEDGE_MIN_DAYS = 30
WEDGE_MIN_SLOPE = 0.0004  # 两轨斜率绝对值的下限，再平就是箱体
WEDGE_MIN_CONVERGE = 0.55  # 收敛比例下限 (起始间距 − 结束间距) / 起始间距
WEDGE_TOUCH_TOL = 0.03  # 轨被触碰的容差
WEDGE_MIN_TOUCHES = 3  # 每条轨至少被碰这么多次（真楔形的高/低点会反复贴轨）
# 下降楔形 2026-10-18 已删除（连同 `WEDGE_FALL_*` 两个专属阈值）。

# 菱形（先扩张后收敛）
DIAMOND_DAYS = 70
DIAMOND_MIN_DAYS = 45
DIAMOND_MIN_EXPAND = 0.25  # 前半段振幅扩张比例下限
DIAMOND_MIN_CONTRACT = 0.4  # 后半段振幅收敛比例下限
DIAMOND_MIDDLE_EDGE = 1.6  # 中段振幅至少要达到两端的这个倍数（不然只是普通波动）

# ---- 2026-10-18 候选策略（移植自 myhhub/stock，**回测通过前不进生产**）----
#
# 这一批的定义来自 InStock 的「策略选股」文档，先原样实现跑全量回测，
# 数字出来之后再决定留谁 —— 不要因为它们出自别的项目就默认有效。
# 「无大幅回撤」没有单独做成形态：它是一个**过滤条件**（60 日涨幅 <60% 且没有
# 单日/两日大跌），单独当形态会命中上千只、没有区分度。

# 停机坪：放量大涨后连续 3 天高开小阳整理
PARKING_SURGE_PCT = 9.5
PARKING_SURGE_VOL = 2.0  # 大涨日量 / 前 5 日均量
PARKING_FLAT_DAYS = 3
PARKING_FLAT_BODY_MAX = 0.03  # 收盘与开盘相差 <3%
PARKING_FLAT_PCT_MAX = 5.0  # 整理日涨跌幅绝对值上限

# 回踩年线：突破 MA250 后回踩缩量、不破年线
MA250_PULLBACK_WINDOW = 60  # 在最近这么多天里找阶段高点与回踩低点
MA250_PULLBACK_MIN_GAP = 10  # 高点 → 回踩低点至少隔这么多天
MA250_PULLBACK_MAX_GAP = 50
MA250_PULLBACK_MIN_SHRINK = 2.0  # 高点日量 / 回踩低点日量
MA250_PULLBACK_MIN_DEPTH = 0.2  # 回踩低点 / 高点收盘 < 0.8
MA250_PULLBACK_RECENT = 5  # 回踩低点距今天不超过这么多天

# 低 ATR 成长：波动收敛 + 10 日重心上移
LOW_ATR_DAYS = 14
LOW_ATR_MAX = 0.04  # ATR14 / 收盘价
LOW_ATR_RANGE_DAYS = 10
LOW_ATR_MIN_RANGE = 0.10  # 10 日 (最高收盘 / 最低收盘 − 1)
LOW_ATR_TREND_DAYS = 10  # MA20 斜率窗口

# 放量跌停（**警示类**，不是买点）
VOL_LIMIT_DOWN_PCT = -9.5
VOL_LIMIT_DOWN_MIN_AMOUNT = 2e8
VOL_LIMIT_DOWN_VOL_MULT = 4.0


# 蜡烛形态（单根 / 两根 / 三根）
CANDLE_BODY_MAX = 0.35  # 小实体：实体 / 全日振幅 的上限
CANDLE_PRIOR_DAYS = 5
# 2026-10-18 的 K 线确认实验（清单 #3）从删除前那一版取回的三条：
# 它们**只服务于** `_bullish_engulf_confirm`（金叉大阳的确认标签），
# **不注册独立蜡烛形态**。判定与 `scripts/backtest_patterns.py` 里那份逐字一致。
CANDLE_PRIOR_DROP = 0.03  # 前置下跌幅度：反转类蜡烛要在跌势之后出现才有意义
ENGULF_MIN_BODY = 1.3  # 今日实体 / 昨日实体 的下限
ENGULF_MIN_CLOSE_POS = 0.6  # 今日收盘要落在全日振幅的这个位置以上
# 2026-10-14 撤下「看涨吞没 / 阳包阴」时，一并删了只被它们用到的三个阈值：
# `CANDLE_MIN_BODY`（实体不能是十字星的下限）、`CANDLE_PRIOR_DROP`（前置跌幅）、
# `ENGULF_MIN_BODY` / `ENGULF_MIN_CLOSE_POS`（今日实体倍数与收盘位置）。
# 2026-10-18 其中三条按 K 线确认实验的结论重新加回（见上），只给「金叉大阳」的
# `candle_confirm` 标签用；`CANDLE_MIN_BODY` 仍然没有回来。
# 「实体不能是十字星」这条思路如今只剩 `KNEAD_MIN_BODY`（揉搓线）在用，同值 0.05。
SOLDIER_MIN_BODY = 0.3  # 红三兵每根实体占振幅的下限
SOLDIER_MAX_SHADOW = 0.35  # 每根上影线占振幅的上限
SOLDIER_MIN_GAIN = 0.03  # 三根累计涨幅下限
# 揉搓线（两根 K 的组合）—— 2026-09-27 用户给的定义，2026-10-14 按用户新标准重写
#
# 昨天长上影、今天长下影，两根都是小实体，合起来像一根十字线（螺旋桨）。
# **顺序不能反**（用户两次点名强调）：先长下影、后长上影是另一回事，所以判据分别落在
# 昨天（长上影）与今天（长下影）上，见 `_kneading_line`。
#
# 规模（2026-10-14 重算，新口径）：20cm 1877 只 × 260 个交易日共 **1374 条**（20 日去重后），
# 约 5.3 条/天 —— 是「一份清单」的规模，不是稀有信号。
#
# 回测（`scripts/backtest_patterns.py --pattern kneading_line --board wudao`，2026-10-14）：
#
# | 持有 | 信号 | 均值 | 中位 | 胜率 | 超额 |
# | --- | --- | --- | --- | --- | --- |
# | 5 日 | 1374 | −1.17% | −1.50% | 40.9% | −0.19% |
# | 10 日 | 1374 | −1.07% | −2.30% | 41.5% | **+0.01%** |
# | 20 日 | 1374 | −1.86% | −5.26% | 36.3% | +0.21% |
# | 60 日 | 1374 | −2.43% | −8.90% | 33.1% | +0.51% |
#
# ⚠️ **结论与其它蜡烛形态一致：短周期没有预测力**（胜率 41%、中位 −2.3%、超额≈0），
# 20 / 60 日才略微转正。所以它的定位就是「按这个形状捞一批票自己看」，别当买点信号用。
# 这次重写（2026-10-14）按用户给的标准把形状判据改对了、也把众生药业那一对捞了进来，
# 但**超额并没有变好**（10 日 −0.19% → +0.01%，20 日 +0.75% → +0.21%）——
# 这是判据的固有性质，不是阈值没调好。
# 2026-10-14 那三处改动的要点（理由与实测见上面那段）：删掉「收盘相近」否决
# （众生那一对是 1.2016%，擦边 1.2% 被卡掉）、主影改按振幅算、去掉冗余的「另一侧影短」。
KNEAD_LONG_SHADOW = 0.5  # 主影线（昨天的上影 / 今天的下影）占振幅的下限
# 实体占振幅的**下限**：实体要看得见，不能是十字星。
# ⚠️ 这条是必需的，不是保险：只判上界（≤ `CANDLE_BODY_MAX`）的话，实体趋近 0 的样本
# 也能满足「主影 ≥ 振幅一半」并排到列表最前 —— 实测过。
# 也不能写成 `body <= 0` 排除十字星：前复权把「开 = 收」算成 `open × (net/close)`，
# 真实数据上几乎必然是 1e-13 这种尾巴，位精确比较挡不住（2026-09-27 修）。
KNEAD_MIN_BODY = 0.05

# 金叉大阳（2026-10-10 用户给的通达信公式，原样落成生产函数）
#
#   买入:=CROSS(MA(C,3),MA(C,5)) AND 涨幅>=4 AND RSI6<60 AND 上影/振幅<=0.2;
#
# 四条是**布尔与**，命中即成立，所以底分给 60（高过 MIN_SCORE=50）、余下 40 分按
# 「过线多少」分级，只用来排序 —— 否则每个命中都是同一个分数，清单没法看。
#
# 回测（`scripts/backtest_patterns.py --pattern ma_cross_big_yang --board wudao`，
# 2026-10-10，1908 只 · 250 个交易日 · 559 条信号）：
#
# | 持有 | 信号 | 均值 | 中位 | 胜率 | 超额 |
# | --- | --- | --- | --- | --- | --- |
# | 5 日 | 559 | −0.89% | −1.50% | 39.0% | −0.13% |
# | 10 日 | 559 | 0.00% | −0.78% | 47.2% | +1.15% |
# | 20 日 | 559 | −0.86% | −4.00% | 40.3% | +1.38% |
# | 60 日 | 537 | +1.30% | −7.87% | 37.6% | +2.49% |
#
# 同池同窗口的同类对比（10/20/60 日超额）：金叉共振 +0.35 / −0.07 / −0.95、
# 玉柱擎天 +0.10 / +0.53 / +1.99、放量上涨 −0.45 / −0.32 / −0.71 —— 三个都比它差。
# ⚠️ 但四档**中位数全负、胜率不到 50%**，收益是右尾驱动（最好 10 日 +82.5%、
# 60 日 +213%），所以定位与「洗后可盯」同档：一份清单，不是买点信号。
GCB_GAIN_MIN = 0.04  # 信号日涨幅门槛（公式里的 4%）
GCB_GAIN_IDEAL = 0.08  # 涨幅到这给满分（单边）
GCB_RSI_MAX = 60.0  # RSI6 上限（公式里的「低 RSI」）
GCB_RSI_IDEAL = 45.0  # RSI6 低到这给满分
GCB_UPPER_MAX = 0.2  # 上影 / 振幅 的上限（公式里的「短上影」）
GCB_MIN_BARS = 30  # 够算 MA5 与 Wilder RSI6 的预热
# 公式里分母写的是 `H-L+0.0001`（防一字板除零），这里照抄 —— 不加这个的话
# 振幅为 0 的样本会除零，整只票的扫描会抛异常
GCB_SPAN_EPS = 0.0001

# 做T买点（2026-10-10 用户给的「V5 日线做T」主图公式）
#
# 原式是一张主图叠加指标，同时有买（深B / ★B / 双B）和卖（卖T）两侧。**这里只落
# 买方向**：站点扫的是「今天有什么买点」，卖出侧是持仓纪律、要看自己手里的票，
# 不属于全市场扫描。三档是层层包含的（双B ⊂ ★B ⊂ 深B），一根 K 线只报最高那档。
#
# 回测（`python scripts/backtest_patterns.py --pattern t_buy`，
# 4945 只 · 260 个交易日 · 5250 条信号）：
#
# | 持有 | 信号 | 均值 | 中位 | 胜率 | 基准均值 | 超额 |
# | --- | --- | --- | --- | --- | --- | --- |
# | 5 日 | 5250 | −1.53% | −2.48% | 34.0% | −1.08% | −0.46% |
# | 10 日 | 5249 | −2.44% | −4.17% | 34.4% | −2.72% | +0.28% |
# | 20 日 | 5248 | −6.19% | −8.19% | 28.1% | −6.64% | +0.45% |
# | 60 日 | 5062 | −4.98% | −5.74% | 34.7% | −6.76% | +1.78% |
#
# ⚠️ **四档中位数全负、胜率 28~35%，只有 10/60 日超额微正** —— 它是个「越跌越买」
# 的清单，与「均线粘合 / 地量见底」同档，**别当买点信号用**。样本区间（2026-04~07）
# 是单边下跌，基准 5/20/60 日 −1.1%/−6.6%/−6.8%，抄底型信号在这段天生吃亏；
# 但中位比基准还低 1.4~1.6 个点，说明不只是行情的原因。
# 原式是用户点名要的，先按它落库；收紧方案（只留 ★B/双B、或给底背离补一条
# 「MA20 走平/上翘」）等看过实际命中再定。明细里的 `tier` 只改排序分、不改命中
# —— 三档层层包含，见 `_t_buy`。
T_BUY_MIN_BARS = 150  # 120 日背离窗 + 5 日观察窗 + EMA26 预热，再留余量
T_BUY_DIVERGE_DAYS = 120  # 原式的 `C120L / DIF120L / V120H` 那一档窗口
T_BUY_OBSERVE_DAYS = 5  # `SUM(底观察,5)>0`
T_BUY_CROSS_DAYS = 3  # `EXIST(MA3金叉MA5,3)`
T_BUY_NEAR_TOL = 0.02  # 贴近 120 日新低：`C<=C120L*1.02`
T_BUY_SHORT_TOL = 0.01  # 短窗那两档的容差：`*1.01`（低）/ `*0.99`（高）
T_BUY_DIF_RATIO = 0.85  # 背离时的 DIF 比较系数（`DIF>DIF120L*0.85`）
T_BUY_VOL_RATIO = 0.5  # 背离时量能要缩到同窗最高量的这个比例以下
T_BUY_HIST_RATIO = 0.8  # MACD 柱背离系数（原式直接写的 0.8，与 DIF 那档不同）
T_BUY_GAP_DIP = -2.0  # 底背要求的乖离上界（必须在 MA20 下方）
T_BUY_GAP_BASE = -3.0  # 基买的乖离上界（比底背更深）
# 乖离掉到这个深度，档位分之外的那 16 分给满（只影响排序）。
# ⚠️ 2026-10-10 从 −8 收到 −12：10-09 那天的命中里，`双B + 距MA20 ≤ −8%` 直接撞到
# 100.0 分并列，榜内前段没有区分度 —— 满分区下移之后榜单才排得开（上限 96）。
T_BUY_GAP_IDEAL = -12.0
T_BUY_STRONG = 5.0  # 强空/强多的分界（`涨幅<-5%` 时不给双零金与基买）
T_BUY_OVERDROP = -15.0  # 超跌：乖离阈值
T_BUY_SHRINK = 0.7  # 缩量：量 < 20 日均量 × 该系数
T_BUY_MACD_DAYS = 30  # `COUNT(金叉 AND DIF<0,30)` 的窗口
T_BUY_MACD_REPEAT = 2  # 该窗口内至少金叉这么多次才算「零下二金」
T_BUY_COOLDOWN = 5  # 买点冷却（低于这个间隔的重复信号丢掉）
T_BUY_COOLDOWN_DEEP = 7  # 超跌状态下的冷却（原式 `IF(超跌,7,5)`）
T_BUY_BASE_SCORE = 60.0  # 命中即入库（> MIN_SCORE），后 36 分（档位 20 + 乖离 16）只用于排序
T_BUY_GAP_SCORE = 16.0  # 乖离那一档最多贡献的分
#: 三档的相对强弱：深B 是全集、★B 多一条 MA3 上穿 MA5、双B 要求就穿在今天。
#: ⚠️ 2026-10-10 从 0/12/24 收到 0/10/20：原来 60+24+16 正好压在 100，让「双B + 深乖离」
#: 一片并列满分。收窄之后同上限只到 96，留出区分空间（档位仍是排序用的，不改是否命中）。
T_BUY_TIER_SCORE = {"深B": 0.0, "★B": 10.0, "双B": 20.0}

# ---- ⚠️ 「上涨结构内的 B 点」（`up_structure_b`）：2026-10-14 新增，**同日撤下** ----
#
# 原口径（用户给的，以近岸蛋白为例）：缩量下跌后放量起涨，随后走出一串「上涨结构」——
# 每一段的高点高于前一段的高点、低点也高于前一段的低点；选「在第 1 或第 2 段里出过
# B 点」的票（B 点 = 用户「V5 日线做T」主图里的 深B / ★B / 双B，见 `t_buy_state`）。
#
# **留这段是为了别再有人照原定义做一遍** —— 判据、阈值、实现全删了（`git log` 里
# 找 `81dc5be` 与撤下那一笔）。全量回测 + 参数寻优都证明它不成立：
#
# 新口径下的实测（见 `PATTERNS` 上方那张全量表的同名行）：10 日超额 **−2.99%**、
# 10 日胜率 **23.3%**、10 日中位 −8.45%（219 条），56 个形态里**倒数第二**。
#
# 参数寻优（摆动阈值倍数 1.2~2.6 × 段数上限 1/2 × B 点档位 全档/★B+双B/仅双B，30 组）：
#
# | 10日超额 | 倍数 | 段数 | 档位 | 信号 | 胜率 |
# | --- | --- | --- | --- | --- | --- |
# | **−0.37%**（最好） | 1.2 | 2 | 全档 | 535 | 31.6% |
# | −0.59% | 1.2 | 1 | 全档 | 465 | 29.0% |
# | −1.05% | 1.5 | 1 | 全档 | 298 | 28.5% |
# | −2.47% | 2.2 | 1 | 全档 | 105 | 29.5% |
# | −2.99%（当时现值） | 1.8 | 2 | 全档 | 219 | 23.3% |
# | −3.74%（最差） | 2.2 | 2 | 仅双B | 53 | 24.5% |
#
# **30 组全负**，10 日胜率全落在 22%~32%（掷硬币是 50%）。而且**倍数越小反而越好**：
# `mult=1.2` 的 −0.37% 已经贴到 `t_buy` 自己的 −0.36%（1699 条）—— 说明负超额来自
# **B 点本身**，「上涨结构」这层过滤只是把它挑得更差。
#
# **要救得动 B 点的定义**（那是 `t_buy` 的事），别再在这类「结构过滤」上调参。


# ---------------------------------------------------------------- 数据结构


@dataclass(slots=True)
class Bars:
    """一只票的日线序列，价格**已前复权**、按交易日升序。"""

    dates: list[date]
    open: np.ndarray
    high: np.ndarray
    low: np.ndarray
    close: np.ndarray
    volume: np.ndarray
    amount: np.ndarray
    pct_chg: np.ndarray
    #: 六位股票代码。**只有少数形态用得上**（「知行超级B1」要按代码前缀判 20cm 板块），
    #: 所以默认空串 —— 个股页的 K 线取数、阶段判定那几处不跑形态，不传也不会报错；
    #: 扫描与回测会传（见 `scan_patterns` / `scripts.backtest_patterns`）。不传时
    #: 依赖代码的判据会退化成「只按非代码条件判」，所以**能传就要传**。
    code: str = ""

    def __len__(self) -> int:
        return int(self.close.size)


@dataclass(slots=True)
class Signal:
    """一个形态的命中结果。"""

    pattern: str
    score: float
    key_levels: dict[str, float] = field(default_factory=dict)
    #: 明细字段基本是数字，但「档位 / 触发」这类短标签直接给 str 更省事 ——
    #: 前端 `detailText` 对非数字原样透传。
    detail: dict[str, float | int | str] = field(default_factory=dict)


@dataclass(frozen=True, slots=True)
class Pattern:
    key: str
    name: str
    # 趋势 / 突破 / 量价 / 几何
    group: str
    detect: Callable[[Bars], Signal | None]


# ---------------------------------------------------------------- 复权


#: 一行日线要能当「一根 K 线」用，这几个字段都必须有值。
#: iFinD 对停牌日会给一行「只有收盘价、其余全空」的**残行**，`build_bars` 里
#: `float(r["open"])` 遇到它直接抛 `TypeError`（`float(None)` 不行）。
BAR_REQUIRED_FIELDS = ("open", "high", "low", "close", "pct_chg")


def usable_bar(bar: dict) -> bool:
    """一行日线能不能当一根 K 线用：`BAR_REQUIRED_FIELDS` 五项都要非空。

    2026-10-10 从 `services.stock_phase.load_phase` 抽成公共函数，供三处共用
    （`scan_patterns._load_bars` / `scripts.backtest_patterns._load_history` /
    `stock_phase.load_phase`）—— 原来那两处只滤 `close / pct_chg` 两项，遇到
    「收盘价有值、开高低为空」的残行会把 `None` 喂进 `build_bars`，整轮扫描崩掉；
    `load_phase` 那一处本来就滤了五项（注释写明「`float(None)` 会直接抛 500」），
    以它为准统一。调用方要先把自己的行**转成 dict** 再传进来。
    """
    return all(bar.get(field) is not None for field in BAR_REQUIRED_FIELDS)


def build_bars(records: list[dict], code: str = "") -> Bars:
    """把一只票的**不复权**日线记录转成前复权序列。

    `records` 必须按交易日升序，每项含 `date / open / high / low / close /
    volume / amount / pct_chg`（值为 None 的请调用方先过滤掉）。

    `code` 原样存进 `Bars.code`，只有「知行超级B1」这类要按代码前缀判板块的形态用得上
    （见 `Bars.code`）。

    ## 为什么用涨跌幅而不是「前复权价」

    iFinD 不给前复权价，但 `涨跌幅` 是**已按除权调整的真实收益率**（实测验证过
    21 个银行除权日）。所以：

    - 收盘序列：`net[i] = net[i-1] * (1 + pct[i]/100)`，即真实收益的复利
    - 当日 OHLC：用**当天收盘价**做基准换算 —— `adj_x[i] = x[i] * net[i] / close[i]`

    第二步只能按天内的比例换算，不能乘一个累计因子。因为除权调整发生在
    当日开盘相对昨日收盘之间，**同一根 K 线内部的四个价格本来就在同一个基准上**；
    乘累计因子会把整根 K 线一起挪走，反而制造出一个假的跳空。

    锚点取「最新一根的收盘价」：前复权的通行定义就是以最新价为基准，
    这样最近的关键位（突破价等）可以直接当作真实价格看。

    ## 成交量也要按同一比例缩放

    ⚠️ 价格前复权了、量却用原始值，会让「量比」在送转之后整体虚高（10 转 10 约翻倍），
    凭空触发放量类形态、又把缩量类压掉（2026-10-10 修）。除权日股本变了，绝对量本来就
    不该直接跨日比。做法与个股接口 `_adjusted(vol_adjust=True)` 同一口径：
    **量 ÷ (复权价 / 原始价)**（= `volume / ratio`）—— 除权日之后复权价相对原始价缩小，
    量相应放大，跨除权日才可比。成交额 `amount` **不缩放**（钱是钱，与接口一致）。
    """
    if not records:
        raise ValueError("build_bars 收到空序列")

    close = np.array([float(r["close"]) for r in records], dtype=float)
    pct = np.array([float(r["pct_chg"] or 0.0) for r in records], dtype=float)

    # 首日没有涨跌幅，净值从 1 起算
    net = np.empty(len(records), dtype=float)
    net[0] = 1.0
    if len(records) > 1:
        net[1:] = np.cumprod(1.0 + pct[1:] / 100.0)
    # 锚到最新价：adj[-1] == 原始收盘价
    net *= close[-1] / net[-1]

    # 日内比例换算。close 理论上不会为 0，真出现就整根丢掉意义，直接置 1 避免除零
    ratio = np.divide(net, close, out=np.ones_like(net), where=close != 0)
    # 成交量按同一比例**反向**缩放（见 docstring）。ratio 为 0 是病态数据，退回 1 别除爆
    volume_ratio = np.where(ratio != 0, ratio, 1.0)

    return Bars(
        dates=[r["date"] for r in records],
        open=np.array([float(r["open"]) for r in records]) * ratio,
        high=np.array([float(r["high"]) for r in records]) * ratio,
        low=np.array([float(r["low"]) for r in records]) * ratio,
        close=net,
        volume=np.array([float(r["volume"] or 0.0) for r in records]) / volume_ratio,
        amount=np.array([float(r["amount"] or 0.0) for r in records]),
        pct_chg=pct,
        code=code,
    )


# ---------------------------------------------------------------- 打分工具


def _gate_score(value: float, gate: float, ideal: float) -> float:
    """「过了门槛就给分，到理想值满分」的线性映射，方向由 `gate` 与 `ideal` 的大小决定。

    - `ideal < gate`：越小越好（缩量幅度、回撤深度、两底差距…）
    - `ideal > gate`：越大越好（恢复比例、收回力度…）

    和 `_band_score` 的分工：有两个方向都扣分的用 `_band_score`（乖离率、放量倍数
    —— 太弱不行、太强也不行）；只有一个方向的用这个。

    **不要把 `gate` 当成满分点**：那样刚过门槛的样本会直接拿 0 分，等于把
    「能接受的最差值」和「理想值」混成一件事。实测这么写会让一个形态的命中
    从 80 只掉到 16 只（当时测的是「回踩不破」，该形态 2026-09-27 已删）——
    分数低到进不了库，而不是判定变严了。
    """
    if gate == ideal:
        return 1.0
    if ideal < gate:  # 越小越好
        if value >= gate:
            return 0.0
        if value <= ideal:
            return 1.0
        return (gate - value) / (gate - ideal)
    if value <= gate:  # 越大越好
        return 0.0
    if value >= ideal:
        return 1.0
    return (value - gate) / (ideal - gate)


def _band_score(value: float, low: float, high: float, cap: float) -> float:
    """把「理想区间」映射到 0~1：区间**中心给满分**，两端降到 `EDGE_SCORE`，
    区间外线性衰减，`cap` 之外归零。

    为什么区间内不一律给满分：实测「放量上涨」的 80 只里，有 64 只同时落在
    涨幅 3~10% 且量比 2~6 的理想区间，于是全部并列 100 分 —— 排名就失去意义了。
    改成余弦钟形后中心唯一最高，既能分辨「教科书级」和「刚够格」，
    又不改变「落在区间里都算不错」的语义。

    **`high` 必须严格小于 `cap`。** 两者相等时区间上界恰好也是衰减终点，
    值正好落在那里会走 `value >= cap` 分支拿 0 分 —— 而那恰恰是最优值。
    这个坑我踩过 6 次（如「收盘从未跌破 MA20」得 0 分），单方向的打分一律用
    `_ramp`，别用这个。

    ⚠️ **「越接近区间中段越好」就把量本身传进来，别自己拼 `span - abs(x - mid)`。**
    那个量的最大值（正好落在中段时）是 `span`，而 band 的上界若写成 `span*0.8`，
    最优样本会被当成「过大」衰减 —— 分数变成**中间低、两边高**的 U 形，与「中段最好」
    正好相反，而且从结果里看不出来。缩量回踩与杯柄都这么错过（2026-09-27 修）。
    修完实测（1200 只样本）：缩量回踩信号 413 → 452 条，5/20/60 日超额基本不变；
    杯柄 11 → 13 条（样本太小，超额差异是噪声）。方向对、量级可控。
    """
    if value <= 0:
        return 0.0
    center = (low + high) / 2
    if low <= value <= high:
        return EDGE_SCORE + (1.0 - EDGE_SCORE) * math.cos(
            (value - center) / (high - low) * math.pi
        )
    if value < low:
        return EDGE_SCORE * (value / low)
    if value >= cap:
        return 0.0
    return EDGE_SCORE * (cap - value) / (cap - high)


def _ma_series(values: np.ndarray, window: int) -> np.ndarray | None:
    """滑动均值序列，长度 = len(values) - window + 1。数据不足返回 None。"""
    if values.size < window:
        return None
    cumulative = np.concatenate([[0.0], np.cumsum(values)])
    return (cumulative[window:] - cumulative[:-window]) / window


def _align(series: np.ndarray | None, window: int, length: int) -> np.ndarray:
    """把均线序列对齐到 K 线的索引，前面不足的部分填 NaN。

    对齐后 `result[i]` 就是第 i 根 K 线的均线值，省得每个形态各写一遍索引换算。
    """
    out = np.full(length, np.nan)
    if series is None:
        return out
    usable = min(series.size, length - window + 1)
    if usable > 0:
        out[window - 1 : window - 1 + usable] = series[:usable]
    return out


def _rolling(values: np.ndarray, window: int, mode: str) -> np.ndarray:
    """滑动窗口归约，**对齐到窗口右端**：`out[i]` 是 `values[i-window+1 … i]` 的归约值，
    前面不够 window 根的部分填 NaN。

    `mode` 取 `min` / `max` / `sum`，就是通达信的 `LLV` / `HHV` / `SUM`。窗口内的
    NaN 会传染（`min`/`max`/`sum` 都返回 NaN），这与 `_ma_series` 的口径一致：
    数据不够就是不够，不假装算得出来。
    """
    out = np.full(values.size, np.nan)
    if values.size < window:
        return out
    windows = np.lib.stride_tricks.sliding_window_view(values, window)
    if mode == "min":
        out[window - 1 :] = windows.min(axis=1)
    elif mode == "max":
        out[window - 1 :] = windows.max(axis=1)
    else:
        out[window - 1 :] = windows.sum(axis=1)
    return out


def _shift(values: np.ndarray, bars: int) -> np.ndarray:
    """`REF(values, bars)`：整体后移 `bars` 根，前面补 NaN。"""
    out = np.full(values.size, np.nan)
    if bars < values.size:
        out[bars:] = values[: values.size - bars]
    return out


def _cross(fast: np.ndarray, slow: np.ndarray) -> np.ndarray:
    """`CROSS(fast, slow)`：今天 `fast > slow` 且昨天 `fast <= slow`。

    NaN 参与比较恒为 False，所以预热段自然不算金叉。
    """
    out = np.zeros(fast.size, dtype=bool)
    out[1:] = (fast[1:] > slow[1:]) & (fast[:-1] <= slow[:-1])
    return out


def _barslast(flags: np.ndarray) -> np.ndarray:
    """`BARSLAST(flags)`：距上一次成立（含当根）的周期数。

    **从未成立过返回 `inf`。** 公式里它只用在「上次信号距今 > 冷却天数」这一处，
    `inf` 就等于「冷却已满足」—— 第一次出现当然该算信号，不该被冷却挡住。
    """
    out = np.full(flags.size, np.inf)
    last = -1
    for i in range(flags.size):
        if flags[i]:
            last = i
        if last >= 0:
            out[i] = i - last
    return out


def _count(flags: np.ndarray, window: int) -> np.ndarray:
    """`COUNT(cond, N)` 铺成整条序列：`out[i]` = `flags[i-N+1 … i]` 里成立了几根。

    就是 `_rolling(flags.astype(float), N, "sum")`，包一层只是让调用处仍照着公式写
    `COUNT(...)`、省掉每处一遍 `astype(float)`。窗口不足 N 根的前几根是 NaN，
    参与比较恒为 False（与 `_rolling` 同口径）。
    """
    return _rolling(flags.astype(float), window, "sum")


def _every(flags: np.ndarray, window: int) -> np.ndarray:
    """`EVERY(cond, N)` 铺成整条序列：最近 N 根是否**都**成立。"""
    return _rolling(flags.astype(float), window, "sum") >= window


def _hhvbars(values: np.ndarray, window: int) -> np.ndarray:
    """`HHVBARS(X,N)` 铺成整条序列：每根上「窗口内最高值距它多少根」（0 = 当根最高）。

    前 `N-1` 根数据不足填 NaN（与 `_rolling` 同口径）。「知行超级B1」拿它当**逐根**的
    位移（`REF(C,VDAY)` 里的 `VDAY`），所以不能只算最后一个点。
    """
    out = np.full(values.size, np.nan)
    if values.size < window:
        return out
    windows = np.lib.stride_tricks.sliding_window_view(values, window)
    out[window - 1 :] = window - 1 - windows.argmax(axis=1)
    return out


def _sma(values: np.ndarray, n: int, m: int) -> np.ndarray:
    """通达信 / 同花顺的 `SMA(X,N,M)`：`Y[i] = (M*X[i] + (N-M)*Y[i-1]) / N`。

    与 `_ema`（`alpha = 2/(span+1)`）不是一回事，别混用：KDJ 的 `K`/`D` 与
    「知行超级B1」的 3 日 RSI 用的都是这个带权递推。首个**有效**样本直接当初值，
    之前的填 NaN；NaN 不参与递推（保持上一个值）—— 否则一个一字板让 `RSV` 的分母
    为 0，后面整条 KDJ 都会变成 NaN。

    ⚠️ 3 日 RSI 等价于 `_wilder_rsi(close, 3)`（`SMA` 是线性的，分母
    `SMA(ABS(涨跌),3,1) = SMA(涨,3,1) + SMA(跌,3,1)`），两处口径已经对齐。
    """
    out = np.full(values.size, np.nan)
    if values.size == 0:
        return out
    weight = m / n
    prev = np.nan
    for i in range(values.size):
        x = float(values[i])
        if not math.isfinite(x):
            out[i] = prev
            continue
        prev = x if not math.isfinite(prev) else weight * x + (1.0 - weight) * prev
        out[i] = prev
    return out


def _rising(series: np.ndarray, lookback: int) -> bool:
    return series.size > lookback and series[-1] > series[-1 - lookback]


def _trailing_run(flags: np.ndarray) -> int:
    """从尾部往前数，连续的 True 有多少个。"""
    count = 0
    for flag in flags[::-1]:
        if not flag:
            break
        count += 1
    return count


def _safe_mean(values: np.ndarray) -> float:
    finite = values[np.isfinite(values)]
    return float(finite.mean()) if finite.size else 0.0


def _volume_ratio(bars: Bars, window: int) -> float:
    """当日成交量 / 前 window 日均量。"""
    if len(bars) < window + 1:
        return 0.0
    base = _safe_mean(bars.volume[-window - 1 : -1])
    return float(bars.volume[-1] / base) if base > 0 else 0.0


# ---------------------------------------------------------------- 形态实现


def _ma_bull(bars: Bars) -> Signal | None:
    """均线多头排列：MA5>MA10>MA20>MA60，且四条均线近期都在向上。"""
    if len(bars) < MIN_BARS:
        return None

    series = [_ma_series(bars.close, period) for period in MA_PERIODS]
    if any(item is None for item in series):
        return None

    # 四条均线起止日期不同，取公共长度后再比大小
    shared = min(item.size for item in series if item is not None)
    if shared <= MA_SLOPE_LOOKBACK:
        return None
    m5, m10, m20, m60 = (item[-shared:] for item in series if item is not None)

    stacked = (m5 > m10) & (m10 > m20) & (m20 > m60)
    if not stacked[-1]:
        return None
    if not all(_rising(item, MA_SLOPE_LOOKBACK) for item in (m5, m10, m20, m60)):
        return None

    days = _trailing_run(stacked)
    spread = float((m5[-1] - m60[-1]) / m60[-1])
    gap = float((bars.close[-1] - m20[-1]) / m20[-1])

    score = min(days, MA_STACK_FULL_DAYS) / MA_STACK_FULL_DAYS * 40
    score += _band_score(spread, *MA_SPREAD_IDEAL, MA_SPREAD_CAP) * 30
    score += _band_score(gap, *MA_GAP_IDEAL, MA_GAP_CAP) * 30

    return Signal(
        "ma_bull",
        score,
        {"support": float(m20[-1]), "ma5": float(m5[-1]), "ma10": float(m10[-1])},
        {"stack_days": days, "spread": round(spread, 4), "gap": round(gap, 4)},
    )


def _new_high(bars: Bars) -> Signal | None:
    """创 N 日新高：收盘价高于前 N 根 K 线的最高收盘价，取命中的最长周期。"""
    for window in NEW_HIGH_WINDOWS:
        usable = min(window, len(bars) - 1)
        if usable < NEW_HIGH_MIN_WINDOW:
            continue
        # ⚠️ 历史长度不够这个档时**不能**照给它的基础分（2026-10-10 修）：61 根的次新股
        # 创 60 日新高，若套 250 日档的 92 分会凭空挤进「评分前 50」，污染胜率样本；老股
        # 同样只是 60 日新高、只拿 55。差 1 根仍放行（库里历史正好 250 根 → 250 日档实际
        # 按 249 根判，见顶部常量注释），差更多就说明根本没这么长的历史，跳过这把档。
        if window - usable > 1:
            continue
        prior = float(bars.close[-usable - 1 : -1].max())
        if bars.close[-1] <= prior:
            continue

        excess = float(bars.close[-1] / prior - 1)
        ratio = _volume_ratio(bars, 5)
        score = NEW_HIGH_BASE[window]
        score += _band_score(excess, 0.005, 0.03, 0.10) * 4
        # 量能按连续量给分，而不是「过 1.2 倍就 +3」的开关 ——
        # 后者会让所有放量的新高票挤在同一个分数上，榜首失去区分度
        score += min(ratio / 3.0, 1.0) * 4
        return Signal(
            "new_high",
            min(score, 100.0),
            {"breakout": prior},
            {"window": usable, "excess": round(excess, 4), "vol_ratio": round(ratio, 2)},
        )
    return None


def _platform_breakout(bars: Bars) -> Signal | None:
    """平台突破：前期窄幅横盘，今天放量收在平台上沿之上。"""
    need = PLATFORM_DAYS + 5
    if len(bars) < need:
        return None

    box = slice(len(bars) - 1 - PLATFORM_DAYS, len(bars) - 1)
    top = float(bars.high[box].max())
    bottom = float(bars.low[box].min())
    if bottom <= 0:
        return None
    width = (top - bottom) / bottom
    if width >= PLATFORM_MAX_RANGE:
        return None
    if bars.close[-1] <= top:
        return None

    ratio = _volume_ratio(bars, 5)
    if ratio < PLATFORM_VOL_MULT:
        return None

    excess = float(bars.close[-1] / top - 1)
    if excess > PLATFORM_MAX_EXCESS:
        return None

    # 平台越窄越好、放量越足越好、突破幅度适中
    score = _gate_score(width, PLATFORM_MAX_RANGE, PLATFORM_IDEAL_RANGE) * 40
    score += _band_score(ratio, PLATFORM_VOL_MULT, 4.0, 8.0) * 35
    score += _band_score(excess, 0.005, 0.04, 0.10) * 25

    return Signal(
        "platform_breakout",
        score,
        {"breakout": top, "support": bottom},
        {"platform_width": round(width, 4), "vol_ratio": round(ratio, 2),
         "excess": round(excess, 4)},
    )


def _volume_breakout(bars: Bars) -> Signal | None:
    """放量突破前高：突破 60 日前高，且当日量显著放大。"""
    if len(bars) < PRIOR_HIGH_DAYS + PRIOR_HIGH_VOL_WINDOW:
        return None

    prior = float(bars.close[-PRIOR_HIGH_DAYS - 1 : -1].max())
    if bars.close[-1] <= prior:
        return None

    ratio = _volume_ratio(bars, PRIOR_HIGH_VOL_WINDOW)
    if ratio < PRIOR_HIGH_VOL_MULT:
        return None

    excess = float(bars.close[-1] / prior - 1)
    score = _band_score(ratio, PRIOR_HIGH_VOL_MULT, 5.0, 10.0) * 60
    score += _band_score(excess, 0.005, 0.04, 0.10) * 40

    return Signal(
        "volume_breakout",
        score,
        {"breakout": prior},
        {"vol_ratio": round(ratio, 2), "excess": round(excess, 4)},
    )


def _turtle_breakout(bars: Bars) -> Signal | None:
    """海龟突破：收盘创 20 日**最高价**新高，成交额过亿，且今天是实体阳线 + 真涨。

    2026-10-17 移植自 `sngyai/Sequoia-X` 的 `TurtleTradeStrategy`。四条必要条件
    照搬，打分按本站 0~100 口径重写（见文件顶部 `TURTLE_*` 那段的分工说明）。
    """
    if len(bars) < TURTLE_WINDOW + 1:
        return None

    prior_high = float(bars.high[-TURTLE_WINDOW - 1 : -1].max())
    close = float(bars.close[-1])
    if close <= prior_high:
        return None

    amount = float(bars.amount[-1])
    if amount < TURTLE_MIN_AMOUNT:
        return None

    # 防诱多：高开低走的大阴线即使盘中创了新高也不收（原策略专门加的这条）
    if close <= float(bars.open[-1]) or close <= float(bars.close[-2]):
        return None

    excess = close / prior_high - 1
    ratio = _volume_ratio(bars, 5)
    pct = float(bars.pct_chg[-1])

    score = _gate_score(amount, TURTLE_MIN_AMOUNT, TURTLE_AMOUNT_IDEAL) * 20
    score += _band_score(ratio, *TURTLE_VOL_IDEAL, TURTLE_VOL_CAP) * 35
    score += _band_score(excess, *TURTLE_EXCESS_IDEAL, TURTLE_EXCESS_CAP) * 30
    score += _gate_score(pct / 100.0, 0.0, 0.03) * 15

    return Signal(
        "turtle_breakout",
        min(score, 100.0),
        {"breakout": prior_high},
        {
            "excess": round(excess, 4),
            "vol_ratio": round(ratio, 2),
            "amount_yi": round(amount / 1e8, 2),
            "pct_chg": round(pct, 2),
        },
    )


def _volume_surge(bars: Bars) -> Signal | None:
    """放量上涨：当日大涨且量比显著高于 5 日均量。"""
    if len(bars) < 6:
        return None

    pct = float(bars.pct_chg[-1])
    if pct < SURGE_MIN_PCT:
        return None
    ratio = _volume_ratio(bars, 5)
    if ratio < SURGE_MIN_VOL_RATIO:
        return None

    score = _band_score(pct, *SURGE_PCT_IDEAL, SURGE_PCT_CAP) * 50
    score += _band_score(ratio, *SURGE_RATIO_IDEAL, SURGE_RATIO_CAP) * 50

    return Signal(
        "volume_surge",
        score,
        {},
        {"pct_chg": round(pct, 2), "vol_ratio": round(ratio, 2)},
    )


def _volume_engulf(bars: Bars) -> Signal | None:
    """放量阳包阴：阳线实体反包阴线实体，且**阳线成交量 > 阴线成交量**。

    2026-10-19 用户定义。它与 2026-10-14 撤下的裸「阳包阴」不是一回事 ——
    那一版不看量（信号 3963 条、10 日超额 +0.31%，按当时的噪声线撤下）；
    这里要求今量严格大于昨量，信号会少一大截。

    判定只用最近两根 K 线，不加「前期回调」之类的前置：

    1. 昨日阴线（收 < 开）、今日阳线（收 > 开）；
    2. 今日实体完全包住昨日实体：今开 ≤ 昨收，今收 ≥ 昨开；
    3. 今日成交量 > 昨日成交量，且**倍量 ≥ `ENGULF_MIN_VOLUME_RATIO`（1.5）**。

    评分：50 分起步（刚好达标），倍量超过门槛的部分最多 +25、实体比最多 +20 ——
    上限 **95 分**，不让它轻易刷到 100 去霸占命中列表前排（2026-10-19 实测：
    门槛 1.2 时一天 27 条满分，前 50 几乎全是它）。
    """
    if len(bars) < 2:
        return None

    prev_open, _, _, prev_close, prev_body, _, _, _ = _candle(bars, -2)
    open_, _, low, close, body, _, _, _ = _candle(bars)
    if prev_close >= prev_open or close <= open_:
        return None
    if prev_body <= 0 or body <= 0:
        return None
    if not (open_ <= prev_close and close >= prev_open):
        return None

    prev_volume = float(bars.volume[-2])
    volume = float(bars.volume[-1])
    if prev_volume <= 0:
        return None
    ratio = volume / prev_volume
    if ratio < ENGULF_MIN_VOLUME_RATIO:
        return None

    body_ratio = body / prev_body
    score = (
        50.0
        + min(25.0, (ratio - ENGULF_MIN_VOLUME_RATIO) * 20.0)
        + min(20.0, (body_ratio - 1.0) * 10.0)
    )
    return Signal(
        "volume_engulf",
        round(score, 1),
        {"breakout": round(prev_open, 2), "support": round(low, 2)},
        {
            "volume_ratio": round(ratio, 2),
            "body_ratio": round(body_ratio, 2),
            "pct_chg": round(float(bars.pct_chg[-1]), 2),
        },
    )


def _dry_pullback(bars: Bars) -> Signal | None:
    """缩量回踩：高位回调但量能明显萎缩，且没跌破 MA20。"""
    if len(bars) < MA_PERIODS[-1] + DRY_PULLBACK_UP_WINDOW + DRY_PULLBACK_MAX_DAYS:
        return None

    ma20 = _align(_ma_series(bars.close, 20), 20, len(bars))
    if not np.isfinite(ma20[-1]) or ma20[-1] <= 0:
        return None
    if bars.close[-1] <= ma20[-1]:
        return None

    best: Signal | None = None
    for days in range(DRY_PULLBACK_MIN_DAYS, DRY_PULLBACK_MAX_DAYS + 1):
        seg = slice(len(bars) - days, len(bars))
        peak = float(bars.high[seg].max())
        if peak <= 0:
            continue
        drop = (peak - float(bars.close[-1])) / peak
        if not (DRY_PULLBACK_DROP[0] <= drop <= DRY_PULLBACK_DROP[1]):
            continue

        prior = slice(len(bars) - days - DRY_PULLBACK_UP_WINDOW, len(bars) - days)
        up_volume = _safe_mean(bars.volume[prior])
        if up_volume <= 0:
            continue
        ratio = _safe_mean(bars.volume[seg]) / up_volume
        if ratio > DRY_PULLBACK_MAX_VOL_RATIO:
            continue

        gap = float((bars.close[-1] - ma20[-1]) / ma20[-1])
        score = _gate_score(ratio, DRY_PULLBACK_MAX_VOL_RATIO, DRY_PULLBACK_IDEAL_VOL_RATIO) * 45
        # 回调幅度取区间中段最好：太浅没洗够，太深就成破位了。这个是双向的，用 _band_score
        # —— `_band_score` 本身就是「区间中心给满分」的钟形，**把 drop 原样传进去**即可。
        # ⚠️ 曾经写成 `span - abs(drop - mid)`：那个量的最大值（正好落在中段时）是 `span`，
        # 而 band 的 high 只有 `span*0.8` —— 最优样本被当成「过大」衰减到 0.4，
        # 反而是偏离中段的样本拿满分，与「中段最好」正好相反（2026-09-27 修）。
        score += _band_score(
            drop, DRY_PULLBACK_DROP[0], DRY_PULLBACK_DROP[1], DRY_PULLBACK_DROP[1] * 1.4
        ) * 30
        score += _gate_score(gap, 0.002, 0.05) * 25

        candidate = Signal(
            "dry_pullback",
            score,
            {"support": float(ma20[-1]), "peak": peak},
            {"pullback_days": days, "drop": round(drop, 4), "vol_ratio": round(ratio, 3)},
        )
        if best is None or candidate.score > best.score:
            best = candidate
    return best


# ---------------------------------------------------------------- 摆动点骨架


def swing_threshold(bars: Bars) -> float:
    """摆动点的最小反向幅度，按该股近一年的日均振幅自适应。

    **这是几何形态唯一的主观旋钮**，也是它们最容易出问题的地方：阈值太小会把
    日常噪声当成一个「摆动」，于是满地都是杯柄和 W 底；太大则把真实形态整个吞掉。

    固定百分比做不到两头兼顾 —— 日均振幅 1.5% 的银行股和 6% 的题材股，
    同一个 5% 阈值前者是「趋势反转」、后者是「周二」。
    """
    window = min(len(bars), SWING_AMP_WINDOW)
    if window < 20:
        return SWING_MIN
    amplitude = (bars.high[-window:] - bars.low[-window:]) / bars.close[-window:]
    median = float(np.median(amplitude))
    return float(min(max(median * SWING_AMP_MULT, SWING_MIN), SWING_MAX))


def zigzag(high: np.ndarray, low: np.ndarray, threshold: float) -> list[tuple[int, float, int]]:
    """ZigZag 摆动点，返回 `[(索引, 价格, 方向)]`，方向 +1 为高点、-1 为低点。

    严格交替。做法是：顺着当前趋势跟踪极值，当反向幅度超过 `threshold` 时确认
    上一个极值、翻转方向。首个极值以第一根 K 线的高点起算 —— 起点选谁不影响
    形态判定，因为所有形态都只看相对关系。

    末尾那个**尚未被反向确认**的极值也会带上（假设趋势延续）。不加的话，
    「正在突破的路上」这类形态全都看不到 —— 而它们恰恰是最该被看到的。
    """
    n = int(high.size)
    if n < 3:
        return []

    pivots: list[tuple[int, float, int]] = []
    trend = 1  # 一开始假设在走高，从第一根的高点起算
    last_idx, last_price = 0, float(high[0])

    for index in range(1, n):
        if trend > 0:
            if high[index] > last_price:
                last_idx, last_price = index, float(high[index])
            elif low[index] <= last_price * (1 - threshold):
                pivots.append((last_idx, last_price, 1))
                trend = -1
                last_idx, last_price = index, float(low[index])
        else:
            if low[index] < last_price:
                last_idx, last_price = index, float(low[index])
            elif high[index] >= last_price * (1 + threshold):
                pivots.append((last_idx, last_price, -1))
                trend = 1
                last_idx, last_price = index, float(high[index])

    pivots.append((last_idx, last_price, trend))
    return pivots


def _recent_pivots(bars: Bars, window: int) -> list[tuple[int, float, int]]:
    pivots = zigzag(bars.high, bars.low, swing_threshold(bars))
    return [item for item in pivots if item[0] >= len(bars) - window]


# ---------------------------------------------------------------- 几何形态


def _cup_handle(bars: Bars) -> Signal | None:
    """杯柄：左杯沿 → 回调 15~35% → 右杯沿回到前高附近 → 柄部小幅缩量回踩 → 突破柄部上沿。

    不用摆动点，直接按「杯底把窗口切成左右两半」来切 —— 杯子的形状是平滑的圆弧，
    用摆动点反而会被杯内的小波动切碎。
    """
    if len(bars) < CUP_WINDOW:
        return None

    highs = bars.high[-CUP_WINDOW:]
    lows = bars.low[-CUP_WINDOW:]
    size = int(highs.size)

    left_end = int(size * CUP_LEFT_END)
    right_start = int(size * CUP_RIGHT_START)
    left_rel = int(np.argmax(highs[:left_end]))
    left_rim = float(highs[left_rel])

    if right_start <= left_rel + 2:
        return None
    trough_rel = int(np.argmin(lows[left_rel + 1 : right_start])) + left_rel + 1
    trough = float(lows[trough_rel])

    depth = (left_rim - trough) / left_rim
    if not (CUP_DEPTH[0] <= depth <= CUP_DEPTH[1]):
        return None

    if trough_rel + 2 >= size - 1:
        return None
    right_rel = int(np.argmax(highs[trough_rel + 1 :])) + trough_rel + 1
    right_rim = float(highs[right_rel])
    cup_height = left_rim - trough
    if cup_height <= 0:
        return None
    recover = (right_rim - trough) / cup_height
    if recover < CUP_RECOVER:
        return None

    # 柄部：右杯沿之后、**不含今天**的那些 K 线（今天是突破日）
    handle = slice(right_rel + 1, size - 1)
    handle_days = handle.stop - handle.start
    if handle_days < CUP_HANDLE_MIN_DAYS or handle_days > CUP_HANDLE_MAX_DAYS:
        return None

    handle_top = float(highs[handle].max())
    # 用**收盘**的最低点衡量柄部深度，不用最低价：单根下影线扎一下就把整个
    # 结构判死没有意义，柄部的「回撤」应该是实打实跌下去多少
    handle_low = float(bars.close[-CUP_WINDOW:][handle].min())
    handle_ratio = (right_rim - handle_low) / cup_height
    if handle_ratio > CUP_HANDLE_DEPTH_RATIO:
        return None
    if bars.close[-1] <= handle_top:
        return None

    rise = slice(trough_rel, right_rel + 1)
    rise_volume = _safe_mean(bars.volume[-CUP_WINDOW:][rise])
    handle_volume = _safe_mean(bars.volume[-CUP_WINDOW:][handle])
    ratio = handle_volume / rise_volume if rise_volume > 0 else 1.0
    if ratio > CUP_HANDLE_VOL_RATIO:
        return None

    excess = float(bars.close[-1] / handle_top - 1)
    # 杯深取区间中段最好（太浅是回调不是杯，太深是反转不是整理）—— 唯一双向的一项。
    # 同 `_dry_pullback`：把 `depth` 原样交给 `_band_score`，别自己拼
    # `half - abs(depth - mid)`（那样最优值会被当成过大衰减，见该处的说明）。
    score = _band_score(depth, CUP_DEPTH[0], CUP_DEPTH[1], CUP_DEPTH[1] * 1.4) * 30
    score += _gate_score(recover, CUP_RECOVER, 1.0) * 20
    score += _gate_score(handle_ratio, CUP_HANDLE_DEPTH_RATIO, CUP_HANDLE_IDEAL_RATIO) * 25
    score += _gate_score(ratio, CUP_HANDLE_VOL_RATIO, CUP_HANDLE_IDEAL_VOL_RATIO) * 15
    score += _band_score(excess, 0.005, 0.03, 0.08) * 10

    return Signal(
        "cup_handle",
        score,
        {"breakout": handle_top, "support": handle_low, "rim": left_rim},
        {
            "cup_depth": round(depth, 4),
            "recover": round(recover, 3),
            "handle_days": handle_days,
            "handle_ratio": round(handle_ratio, 3),
            "handle_vol_ratio": round(ratio, 3),
            "excess": round(excess, 4),
        },
    )


def _double_bottom(bars: Bars) -> Signal | None:
    """W 底：两个相近的低点，中间反弹出颈线，今天收在颈线上方。"""
    if len(bars) < DOUBLE_BOTTOM_MIN_BARS:
        return None

    recent = _recent_pivots(bars, DOUBLE_BOTTOM_WINDOW)
    lows = [item for item in recent if item[2] < 0]
    if len(lows) < 2:
        return None

    first, second = lows[-2], lows[-1]
    gap = second[0] - first[0]
    if not (DOUBLE_BOTTOM_GAP[0] <= gap <= DOUBLE_BOTTOM_GAP[1]):
        return None

    shallow = max(first[1], second[1])
    tolerance = abs(first[1] - second[1]) / shallow
    if tolerance > DOUBLE_BOTTOM_TOLERANCE:
        return None

    between = [item for item in recent if first[0] < item[0] < second[0] and item[2] > 0]
    if not between:
        return None
    neck = max(between, key=lambda item: item[1])
    neckline = neck[1]
    rebound = (neckline - shallow) / shallow
    if rebound < DOUBLE_BOTTOM_REBOUND:
        return None

    if bars.close[-1] <= neckline:
        return None
    excess = float(bars.close[-1] / neckline - 1)
    if excess > DOUBLE_BOTTOM_MAX_EXCESS:
        return None

    score = _gate_score(tolerance, DOUBLE_BOTTOM_TOLERANCE, 0.0) * 35
    score += _band_score(rebound, DOUBLE_BOTTOM_REBOUND, 0.30, 0.50) * 30
    score += _band_score(excess, 0.003, 0.025, 0.06) * 35

    return Signal(
        "double_bottom",
        score,
        {"breakout": neckline, "support": shallow},
        {
            # 刻意叫 bottom_gap 而不是 gap：`gap` 在均线多头排列里是「距 MA20 的比率」，
            # 同名不同义会让前端把它当比率乘 100，显示成 2700%（27 天 × 100）
            "bottom_gap": gap,
            "tolerance": round(tolerance, 4),
            "rebound": round(rebound, 4),
            "excess": round(excess, 4),
        },
    )


def _head_shoulders(bars: Bars) -> Signal | None:
    """头肩底：左肩 → 头（更低的低点）→ 右肩，两肩等高、颈线大致水平，今天收在颈线上方。

    与 W 底的区别在**结构**而不是阈值：W 底是两个底加一次反弹，头肩底是三个底、
    中间那个最深。所以这里必须点名「三个低点」，不能拿 W 底的条件拼出来 ——
    头肩底的两个肩在 W 底眼里正好是「两个相近的低点」。

    同一段走势同时命中两个形态是允许的（本来就重叠），但观察点不同：
    W 底盯的是两个底的连线，头肩底盯的是颈线。**别为了去重而把结构判松**，
    那会连「像不像」都一起丢掉。
    """
    if len(bars) < HS_MIN_BARS:
        return None

    recent = _recent_pivots(bars, HS_WINDOW)
    lows = [item for item in recent if item[2] < 0]
    if len(lows) < 3:
        return None

    left, head, right = lows[-3], lows[-2], lows[-1]
    # 头必须是三个低点里最低的那个，否则就不是头肩
    if not (head[1] < left[1] and head[1] < right[1]):
        return None

    shoulder_diff = abs(left[1] - right[1]) / min(left[1], right[1])
    if shoulder_diff > HS_SHOULDER_TOLERANCE:
        return None

    # 两个颈线高点：左肩~头之间一个、头~右肩之间一个
    neck_left = [item for item in recent if left[0] < item[0] < head[0] and item[2] > 0]
    neck_right = [item for item in recent if head[0] < item[0] < right[0] and item[2] > 0]
    if not neck_left or not neck_right:
        return None
    neck_a = max(neck_left, key=lambda item: item[1])
    neck_b = max(neck_right, key=lambda item: item[1])
    # 突破线取两者中**较低**的那个：保守一些，宁可要求多涨一点才算过关
    neckline = min(neck_a[1], neck_b[1])

    neck_diff = abs(neck_a[1] - neck_b[1]) / max(neck_a[1], neck_b[1])
    if neck_diff > HS_NECK_TOLERANCE:
        return None

    depth = (neckline - head[1]) / neckline
    if depth < HS_MIN_DEPTH:
        return None

    tail = len(bars) - 1 - right[0]
    if tail > HS_MAX_TAIL:
        return None

    if bars.close[-1] <= neckline:
        return None
    excess = float(bars.close[-1] / neckline - 1)
    if excess > HS_MAX_EXCESS:
        return None

    score = _gate_score(shoulder_diff, HS_SHOULDER_TOLERANCE, 0.0) * 25
    score += _gate_score(neck_diff, HS_NECK_TOLERANCE, 0.0) * 20
    score += _band_score(depth, HS_MIN_DEPTH, 0.20, 0.35) * 25
    score += _band_score(excess, 0.003, 0.025, 0.06) * 30

    return Signal(
        "head_shoulders",
        score,
        {"breakout": neckline, "support": max(left[1], right[1])},
        {
            "shoulder_diff": round(shoulder_diff, 4),
            "neck_diff": round(neck_diff, 4),
            "head_depth": round(depth, 4),
            "excess": round(excess, 4),
            "tail": tail,
        },
    )


def _flag(bars: Bars) -> Signal | None:
    """旗形：一段急涨（旗杆）之后窄幅缩量整理（旗面），今天贴着旗面上沿。

    属于**待突破**的观察位，所以不打「已经突破」的分，
    打的是「旗杆够不够强、整理得够不够紧」。

    旗面不用摆动点切，而是**从最高点之后算起**：整理期的波动本来就小，
    摆动点在这么窄的区间里会被噪声切出一堆假极值。这也顺便给了「旗面多长」
    一个自然的定义 —— 急涨顶到哪儿，旗面就从哪儿开始。
    """
    total = FLAG_POLE_DAYS + FLAG_MAX_DAYS
    if len(bars) < total + 10:
        return None

    highs = bars.high[-total:]
    lows = bars.low[-total:]

    peak = int(np.argmax(highs))
    flag_days = int(highs.size) - 1 - peak
    if not (FLAG_MIN_DAYS <= flag_days <= FLAG_MAX_DAYS):
        return None
    # 旗杆得留得下：顶之前至少还有 FLAG_POLE_DAYS 根可看
    if peak < FLAG_POLE_DAYS:
        return None

    pole_start = peak - FLAG_POLE_DAYS
    pole_low = float(lows[pole_start : peak + 1].min())
    if pole_low <= 0:
        return None
    pole_gain = float(highs[peak]) / pole_low - 1
    if pole_gain < FLAG_MIN_POLE:
        return None

    flag_high = float(highs[peak + 1 :].max())
    flag_low = float(lows[peak + 1 :].min())
    if flag_high <= flag_low:
        return None
    flag_range = (flag_high - flag_low) / flag_high
    if flag_range > FLAG_MAX_RANGE:
        return None

    retrace = (float(highs[peak]) - flag_low) / (float(highs[peak]) - pole_low)
    if retrace > FLAG_MAX_RETRACE:
        return None

    pole_volume = _safe_mean(bars.volume[-total:][pole_start : peak + 1])
    flag_volume = _safe_mean(bars.volume[-total:][peak + 1 :])
    vol_ratio = flag_volume / pole_volume if pole_volume > 0 else 1.0
    if vol_ratio > FLAG_MAX_VOL_RATIO:
        return None

    position = (float(bars.close[-1]) - flag_low) / (flag_high - flag_low)
    if position < FLAG_MIN_POSITION:
        return None
    excess = float(bars.close[-1] / flag_high - 1)
    if excess > FLAG_MAX_EXCESS:
        return None

    score = _band_score(pole_gain, FLAG_MIN_POLE, 0.35, 0.60) * 30
    score += _gate_score(flag_range, FLAG_MAX_RANGE, 0.04) * 20
    score += _gate_score(retrace, FLAG_MAX_RETRACE, 0.15) * 20
    score += _gate_score(vol_ratio, FLAG_MAX_VOL_RATIO, 0.50) * 20
    score += _band_score(position, FLAG_MIN_POSITION, 0.85, 1.05) * 10

    return Signal(
        "flag",
        score,
        {"breakout": flag_high, "support": flag_low},
        {
            "pole_gain": round(pole_gain, 4),
            "flag_days": flag_days,
            "flag_range": round(flag_range, 4),
            "retrace": round(retrace, 4),
            "vol_drop": round(vol_ratio, 4),
            "position": round(position, 4),
            "excess": round(excess, 4),
        },
    )


def _three_stage(bars: Bars) -> Signal | None:
    """三段式突破：缓涨 → 急涨 → 缩量整理 → 今天突破整理段上沿。

    这是**唯一一个不是从交易书里抄来的形态** —— 它来自用户举的一只真实票
    （强达电路 301628，2026-08 那段），阈值则是在全市场回测里选出来的
    （过程与局限见 `THREE_SLOW_DAYS` 上面那段注释，别跳过）。

    与「旗形」的关键区别：旗形只看急涨之后的整理，这里还要求**急涨之前有一段
    缓涨** —— 资金是逐步进场的，不是一根线拉起来的。代价是它严得多，
    A 股全市场平均每周才出一个。

    整理段与急涨段的长度都未知，两个都枚举一遍，取**评分最高**的组合：
    判定用的是「是不是」，但页面上要排序，所以必须给分而不是给是非。
    """
    close, high, low, volume, open_ = (
        bars.close,
        bars.high,
        bars.low,
        bars.volume,
        bars.open,
    )
    size = len(bars)
    best: Signal | None = None

    for flat_days in range(THREE_FLAT_DAYS[0], THREE_FLAT_DAYS[1] + 1):
        # 整理段是「不含今天」的那几天 —— 今天是突破日
        flat_start = size - 1 - flat_days
        if flat_start < 30:
            continue
        flat_high = float(high[flat_start : size - 1].max())
        flat_low = float(low[flat_start : size - 1].min())
        flat_mean = float(close[flat_start : size - 1].mean())
        if flat_mean <= 0:
            continue
        flat_range = (flat_high - flat_low) / flat_mean
        flat_vol = float(volume[flat_start : size - 1].mean())
        if flat_vol <= 0:
            continue

        for surge_days in range(THREE_SURGE_DAYS[0], THREE_SURGE_DAYS[1] + 1):
            surge_end = flat_start - 1
            surge_start = surge_end - surge_days + 1
            if surge_start < THREE_SLOW_DAYS + 5:
                continue
            base = float(close[surge_start - 1])
            if base <= 0:
                continue
            surge_gain = float(close[surge_end]) / base - 1
            if surge_gain < THREE_SURGE_GAIN:
                continue
            prev_vol = float(volume[surge_start - 5 : surge_start].mean())
            if prev_vol <= 0:
                continue
            surge_ratio = float(volume[surge_start : surge_end + 1].mean()) / prev_vol
            if surge_ratio < THREE_SURGE_VOL:
                continue
            if flat_range > THREE_FLAT_RANGE:
                continue

            # 整理段要守住急涨的成果
            span_high = float(high[surge_start - 1 : surge_end + 1].max())
            span_low = float(low[surge_start - 1 : surge_end + 1].min())
            span = span_high - span_low
            if span <= 0:
                continue
            if (span_high - flat_low) / span > THREE_FLAT_DROP:
                continue
            shrink = flat_vol / (float(volume[surge_start : surge_end + 1].mean()))
            if shrink > THREE_FLAT_VOL:
                continue

            # 缓涨段：急涨之前的这些天，涨得不多但阳线多
            slow_start = max(0, surge_start - THREE_SLOW_DAYS)
            slow_close = close[slow_start:surge_start]
            if slow_close.size < 8:
                continue
            slow_base = float(slow_close[0])
            if slow_base <= 0:
                continue
            slow_gain = float(slow_close[-1]) / slow_base - 1
            if not (THREE_SLOW_GAIN[0] <= slow_gain <= THREE_SLOW_GAIN[1]):
                continue
            bull = float(np.mean(slow_close > open_[slow_start:surge_start]))
            if bull < THREE_SLOW_BULL:
                continue

            # 今天必须真的突破了整理段上沿
            if float(close[-1]) <= flat_high:
                continue
            break_ratio = float(volume[-1]) / flat_vol
            if break_ratio < THREE_BREAK_VOL:
                continue
            excess = float(close[-1] / flat_high - 1)

            score = _band_score(surge_gain, THREE_SURGE_GAIN, 0.25, 0.45) * 20
            score += _band_score(surge_ratio, THREE_SURGE_VOL, 3.0, 5.0) * 15
            score += _gate_score(flat_range, THREE_FLAT_RANGE, 0.05) * 20
            score += _gate_score(shrink, THREE_FLAT_VOL, 0.35) * 20
            score += _gate_score(break_ratio, THREE_BREAK_VOL, 2.5) * 10
            score += _gate_score(bull, THREE_SLOW_BULL, 0.75) * 15

            if best is None or score > best.score:
                best = Signal(
                    "three_stage",
                    score,
                    {"breakout": flat_high, "support": flat_low},
                    {
                        "slow_gain": round(slow_gain, 4),
                        "slow_bull": round(bull, 3),
                        "surge_gain": round(surge_gain, 4),
                        "surge_days": surge_days,
                        "surge_vol": round(surge_ratio, 3),
                        "flat_days": flat_days,
                        "flat_range": round(flat_range, 4),
                        "shrink": round(shrink, 3),
                        "break_vol": round(break_ratio, 3),
                        "excess": round(excess, 4),
                    },
                )
    return best


def _limit_surge_flat(bars: Bars) -> Signal | None:
    """涨停爆量横盘：涨停爆量启动 → 突破前期平台 → 缩量横盘，今天仍在横盘段里。

    与其它形态最大的不同：它找的是**已经走完一段、正在歇脚**的票，买点在
    「横盘上沿被再次放量突破」那一刻 —— 所以它**不要求今天突破**，反而要求
    今天仍在区间内。这也意味着同一只票在横盘期里会**连续多天**命中，这是对的。

    「涨停日」在最近 `LS_LOOKBACK` 天里枚举（一只票可能连着好几个涨停），
    横盘长度也枚举，取评分最高的组合 —— 判定是「是不是」，但页面上要排序。
    """
    size = len(bars)
    # 涨停日之后至少要留出「上冲 1 天 + 横盘 LS_FLAT_DAYS[0] 天」
    last_t0 = size - 1 - LS_FLAT_DAYS[0]
    first_t0 = max(LS_PLATFORM_DAYS + 5, size - 1 - LS_LOOKBACK)
    if last_t0 < first_t0:
        return None

    close, high, low, volume, pct = (
        bars.close,
        bars.high,
        bars.low,
        bars.volume,
        bars.pct_chg,
    )
    best: Signal | None = None

    for t0 in range(first_t0, last_t0 + 1):
        if float(pct[t0]) < LS_LIMIT_PCT:
            continue
        base_vol = _safe_mean(volume[t0 - 5 : t0])
        if base_vol <= 0:
            continue
        limit_vol = float(volume[t0]) / base_vol
        if limit_vol < LS_SURGE_VOL:
            continue

        # 前期平台（不含涨停日，否则自己就是自己的平台）
        platform = float(high[t0 - LS_PLATFORM_DAYS : t0].max())
        prev_close = float(close[t0 - 1])
        if platform <= 0 or prev_close <= 0:
            continue

        for flat_days in range(LS_FLAT_DAYS[0], LS_FLAT_DAYS[1] + 1):
            flat_start = size - flat_days
            if flat_start <= t0:
                continue
            run_end = flat_start - 1

            # ---- 上冲段：涨停日起到横盘开始之前 ----
            seg_high = float(high[t0 : run_end + 1].max())
            run_gain = seg_high / prev_close - 1
            if run_gain < LS_MIN_RUN:
                continue
            # 突破必须**在涨停后 LS_BREAK_DAYS 天内**发生，且是收盘站上平台。
            # 只问「这段里有没有收盘在平台之上」不够 —— 涨了一大段之后的收盘
            # 当然也在上面，那就等于没检查突破发生的时间
            break_to = min(t0 + LS_BREAK_DAYS, run_end)
            if float(close[t0 : break_to + 1].max()) <= platform:
                continue

            # ---- 横盘段 ----
            flat_high = float(high[flat_start:].max())
            flat_low = float(low[flat_start:].min())
            flat_mean = float(close[flat_start:].mean())
            if flat_mean <= 0 or flat_high <= flat_low:
                continue
            flat_range = (flat_high - flat_low) / flat_mean
            if flat_range > LS_FLAT_RANGE:
                continue
            # 横盘低点守住多少成果。这一条比「振幅够窄」更要紧：振幅窄但一路
            # 阴跌回平台上的「横盘」，是出货不是整理
            keep = (flat_low - platform) / (seg_high - platform)
            if keep < LS_FLAT_KEEP:
                continue

            run_vol = _safe_mean(volume[t0 : run_end + 1])
            flat_vol = _safe_mean(volume[flat_start:])
            if run_vol <= 0:
                continue
            shrink = flat_vol / run_vol
            if shrink > LS_FLAT_VOL:
                continue

            score = _band_score(limit_vol, LS_SURGE_VOL, 5.0, 12.0) * 20
            score += _band_score(run_gain, LS_MIN_RUN, 0.30, 0.60) * 20
            score += _gate_score(flat_range, LS_FLAT_RANGE, 0.04) * 20
            score += _gate_score(shrink, LS_FLAT_VOL, 0.40) * 20
            score += _gate_score(keep, LS_FLAT_KEEP, 0.85) * 10
            score += _band_score(float(flat_days), LS_FLAT_DAYS[0], 6, LS_FLAT_DAYS[1] + 1) * 10

            if best is None or score > best.score:
                best = Signal(
                    "limit_surge_flat",
                    score,
                    {"breakout": flat_high, "support": flat_low},
                    {
                        "limit_vol": round(limit_vol, 3),
                        "surge_gain": round(run_gain, 4),
                        "flat_days": flat_days,
                        "flat_range": round(flat_range, 4),
                        "shrink": round(shrink, 3),
                        "keep": round(keep, 4),
                        "excess": round(float(close[-1]) / platform - 1, 4),
                    },
                )
    return best


def _breakout_flat(bars: Bars) -> Signal | None:
    """突破后横盘：放量突破 60 日新高 → 缩量横着、不跌回突破位 → 今天仍在区间里。

    与其它形态最不一样的一点：判定日落在**横盘期内**，给的是**观察位**而不是买点 ——
    真正的买点是「它再次放量突破横盘上沿」，那是之后的事。所以它**不要求今天突破**，
    反而要求今天还在区间内。

    突破日在最近 `BF_MAX_GAP` 天里枚举（一只票可能不止一根），取评分最高的那根。
    """
    size = len(bars)
    if size < BF_PRIOR_HIGH + BF_MIN_FLAT + 5:
        return None

    close, high, low, volume = bars.close, bars.high, bars.low, bars.volume
    today = float(close[-1])
    best: Signal | None = None

    # gap = 今天距突破日的天数。横盘段是「突破日之后、今天之前」
    for gap in range(BF_MIN_FLAT + 1, BF_MAX_GAP + 1):
        b_idx = size - 1 - gap
        if b_idx < BF_PRIOR_HIGH:
            continue
        prev_close = float(close[b_idx - 1])
        if prev_close <= 0:
            continue
        b_close = float(close[b_idx])
        gain = b_close / prev_close - 1
        if gain < BF_MIN_GAIN:
            continue
        prev_vol = _safe_mean(volume[b_idx - 5 : b_idx])
        if prev_vol <= 0:
            continue
        b_ratio = float(volume[b_idx]) / prev_vol
        if b_ratio < BF_MIN_VOL:
            continue
        # 突破要创 N 日新高，否则只是「涨了一天」
        if b_close <= float(close[b_idx - BF_PRIOR_HIGH : b_idx].max()):
            continue

        flat = slice(b_idx + 1, size - 1)
        flat_days = flat.stop - flat.start
        if flat_days < BF_MIN_FLAT:
            continue
        flat_high = float(high[flat].max())
        flat_low = float(low[flat].min())
        flat_mean = float(close[flat].mean())
        if flat_mean <= 0 or flat_high <= flat_low:
            continue
        flat_range = (flat_high - flat_low) / flat_mean
        if flat_range > BF_MAX_RANGE:
            continue
        # 不跌回突破位 —— 这条是形态的关键：涨上去又跌回来就不算强势
        giveback = (b_close - flat_low) / b_close
        if giveback > BF_MAX_GIVEBACK:
            continue
        flat_vol = _safe_mean(volume[flat])
        if flat_vol <= 0:
            continue
        shrink = flat_vol / float(volume[b_idx])
        if shrink > BF_MAX_SHRINK:
            continue
        # 今天还得在区间里：既没跌破下沿，也没有已经冲出去
        if today > flat_high * (1 + BF_EDGE_TOLERANCE):
            continue
        if today < flat_low * (1 - BF_EDGE_TOLERANCE):
            continue

        position = (today - flat_low) / (flat_high - flat_low)

        score = _band_score(gain, BF_MIN_GAIN, 0.15, 0.25) * 20
        score += _band_score(b_ratio, BF_MIN_VOL, 5.0, 10.0) * 20
        score += _gate_score(flat_range, BF_MAX_RANGE, 0.05) * 20
        score += _gate_score(giveback, BF_MAX_GIVEBACK, 0.0) * 10
        score += _gate_score(shrink, BF_MAX_SHRINK, 0.35) * 10
        score += _band_score(float(flat_days), BF_MIN_FLAT, 6, BF_MAX_GAP + 1) * 10
        score += _band_score(position, 0.4, 0.85, 1.05) * 10

        if best is None or score > best.score:
            best = Signal(
                "breakout_flat",
                score,
                {"breakout": flat_high, "support": flat_low},
                {
                    "break_gain": round(gain, 4),
                    "vol_ratio": round(b_ratio, 2),
                    "flat_days": flat_days,
                    "flat_range": round(flat_range, 4),
                    "giveback": round(giveback, 4),
                    "shrink": round(shrink, 3),
                    "position": round(position, 4),
                },
            )
    return best


def _n_shape(bars: Bars) -> Signal | None:
    """N 字选股：放量大涨 → 缩量回调到起涨点附近。

    起涨点 = 大涨那天的起点（开盘价与前一日收盘取低的，含跳空）。

    判定时点落在**回调期内**，所以同一只票会连着几天命中 —— 这是对的：
    它连着几天都处在「已经回踩到起点」的状态里，不是重复计数。
    """
    size = len(bars)
    if size < 30:
        return None

    close, low, open_ = bars.close, bars.low, bars.open
    volume, pct = bars.volume, bars.pct_chg
    best: Signal | None = None

    for pull_days in range(NS_PULL_DAYS[0], NS_PULL_DAYS[1] + 1):
        t0 = size - 1 - pull_days  # 放量大涨日
        if t0 < 10:
            continue
        if float(pct[t0]) < NS_SURGE_PCT:
            continue
        base_vol = _safe_mean(volume[t0 - 5 : t0])
        if base_vol <= 0:
            continue
        ratio = float(volume[t0]) / base_vol
        if ratio < NS_SURGE_VOL:
            continue

        start_point = min(float(open_[t0]), float(close[t0 - 1]))
        if start_point <= 0:
            continue
        pull_low = float(low[t0 + 1 :].min())
        if not (start_point * NS_LOW_BAND[0] <= pull_low <= start_point * NS_LOW_BAND[1]):
            continue
        today = float(close[-1])
        if not (start_point * NS_NOW_BAND[0] <= today <= start_point * NS_NOW_BAND[1]):
            continue
        pull_vol = _safe_mean(volume[t0 + 1 :])
        if pull_vol <= 0:
            continue
        shrink = pull_vol / float(volume[t0])
        if shrink > NS_MAX_SHRINK:
            continue

        gap = today / start_point - 1
        # 「踩得准」占最大权重：离起涨点越近，越像教科书里的那一折
        score = (1 - min(abs(gap), 0.12) / 0.12) * 40
        score += _band_score(ratio, NS_SURGE_VOL, 5.0, 10.0) * 25
        score += _gate_score(shrink, NS_MAX_SHRINK, 0.40) * 20
        score += _band_score(float(pull_days), float(NS_PULL_DAYS[0]), 3.0, 6.0) * 15

        if best is None or score > best.score:
            best = Signal(
                "n_shape",
                score,
                {"breakout": start_point, "support": pull_low},
                {
                    "surge_gain": round(float(pct[t0]) / 100, 4),
                    "vol_ratio": round(ratio, 2),
                    "pullback_days": pull_days,
                    "start_gap": round(gap, 4),
                    "shrink": round(shrink, 3),
                },
            )
    return best


def _burst_shrink_pullback(bars: Bars) -> Signal | None:
    """爆量后缩量回踩：某天成交额放量到前一日 2 倍以上（爆量日），之后某天缩量到
    爆量日的一半以下（缩量日）—— **要选的是缩量日**，不是爆量日。

    判定时点落在缩量日，且是「爆量日之后**第一个**跌破一半的日子」：一只票一次爆量
    只出一个信号，不会在缩量期里连续好几天刷屏（缩量一旦到位往往会在低位趴几天，
    逐日命中会把榜单塞满同一只票）。

    爆量日只看成交额（≥ 前一日 2 倍）+ 必须阳线（收 > 开）；缩量日只看成交额。
    """
    size = len(bars)
    if size < BURST_SHRINK_LOOKBACK + 2:
        return None

    amount = bars.amount
    today = size - 1
    today_amt = float(amount[today])
    if today_amt <= 0:
        return None

    # 从最近往前找爆量日：最近的那一个才是当前这轮缩量的参照 —— 更早的爆量日，
    # 它的缩量早在新爆量日之前就走完了。找到最近的爆量日后，只看它之后
    # **第一个**跌破一半的日子是不是今天；不是就说明这轮信号已经过去/还没到。
    for e in range(today - 1, today - 1 - BURST_SHRINK_LOOKBACK, -1):
        if e < 1:
            break
        prev = float(amount[e - 1])
        cur = float(amount[e])
        if prev <= 0 or cur <= 0 or cur < BURST_SHRINK_MULT * prev:
            continue
        # 爆量日必须是阳线：放量下跌的「爆量」是出货，不是「爆量后缩量回踩」。
        # open/close 是前复权价，但同一根 K 线内部同乘一个 ratio，收>开的关系不变
        if float(bars.close[e]) <= float(bars.open[e]):
            continue

        threshold = cur * BURST_SHRINK_RATIO
        for t in range(e + 1, today + 1):
            a = float(amount[t])
            if a <= 0:
                continue  # 缺成交额的行不算「缩量日」
            if a <= threshold:
                if t != today:
                    return None  # 第一个缩量日已经过去，这轮信号不是今天
                break
        else:
            return None  # 到今天都还没跌破一半，缩量没到位

        mult = cur / prev
        shrink = today_amt / cur
        gap = today - e
        # 分数结构：过了两道硬门槛（爆量 ≥2×、缩量 ≤0.5×）就有保底分 —— 这是「是不是」，
        # 函数前段已经把这些前提 return 掉了。叠加上去的才是「像不像」，只在命中之间排序。
        # 爆量倍数只往一个方向打分（越猛越好）：它没有「太大就假」的上限，别用 _band_score。
        score = 55.0
        score += _gate_score(mult, BURST_SHRINK_MULT, BURST_SHRINK_MULT_IDEAL) * 20
        score += _gate_score(shrink, BURST_SHRINK_RATIO, BURST_SHRINK_IDEAL_RATIO) * 20
        score += _band_score(float(gap), *BURST_SHRINK_GAP_IDEAL, BURST_SHRINK_GAP_CAP) * 5

        return Signal(
            "burst_shrink_pullback",
            score,
            {},
            {
                "burst_mult": round(mult, 2),
                "shrink": round(shrink, 4),
                "burst_gap": gap,
            },
        )
    return None


def _pile_up_shrink(bars: Bars) -> Signal | None:
    """堆量上涨后缩量：先有一段**持续的**放量推升（「堆量」），之后量能塌缩到那一轮的
    一小部分、价格也从高点回落 —— **要选出来的是缩量那一天**。

    与 `_burst_shrink_pullback` 的分工：那一条要的是**单日**爆量（一天顶前一天 2 倍）
    之后的缩量，只回看 10 个交易日；这一条要的是**一段**堆量之后的缩量，回看 45 天。
    两者时间尺度不同，不互相覆盖。

    四步（阈值与三只样例的实测数见文件上方那段）：

    1. 在最近 `PILE_LOOKBACK` 个交易日里找**收盘最高**的那天，当堆量段终点 `e`，
       且它距今不超过 `PILE_GAP_MAX` 天（太远就成了上个月的旧账，不是「这轮在歇」）。
       为什么锚「最高收盘」而不是「最大成交量」：中红医疗的最大量出在堆量段的
       **第一天**（7/30），拿它当终点会漏掉后面十天的推升 —— 而堆量段都是推升到
       区间最高点，终点天然就是它。
    2. 从 `e` 往前试不同起点 `s`（长度 `PILE_MIN_DAYS` ~ `PILE_MAX_DAYS`），在
       「均量 ≥ 基线 × `PILE_VOL_MULT` 且涨幅 ≥ `PILE_MIN_RISE`」的候选里取均量倍数
       最大的一组 —— 「堆量」看的是**一段**的均量，不是某一天的量。
    3. 今天：量 ≤ 堆量段峰值 × `SHRINK_VS_PEAK`，且是近 `SHRINK_LOWEST_DAYS` 天最低量。
    4. 今天：收盘相对 `e` 的收盘回撤 ≥ `PILE_PULLBACK_MIN`。

    只判「今天」，所以「近十个交易日」要靠调用方把那十天各扫一遍（`scan` 一天一次）。
    """
    size = len(bars)
    if size < PILE_BASE_DAYS + PILE_MIN_DAYS + 1:
        return None

    volume = bars.volume
    close = bars.close
    today = size - 1
    today_vol = float(volume[today])
    if today_vol <= 0:
        return None

    # 前缀和：下面要试二十来个起点、每个都要算一次窗口均量，别每次都重新 np.mean
    csum = np.concatenate(([0.0], np.cumsum(volume)))

    def seg_mean(lo: int, hi: int) -> float:
        if hi < lo or lo < 0:
            return 0.0
        return float(csum[hi + 1] - csum[lo]) / (hi - lo + 1)

    # ① 堆量段终点：最近 PILE_LOOKBACK 天里收盘最高的那天（不含今天）
    first = max(0, today - PILE_LOOKBACK)
    if first >= today:
        return None
    e = int(first + np.argmax(close[first:today]))
    # 堆量高点距今太远就不算「这一轮涨完在歇」了（见 `PILE_GAP_MAX`）—— 放最前面判，最省
    if today - e > PILE_GAP_MAX:
        return None

    # ② 堆量段起点：取均量倍数最大的那一段
    best: tuple[float, int, float] | None = None
    for span in range(PILE_MIN_DAYS, PILE_MAX_DAYS + 1):
        s = e - span + 1
        if s - PILE_BASE_DAYS < 0 or float(close[s - 1]) <= 0:
            continue
        base = seg_mean(s - PILE_BASE_DAYS, s - 1)
        if base <= 0:
            continue
        mult = seg_mean(s, e) / base
        if mult < PILE_VOL_MULT:
            continue
        rise = float(close[e]) / float(close[s - 1]) - 1.0
        if rise < PILE_MIN_RISE:
            continue
        if best is None or mult > best[0]:
            best = (mult, s, rise)
    if best is None:
        return None
    mult, s, rise = best

    # ③ 今天缩量到位：相对堆量段峰值、且是近 N 天最低量
    peak = float(volume[s : e + 1].max())
    if peak <= 0:
        return None
    shrink = today_vol / peak
    if shrink > SHRINK_VS_PEAK:
        return None
    lowest = float(volume[max(0, today - SHRINK_LOWEST_DAYS + 1) : today + 1].min())
    if today_vol > lowest:
        return None

    # ④ 已从堆量段高点回落（缩量**回调**）
    drop = 1.0 - float(close[today]) / float(close[e])
    if drop < PILE_PULLBACK_MIN:
        return None

    # 打分只用来在命中之间排序：两道硬门槛过了就有保底分（`MIN_SCORE` 是 50）
    score = 55.0
    score += _gate_score(mult, PILE_VOL_MULT, PILE_VOL_MULT_IDEAL) * 15
    score += _gate_score(rise, PILE_MIN_RISE, PILE_RISE_IDEAL) * 15
    score += _gate_score(shrink, SHRINK_VS_PEAK, SHRINK_IDEAL) * 10
    score += _band_score(drop, *PILE_PULLBACK_IDEAL, PILE_PULLBACK_CAP) * 5

    return Signal(
        "pile_up_shrink",
        score,
        {"pile_high": float(close[e])},
        {
            "pile_days": e - s + 1,
            "vol_mult": round(mult, 2),
            # 不叫 `rise`：那个键 `gap_fill`（缺口回补）已经占了，语义是「补缺口后的
            # 反弹幅度」—— 前端 `DETAIL_FIELDS` 是**全局共用**的，同名会串标签
            "pile_rise": round(rise, 3),
            "shrink": round(shrink, 4),
            "drop": round(drop, 4),
            "pile_gap": today - e,
        },
    )


def _wudao_day_geom(bars: Bars, i: int) -> tuple[float, float, float, float]:
    """返回 (vol_ratio, pct, close_pos, upper_shadow)。"""
    base = _safe_mean(bars.volume[i - 20 : i]) if i >= 20 else 0.0
    vol = float(bars.volume[i] / base) if base > 0 else 0.0
    pct = float(bars.pct_chg[i])
    high = float(bars.high[i])
    low = float(bars.low[i])
    open_ = float(bars.open[i])
    close = float(bars.close[i])
    span = max(high - low, 1e-9)
    close_pos = (close - low) / span
    upper = (high - max(open_, close)) / span
    return vol, pct, close_pos, upper


def _wudao_is_diverge_or_dump(bars: Bars, i: int) -> bool:
    """与悟道 classify 一致：吵起来了 / 像出货 压过「明天盯」。

    两个形态共用一组阈值（见顶部 `WUDAO_DIVERGE_*` / `WUDAO_DUMP_*`）：
    - 形态①：**爆量**冲高不收（量比 ≥ 2.5 且上影大 / 收盘不在高位）；
    - 形态②：量不小（≥ 1.4）、涨不动（< 2%）、留下长上影（≥ 0.3）—— `classify_phase`
      再把这一类贴上「像出货」的标签。
    """
    if i < 20:
        return False
    vol, pct, close_pos, upper = _wudao_day_geom(bars, i)
    if vol >= WUDAO_DIVERGE_VOL and (
        upper >= WUDAO_DIVERGE_UPPER or close_pos <= WUDAO_DIVERGE_CLOSE_POS
    ):
        return True
    return vol >= WUDAO_DUMP_VOL and pct < WUDAO_DUMP_PCT and upper >= WUDAO_DUMP_UPPER


def _wudao_is_sample(bars: Bars, i: int) -> bool:
    """与悟道之路 `is_sample_day` 对齐：冲高约 ≥7%、量比≥1.3、收盘离开最高。

    ⚠️ 这里是**原型口径**，2026-10-09 那道「收盘离开最高 ≤ 0.029」的过线过滤
    **没有并进来** —— 那个判据还被「洗完可盯」`_wudao_wash2` 与个股页阶段判定
    `classify_phase` 共用，并进来会把它们一起砍掉（实测各 −43%、个股页标签减半）。
    过滤只加在「明天盯 / 明天预案」两个出口，见 `_wudao_leave_ok`。
    """
    if i < 1 or i >= len(bars):
        return False
    if i < 20:
        return False
    vol, pct, close_pos, upper = _wudao_day_geom(bars, i)
    if vol < WUDAO_SAMPLE_VOL:
        return False

    prev_close = float(bars.close[i - 1])
    if prev_close <= 0:
        return False
    high = float(bars.high[i])
    high_pct = (high / prev_close - 1.0) * 100.0
    if high_pct < WUDAO_SAMPLE_HIGH_PCT:
        return False
    if pct >= 12 or high_pct >= 18:
        return False

    if close_pos >= 0.92 and upper < 0.08 and pct >= 9.5:
        return False
    leave_high = (high - float(bars.close[i])) / max(high, 1e-9)
    if leave_high < 0.028 and upper < 0.15:
        return False
    if close_pos >= 0.88 and leave_high < 0.04:
        return False
    if pct < -3:
        return False
    return True


def _wudao_leave_ok(bars: Bars, i: int) -> bool:
    """样板日的「过线概率」过滤：收盘离开最高 ≤ `WUDAO_SAMPLE_MAX_LEAVE`（见常量注释）。

    2026-10-09 加。**只作用在「明天盯 / 明天预案」两个形态的出口**，故意不并进
    `_wudao_is_sample` —— 见那个函数的 docstring。`i` 是样板日下标（「明天预案」
    检查的是**昨天**那根）。
    """
    high = float(bars.high[i])
    if high <= 0:
        return True
    return (high - float(bars.close[i])) / high <= WUDAO_SAMPLE_MAX_LEAVE


def _wudao_sample(bars: Bars) -> Signal | None:
    """明天盯：今日是样板日 —— 冲高回落有量，记下今高，今天不买。

    在原型 `_wudao_is_sample` 之上，另过一道 `_wudao_leave_ok`（收盘别离开最高太远）。
    """
    if len(bars) < WUDAO_MIN_BARS:
        return None
    i = len(bars) - 1
    if _wudao_is_diverge_or_dump(bars, i):
        return None
    if not _wudao_is_sample(bars, i):
        return None
    if not _wudao_leave_ok(bars, i):
        return None

    prev_close = float(bars.close[i - 1])
    high = float(bars.high[i])
    close = float(bars.close[i])
    high_pct = (high / prev_close - 1.0) * 100.0
    vol = _volume_ratio(bars, 20)
    leave = (high - close) / max(high, 1e-9)

    score = _band_score(high_pct, WUDAO_SAMPLE_HIGH_PCT, 12.0, 18.0) * 40
    score += _band_score(vol, WUDAO_SAMPLE_VOL, 2.5, 6.0) * 35
    # 收盘离最高越近越好（2026-10-09 那道「leave ≤ 2.9%」过滤的实测结论，见常量注释）。
    # 原来是 `_band_score(leave, 0.028, 0.08, 0.20)`：峰值落在 5.4%，越小反而越低分 ——
    # 与「越近越容易过今高」正好相反（2026-10-10 改成单方向的 `_gate_score`）。
    score += _gate_score(leave, WUDAO_SAMPLE_MAX_LEAVE, 0.0) * 25
    score = max(score, 55.0)

    return Signal(
        "wudao_sample",
        score,
        {"watch_high": high},
        {
            "high_pct": round(high_pct, 2),
            "vol_ratio_20": round(vol, 2),
            "leave_high": round(leave, 4),
            "pct_chg": round(float(bars.pct_chg[i]), 2),
        },
    )


def _wudao_start(bars: Bars) -> Signal | None:
    """明天预案：昨是样板，今放量过昨高。

    2026-10-09 从「今天可买」改名 —— 判定在**收盘后**才跑，那条买点（刚过昨高）
    当天早就过了，叫「今天可买」名不副实（成绩单也印证了：站住率 72%、但 5 日超额
    −2.5%）。它其实是一份**明天按预案跟**的名单，动手仍要等明天真正站上昨高。
    与「明天盯」一样，昨天的样板也要过 `_wudao_leave_ok`。
    """
    if len(bars) < WUDAO_MIN_BARS + 1:
        return None
    i = len(bars) - 1
    y = i - 1
    if not _wudao_is_sample(bars, y):
        return None
    if not _wudao_leave_ok(bars, y):
        return None

    sample_high = float(bars.high[y])
    today_high = float(bars.high[i])
    today_close = float(bars.close[i])
    pct = float(bars.pct_chg[i])
    vol = _volume_ratio(bars, 20)

    broke = today_high > sample_high and today_close >= sample_high * 0.98
    if not (broke and vol >= WUDAO_START_VOL and pct > 0):
        return None

    excess = today_close / sample_high - 1.0
    score = _band_score(vol, WUDAO_START_VOL, 3.0, 8.0) * 45
    score += _band_score(pct, 0.5, 8.0, 16.0) * 30
    # 刚过线更好；收盘远离昨高太多偏追高，略降分但仍可进
    if excess <= 0.04:
        score += 25
    else:
        score += _band_score(excess, 0.0, 0.04, 0.12) * 25
    score = max(score, 60.0)

    return Signal(
        "wudao_start",
        score,
        {"breakout": sample_high, "watch_high": sample_high},
        {
            "vol_ratio_20": round(vol, 2),
            "pct_chg": round(pct, 2),
            "excess": round(excess, 4),
            "sample_high": round(sample_high, 2),
        },
    )


# ---------------------------------------------------------------- 悟道「阶段判定」

# 8 个阶段的展示名与建议动作 —— 与原型 `PHASE_LABELS` / `PHASE_DO` 逐条一致。
# 这是**给单只票的一句话结论**（个股页「阶段判定」卡片用），不是选股信号；
# 选股走的是注册进上面 `PATTERNS` 的那些形态。
# （`weak` 是本站在原型 8 档之外**新增**的第 9 档，2026-10-10 —— 原型没有「在跌」
#   这一档，下跌只能落到「没动静 / 对不上」，见 `classify_phase` 的说明。）
WUDAO_PHASE_LABELS = {
    "silent": "没动静",
    "wake": "刚有人气",
    "sample": "明天盯",
    "start": "明天预案",
    "digest": "休息中",
    "diverge": "吵起来了",
    "dump": "像出货",
    "weak": "走弱",
    "unknown": "对不上",
}

WUDAO_PHASE_DO = {
    "silent": "不看，空仓",
    "wake": "先记自选，别急着买",
    "sample": "今天不买；明天过今高再买",
    "start": "盘中过昨高可小仓；收盘后看见别追明天",
    "digest": "有仓看分时均价；没仓别抄",
    "diverge": "只卖不加",
    "dump": "减仓走人，别接",
    "weak": "有仓逢反抽减，没仓不接",
    "unknown": "空仓，等对上模板再说",
}


@dataclass(frozen=True, slots=True)
class PhaseVerdict:
    """一只票当天的阶段判定：8 个标签之一 + 一眼看懂的说明。"""

    phase: str
    label: str
    action: str
    text: str
    fit_label: str
    fit_text: str
    prefer: int
    shadow_label: str
    shadow_text: str
    pressure_label: str
    pressure_text: str
    plan_text: str
    risk_text: str
    watch_price: float | None
    metrics: dict[str, float | None]


def classify_phase(bars: Bars) -> PhaseVerdict | None:
    """整只票的阶段判定（移植自原型的 `classify_bars` + `_structure_brief`）。

    ⚠️ 与 `PATTERNS` 里的 `wudao_sample` / `wudao_start` **共用同一批判据**
    （`_wudao_is_sample` / `_wudao_is_diverge_or_dump` / `_wudao_day_geom`）——
    别在这里另写一套：两边分叉过一次，回测数字就不再代表生产。

    ⚠️ **但「共用判据」不等于「结果一致」**（2026-10-09 起，名单那侧多了两道过滤，
    两处都**故意**没写进这里）：
    - 名单只收**创业板 + 科创板**（`scan_patterns.is_wudao_board`），这里**全市场都判**
      —— 主板票也会被贴上「明天盯」，而名单里永远不会有它；
    - 名单出口另有一道 `_wudao_leave_ok`（收盘离开最高 ≤ 2.9%，见 §8.88.3）——
      它没并进 `_wudao_is_sample`，因为那个判据还被「洗完可盯」共用。
    实测 2026-09-28：这里判「明天盯」的 31 只里只有 6 只在名单。

    优先级在原型基础上把「走弱」提前到「刚有人气」之前：**启动 > 吵起来了 / 像出货 >
    明天盯 > 休息中 > 走弱 > 刚有人气 > 没动静**。这也是「明明冲高回落了、为什么没进明天盯」
    的答案 —— 它被更靠前的阶段占了（`_wudao_sample` 那边同样先过 `_wudao_is_diverge_or_dump`）。

    阈值都在文件顶部 `WUDAO_WAKE_*` / `WUDAO_DIGEST_*` / `WUDAO_WEAK_PCT` / `WUDAO_SILENT_VOL`
    那一段（2026-10-10 从函数体里抽出来集中的），别在下面的分支里再写裸数字。

    ⚠️ **对原型的四处修正 + 新增一档**（都做过实测，都是「标签与当日事实自相矛盾」）：

    1. **缩量大涨兜底**（2026-10-09）：`pct >= 9.5` 或（`pct >= 4` 且 `high_pct >= 6`）→ `wake`。
       原型直接按 `vol < 0.85` 判「没动静」，会把**缩量涨停 / 一字板**（量比常 0.3~0.8）
       说成「几乎没人气」（实测 4 只）。这类归 `wake`、文案另写（见 `thin_up` 分支）。
    2. **新增 `weak`（走弱）档**（2026-10-10）：`pct <= -3` → `weak`。原型没有「在跌」
       这一档，下跌只能落到「没动静 / 对不上」—— 实测 2026-09-28 前 1500 只里
       **102 只（6.8%）跌 3%~5%、量比 0.4~0.8 被判「没动静」**（文案还写着「几乎没人气」）。
       下界取 -3 与 `digest` 的下界**正好接上**，不留缝；这也把原先那条
       `pct <= -5 → unknown` 的兜底**收编**成了一个正式档（≤ -5 的大跌同样归 `weak`）。
    3. **`digest` 补下界**（2026-10-09）：`-3 <= pct <= 0`。原来只写 `pct <= 0`，跌停也会进
       「休息中」，与它自己的文案「涨跌不大，像在歇口气」直接冲突（实测 7 只、含 4 只跌停）。
    4. **`weak` 提到 `wake` 之前**（2026-10-10）：wake 里有条按 `high_pct >= 6` 判的支路，
       会把**高开 ≥6% 却收跌 ≤ -3%** 的票判成「刚有人气」（量回来了、价格也动了），与事实
       正好相反。让 `weak` 先判，这类一律归「走弱」。wake 与 thin 两条支路都要求 pct 为正，
       所以搬动不影响它们。

    `weak` 与 `digest` 的分工：`weak` **只看跌幅**（在跌就算走弱，放量缩量都算）；
    `digest` 是「涨过一截之后缩量歇气」（还要求近 5 日涨过 `WUDAO_DIGEST_RET5`）。
    所以两者不会抢：跌幅 ≤ -3 一律 `weak`，`digest` 只在 -3%~0 这一段、且前面刚涨过时才成立。
    """
    n = len(bars)
    if n < 25:
        return None
    i = n - 1
    vol, pct, close_pos, upper = _wudao_day_geom(bars, i)
    close = float(bars.close[i])
    high = float(bars.high[i])
    prev_close = float(bars.close[i - 1])
    yday_high = float(bars.high[i - 1])
    high_pct = (high / prev_close - 1.0) * 100.0 if prev_close else 0.0
    leave_high = (high - close) / max(high, 1e-9)
    ret_5 = (close / float(bars.close[i - 5]) - 1.0) * 100.0 if float(bars.close[i - 5]) else 0.0
    ret_20 = (
        (close / float(bars.close[i - 20]) - 1.0) * 100.0 if float(bars.close[i - 20]) else 0.0
    )
    yday_sample = _wudao_is_sample(bars, i - 1)
    today_sample = _wudao_is_sample(bars, i)
    broke_yday_high = high > yday_high and close >= yday_high * 0.98

    # ---- 决策链：从上往下问，**第一个成立的就是结论** ----
    # 顺序（= 优先级）：启动 > 吵/出货 > 明天盯 > 休息中 > 走弱 > 刚有人气 > 没动静 > 兜底。
    # 「走弱」刻意排在「刚有人气」**之前**（2026-10-10 调序）：高开 ≥6%（`high_pct` 达标）
    # 却收跌 ≤ -3% 的票，原先把 wake 排前面会判成「刚有人气」，与 wake 的语义相反。
    # 两个「兜底」都刻意放在**量能判据之前**：只看量的话，缩量涨停（量比 0.3~0.8）与
    # 缩量下跌都会掉进 `silent`、被说成「几乎没人气」，与当天涨停 / 大跌的事实冲突
    # （实测分别 4 只、102 只）。阈值见文件顶部 `WUDAO_WAKE_*` 那一段。
    thin_up = False
    if yday_sample and broke_yday_high and vol >= WUDAO_START_VOL and pct > 0:
        # 昨天是样板日、今天放量过昨高 → 启动
        phase = "start"
    elif _wudao_is_diverge_or_dump(bars, i):
        dump_like = vol >= WUDAO_DUMP_VOL and pct < WUDAO_DUMP_PCT and upper >= WUDAO_DUMP_UPPER
        # 原型是两条（吵起来了 / 像出货），标签要分开；判据在共用的那个函数里
        phase = "dump" if dump_like else "diverge"
    elif today_sample:
        # 今天自己就是样板日。`_wudao_is_sample` 内部要求 `pct >= -3`，
        # 所以下跌日走不到这里，不必另判
        phase = "sample"
    elif (
        WUDAO_DIGEST_PCT_LO <= pct <= 0
        and vol <= WUDAO_DIGEST_VOL
        and ret_5 >= WUDAO_DIGEST_RET5
    ):
        # 「休息中」= 前面涨过一截、今天缩量且涨跌不大。下界与「走弱」接上（见 docstring）
        phase = "digest"
    elif pct <= WUDAO_WEAK_PCT:
        # 「走弱」：**只看跌幅**，放量缩量都算（2026-10-10 新增，取代原先
        # `pct <= -5 → unknown` 的临时兜底 —— 那一版把 -5%~-3% 这段漏给了「没动静」）。
        # 排在这里是为了压住下面那条按 `high_pct` 判的 wake（见上「调序」说明）
        phase = "weak"
    elif vol >= WUDAO_WAKE_VOL and (pct >= WUDAO_WAKE_PCT or high_pct >= WUDAO_WAKE_HIGH_PCT):
        # 「刚有人气」：量回来了、价格也动了（今天是不是样板日已在上面拦掉，不必再判）
        phase = "wake"
    elif pct >= WUDAO_THIN_UP_PCT or (pct >= WUDAO_WAKE_PCT and high_pct >= WUDAO_WAKE_HIGH_PCT):
        # 缩量大涨兜底：涨幅够大但量没跟上（涨停 / 一字板常这样），仍归「刚有人气」，
        # 只是文案另写（`thin_up`）。能走到这里说明上面那条量能条件不成立。
        phase = "wake"
        thin_up = True
    elif vol < WUDAO_SILENT_VOL:
        phase = "silent"
    else:
        phase = "unknown"

    # ---- 结构简报：上影天数 / 左侧压力 / 计划 / 风险 ----
    recent_n = min(8, n)
    shadow_days = 0
    leave_sum = 0.0
    for k in range(n - recent_n, n):
        span = max(float(bars.high[k]) - float(bars.low[k]), 1e-9)
        up = (float(bars.high[k]) - max(float(bars.open[k]), float(bars.close[k]))) / span
        leave_sum += (float(bars.high[k]) - float(bars.close[k])) / max(float(bars.high[k]), 1e-9)
        if up >= 0.35:
            shadow_days += 1
    avg_leave = leave_sum / max(recent_n, 1)

    if shadow_days >= 5 and avg_leave >= 0.04:
        shadow_label = "天天长上影"
        shadow_text = (
            f"近 8 个交易日里有 {shadow_days} 天带明显长上影，平均离最高点约 {avg_leave:.0%}："
            "冲得猛、回得也猛，多空一直在打架。偶发一次可以是洗；天天都有更像分歧票，"
            "难拿、假突破也多。"
        )
        noisy = True
    elif shadow_days >= 5:
        shadow_label = "上影偏多"
        shadow_text = f"近 8 日有 {shadow_days} 天带上影，但回落幅度还不算极端。有点吵，仍可盯，仓位要小。"
        noisy = True
    elif shadow_days >= 3:
        shadow_label = "上影偏多"
        shadow_text = f"近 8 日有 {shadow_days} 天长上影，上方抛压不轻，过昨高后也要防冲高回落。"
        noisy = True
    elif upper >= 0.35:
        shadow_label = "今天有上影"
        shadow_text = "今天冲高没完全站住，更像「画样子」回落，不是单边封死。"
        noisy = False
    else:
        shadow_label = "上影不多"
        shadow_text = "最近不是天天冲高回落，形态相对干净一些。"
        noisy = False

    # 左侧压力 = 「近 60 / 120 日最高」。**只算 120 日这个就够** —— 60 日窗口是它的
    # 子集，取 120 日必然 ≥ 60 日，原先那两个变量再 max() 一次是纯冗余（2026-10-10 删）。
    # `n >= 30` 是本来的经验下限（不足两根月线就不谈左侧压力），保持原样：
    # 它意味着 25~29 根时 `left_high=None`、下面那几段压力文案整块不出现。
    left_high = float(np.max(bars.high[max(0, n - 120) :])) if n >= 30 else None
    low_20 = float(np.min(bars.low[n - 20 :]))
    ma20 = float(np.mean(bars.close[n - 20 :]))
    ma60 = float(np.mean(bars.close[n - 60 :])) if n >= 60 else None

    pressure_bits: list[str] = []
    if left_high and left_high > 0:
        dist = (left_high - close) / left_high * 100
        if dist >= 20:
            pressure_bits.append(
                f"离近几个月高点 {left_high:.2f} 还有约 {dist:.0f}%，上方有一段下跌留下的套牢区（左侧压力）。"
            )
        elif dist >= 10:
            pressure_bits.append(f"上方不远有前高/套牢带（约 {left_high:.2f}），冲过去容易滞涨。")
    if ma20 and close < ma20 * 0.98 and ret_5 > 0:
        pressure_bits.append(f"价格还在 20 日线（约 {ma20:.2f}）下方附近抬头，反弹时容易碰到均线压力。")
    if ma60 and close >= ma60 * 0.97 and close <= ma60 * 1.05:
        pressure_bits.append(f"正蹭着 60 日线一带（约 {ma60:.2f}），这里常有多空分歧。")
    if low_20 and left_high and (close - low_20) / max(left_high - low_20, 1e-9) < 0.45 and ret_20 < 15:
        pressure_bits.append("更像底部反抽探路，不是主升中段；过昨高只是短线确认，别当一飞冲天。")

    # 样板质量：回落温和 + 冲高没太猛 → 更像「干净样板」
    mild_pullback = avg_leave <= 0.045 and high_pct <= 10
    if phase == "sample" and mild_pullback and vol >= 1.5 and not (shadow_days >= 5 and avg_leave >= 0.05):
        fit_label, prefer = "更像你要的", 3
        fit_text = "冲高回落 + 有量，回落幅度相对温和，比较像「先画出样子再等确认」。"
        if pressure_bits:
            fit_text += " 但上方有左侧压力，过昨高后别幻想直奔前高。"
    elif phase == "sample" and noisy and avg_leave >= 0.05:
        fit_label, prefer = "勉强算样板，但偏吵", 1
        fit_text = (
            "也冲高回落了所以进了「明天盯」，但最近老是大幅冲高回落，质量不如干净样板。"
            "可观察，不必跟更干净的票抢仓。"
        )
    elif phase == "sample" and noisy:
        fit_label, prefer = "能盯，略吵", 2
        fit_text = "符合「明天盯」，但上影偏多。能盯，仓位要小；有更干净的票时优先别人。"
    elif phase == "sample":
        fit_label, prefer = "能盯，中等", 2
        fit_text = "符合「明天盯」的基本样子，质量中等。过今高可小仓，不过就空着。"
    elif phase == "start" and not noisy:
        fit_label, prefer = "启动较干净", 3
        fit_text = "过昨高且量跟上了。买点是刚过那一下；收盘后才看见大涨贴板，明天别追。"
    elif phase == "start":
        fit_label, prefer = "启动但带分歧", 1
        fit_text = "算启动，但上影/波动大，只能极小仓或等回踩分时均价，别追尖。"
    elif phase in ("diverge", "dump"):
        fit_label, prefer = "不像启动模板", 0
        fit_text = "现在是刹车灯，不是油门。别当样板/启动去追。"
    elif phase == "weak":
        fit_label, prefer = "在往下走", 0
        fit_text = "不符合任何动手模板，而且今天在跌。别当机会看，等它重新走出样板日。"
    else:
        fit_label, prefer = "还没到动手档", 0
        fit_text = "还没走到「明天盯 / 明天预案」。先放着，别空耗仓位。"

    if phase == "sample":
        plan_text = (
            f"今天不买。下一个交易日盯今高 {high:.2f}：刚过可小仓；不过就空着；"
            "过了又快速掉回今高下，当假突破。"
        )
        if noisy:
            plan_text += " 这只偏吵，仓位要比更干净的票更小，甚至可以只观察不做。"
        if pressure_bits:
            plan_text += " 过了也不要幻想直奔前高，碰到左侧压力滞涨就减。"
    elif phase == "start":
        plan_text = (
            f"买点是盘中刚过昨高 {yday_high:.2f}。若你是收盘后才看到、已经大涨，"
            "默认下一个交易日不追。"
        )
    elif phase in ("diverge", "dump"):
        plan_text = "只减不加。没仓就别上车。"
    elif phase == "digest":
        plan_text = "有仓用分时均价：跌破减/清。没仓别抄。"
    elif phase == "weak":
        plan_text = "有仓：反抽不过昨高就减；没仓：不接飞刀。"
    else:
        plan_text = WUDAO_PHASE_DO[phase]

    if phase == "start":
        text = f"昨天冲高回落过，今天已经过了昨高 {yday_high:.2f}，量比 {vol:.2f}。"
    elif phase == "diverge":
        text = f"量很大（量比 {vol:.2f}），但冲高没站住（上影约 {upper:.2f}），多空在打架。"
    elif phase == "dump":
        text = f"量不小（量比 {vol:.2f}），价格却涨不动、冲完就回，更像有人在出。"
    elif phase == "sample":
        text = (
            f"今天冲过大约 {high_pct:.1f}% 又收回来，量比 {vol:.2f}；"
            f"记下今高 {high:.2f}，明天过了再买，不过就空着。"
        )
    elif phase == "digest":
        text = f"前几天已经拉过一截，今天量缩（量比 {vol:.2f}）、涨跌不大，像在歇口气。"
    elif phase == "weak":
        text = f"今天跌 {pct:.1f}%、量比 {vol:.2f}，在走弱；没重新走出样板日之前不值得看。"
    elif phase == "wake":
        if thin_up:
            text = (
                f"今天涨 {pct:.1f}%、量比 {vol:.2f} —— 量能没跟上（封板/一字也会锁着量）。"
                "别按「放量启动」看待，等明天看量能能不能接上。"
            )
        else:
            text = f"量开始回来（量比 {vol:.2f}），价格也动了，但还没走出「冲高再回落」的样子。"
    elif phase == "silent":
        text = f"量比只有 {vol:.2f}，几乎没人气；这种票很少第二天就起飞。"
    else:
        text = f"量比 {vol:.2f}，涨跌 {pct:.2f}%，暂时对不上模板。"

    action = WUDAO_PHASE_DO[phase]
    if phase == "start" and (upper >= 0.28 or close_pos < 0.65):
        text += " 今天上影不小，即使算可买也只能极小仓，冲高先减。"
        action = "极小仓；更稳是等回踩分时均价"

    risk_bits: list[str] = []
    if phase == "weak":
        risk_bits.append("今天在往下走，别在下跌里找买点")
    if pressure_bits:
        risk_bits.append("左侧/均线压力，冲高易滞涨")
    if noisy:
        risk_bits.append("反复长上影，假突破多")
    if ret_5 >= 25:
        risk_bits.append(f"近 5 日已涨约 {ret_5:.0f}%，别当起涨点猛加")
    if vol >= 3 and close_pos < 0.7:
        risk_bits.append("爆量却收不在高位，分歧大")
    if not risk_bits:
        risk_bits.append("不过昨高不要进；破分时均价要会走")

    if pressure_bits:
        pressure_label, pressure_text = "左侧有压力", " ".join(pressure_bits[:3])
    else:
        pressure_label = "上方压力不明显"
        pressure_text = "按近期结构看，没有特别扎眼的左侧大套牢墙；仍要用分时均价管风险。"

    watch_price = high if phase == "sample" else (yday_high if phase == "start" else None)

    return PhaseVerdict(
        phase=phase,
        label=WUDAO_PHASE_LABELS[phase],
        action=action,
        text=text,
        fit_label=fit_label,
        fit_text=fit_text,
        prefer=prefer,
        shadow_label=shadow_label,
        shadow_text=shadow_text,
        pressure_label=pressure_label,
        pressure_text=pressure_text,
        plan_text=plan_text,
        risk_text="；".join(risk_bits) + "。",
        watch_price=round(watch_price, 2) if watch_price else None,
        metrics={
            "close": round(close, 2),
            "pct_chg": round(pct, 2),
            "high_pct": round(high_pct, 1),
            "vol_ratio": round(vol, 2),
            "close_pos": round(close_pos, 2),
            "upper_shadow": round(upper, 2),
            "leave_high": round(leave_high, 4),
            "ret_5": round(ret_5, 1),
            "ret_20": round(ret_20, 1),
            "yday_high": round(yday_high, 2),
            "today_high": round(high, 2),
            "ma20": round(ma20, 2) if ma20 else None,
            "left_high": round(left_high, 2) if left_high else None,
            "shadow_days": shadow_days,
        },
    )


def _wudao_day_volume_ratio(bars: Bars, i: int) -> float:
    """第 i 根的**量比** = 当日量 ÷ 近 20 日均量（不含当日），口径与 `_wudao_day_geom` 一致。

    与悟道之路的 `enrich` 有一处小差别：它 `vol_ma20 = volume.rolling(20).mean()` 是
    **含当日**的，我们是不含当日。在 1.3~1.5 这些门槛附近两者差不到 3%
    （解一下方程：要打到量比 1.3，含当日口径其实只要 1.32 倍的「前 20 日均量」），
    所以 2026-09-23 那次对账两边计数才会完全一致。**站内一律用这一套**
    （含当日的写法会让一根爆量把分母自己抬高、量比反而变小，不同口径混用比统一更重要）。
    """
    if i < 20:
        return 0.0
    base = _safe_mean(bars.volume[i - 20 : i])
    return float(bars.volume[i] / base) if base > 0 else 0.0


def _wudao_wash2(bars: Bars) -> Signal | None:
    """洗完 → 明天可进（悟道之路「辉宾选股2」，2026-10-08 移植）。

    四段结构：**样板日 → 启动日 → 今日洗盘 → 明天放量过「洗高」**。
    前两段的判定与「明天盯 / 明天预案」**完全同一套**（复用 `_wudao_is_sample` 与同组数字），
    第三段是本形态新增的：洗盘日要守住两个锚点（启动低 / 样板高）、收盘温和、不是继续主升。

    数字全部照抄 `yangban-desk/app/pattern_wash2.py`（commit fe32f80），逐条见文件上方常量。
    它的纪律（`选股逻辑说明.txt` 六段口诀）：**今天是洗盘日 → 只观察记账，不追尖、不加仓**；
    明天盘中放量过洗高再小仓；缩量阴过洗高不算；破启动低（或放量破样板高且收不回）作废。

    出参把两条线一起给前端：`watch_high`（明天要过的线）、`start_low`（作废线）。
    """
    if len(bars) < WUDAO_WASH_MIN_BARS:
        return None
    i = len(bars) - 1
    s, st, w = i - 2, i - 1, i  # 样板 / 启动 / 今日洗盘

    # ① 样板日：与「明天盯」共用 `_wudao_is_sample`（但**不含**吵了/出货的否决 ——
    #    那道 `_wudao_is_diverge_or_dump` 只加在「明天盯 / 明天预案」两个出口，这里没有）
    if not _wudao_is_sample(bars, s):
        return None
    sample_high = float(bars.high[s])

    # ② 启动日：今过昨高 + 收盘站在昨高之上 + 量比达标 + 收红
    start_pct = float(bars.pct_chg[st])
    start_vol = _wudao_day_volume_ratio(bars, st)
    if float(bars.high[st]) <= sample_high:
        return None
    if float(bars.close[st]) < sample_high * 0.98:
        return None
    if start_vol < WUDAO_START_VOL or start_pct <= 0:
        return None

    # ③ 今日洗盘：四个锚点条件
    start_close = float(bars.close[st])
    start_low = float(bars.low[st])
    wash_open = float(bars.open[w])
    wash_close = float(bars.close[w])
    wash_low = float(bars.low[w])
    wash_high = float(bars.high[w])
    wash_pct = float(bars.pct_chg[w])
    start_volume = float(bars.volume[st])
    wash_volume = float(bars.volume[w])
    vol_vs = wash_volume / start_volume if start_volume > 0 else 1.0

    if wash_low < start_low * 0.995:  # 破启动低
        return None
    if wash_close < sample_high * 0.98:  # 掉下样板高
        return None
    if abs(wash_pct) > WUDAO_WASH_MAX_ABS_PCT:
        return None
    body_pct = abs(wash_close - wash_open) / max(start_close, 1e-9) * 100.0
    if body_pct > WUDAO_WASH_MAX_BODY_PCT and wash_pct > 2:  # 大阳续涨不算洗
        return None
    if wash_close > start_close * WUDAO_WASH_MAX_VS_START_CLOSE:
        return None

    # 打分：越干净的洗盘分越高。干净的判据与它一致 —— |洗盘涨跌|≤2% 且 量/启动 ≤1.05
    clean = abs(wash_pct) <= 2.0 and vol_vs <= 1.05
    score = 62.0 if clean else 54.0
    score += _band_score(start_vol, WUDAO_START_VOL, 3.0, 8.0) * 18
    # 洗盘越温和越高（单方向）。原来是 `_band_score(abs(wash_pct), 0.0, 3.0, 8.0)`：
    # `_band_score` 对 value<=0 直接给 0 分 —— 恰好把最温和的「平盘洗」打成 0，
    # 与注释相反（2026-10-10 改成 `_gate_score`）。上面已否决 |wash_pct|>3。
    score += _gate_score(abs(wash_pct), WUDAO_WASH_MAX_ABS_PCT, 0.0) * 12
    if vol_vs <= 1.05:
        score += 8

    return Signal(
        "wudao_wash2",
        score,
        # 两条线：明天要过洗高才进；破了启动低就作废
        {"watch_high": wash_high, "start_low": start_low, "breakout": wash_high},
        {
            "sample_high": round(sample_high, 2),
            "start_low": round(start_low, 2),
            "start_close": round(start_close, 2),
            "start_pct": round(start_pct, 2),
            "start_vol_ratio": round(start_vol, 2),
            "wash_high": round(wash_high, 2),
            "wash_pct": round(wash_pct, 2),
            "wash_vol_vs_start": round(vol_vs, 2),
            "clean": clean,
        },
    )


# ------------------------------------------------- 悟道之路 · 强达型（2026-10-08 移植）


def _ret_pct(bars: Bars, index: int, back: int) -> float:
    """第 index 根相对 `back` 个交易日前的涨幅（%）。`back=5` 就是悟道的 `ret_5`。"""
    base_index = index - back
    if base_index < 0:
        return 0.0
    base = float(bars.close[base_index])
    return (float(bars.close[index]) / base - 1.0) * 100.0 if base > 0 else 0.0


def _pile_wash_phase(bars: Bars) -> tuple[str, dict] | None:
    """强达型的阶段判定，返回 `(阶段, 指标)`。

    逐行照抄 `yangban-desk/app/pile_wash.py::score_pile_wash`（commit fe32f80），
    只把 pandas 的 `iloc` 切片换成 numpy 下标：

    1. 在**最近 55 根**里滑窗找「放量拉升」段（宽度 5~12、段内最高 / 前基 ≥16%、
       段末收盘 / 前基 ≥10%、段均量 / 前段均量 ≥1.35、阳线数 ≥ max(2, 宽度//3)），
       给每个候选打分（涨幅×0.45 + 放量×12 + 收盘涨幅×0.25 + 阳线数；收盘位置偏低 ×0.7；
       拉升后已经缩量的加分），取最高分的那个窗口
    2. 判前段堆量（≥1.25 倍、不是单边暴跌、振幅 <38%）
    3. 判后段缩量洗盘（量 ≤ 拉升期 0.72、守住前基 ×1.05、回吐 <0.62、振幅 ≤28%）
    4. 洗盘成立再看形态走到哪：贴着/越过洗盘高 → `ready`；已远离且 5 日大涨 → `gone`；
       回撤过大 → `gone`；其余 → `wash`

    ⚠️ 它那套的 `pile`（堆量吸筹中，含「只有堆量、还没拉升」那条 `_maybe_pile_only` 分支）
    我们**不出信号**，直接返回 None —— 纪律是「只观察，别动手」。
    """
    n = len(bars.close)
    if n < PILE_MIN_BARS:
        return None
    off = max(0, n - PILE_LOOK_BARS)  # look 的起点（绝对下标）
    total = n - off  # look 的长度
    if total < 30:
        return None

    def mean_vol(start: int, end: int) -> float:
        """look 上 `[start, end]` 闭区间的均量（绝对下标）。"""
        lo, hi = off + start, off + end + 1
        return float(np.mean(bars.volume[lo:hi])) if hi > lo else 0.0

    best: tuple | None = None
    for end in range(8, total):
        for width in PILE_SURGE_WIDTHS:
            start = end - width + 1
            if start < 5:
                continue
            pre_start = max(0, start - 18)
            if start - pre_start < PILE_PRE_MIN_BARS:
                continue
            base = float(bars.close[off + start - 1])
            if base <= 0:
                continue
            peak = float(np.max(bars.high[off + start : off + end + 1]))
            end_close = float(bars.close[off + end])
            surge_ret = (peak / base - 1.0) * 100.0
            close_ret = (end_close / base - 1.0) * 100.0
            if surge_ret < PILE_SURGE_MIN_RET or close_ret < PILE_SURGE_MIN_CLOSE_RET:
                continue
            vol_s = mean_vol(start, end)
            vol_p = mean_vol(pre_start, start - 1) or 1.0
            vol_lift = vol_s / vol_p
            if vol_lift < PILE_SURGE_MIN_VOL_LIFT:
                continue
            window_close = bars.close[off + start : off + end + 1]
            window_open = bars.open[off + start : off + end + 1]
            yang = int(np.sum(window_close >= window_open))
            if yang < max(2, width // 3):
                continue
            lowest = float(np.min(bars.low[off + start : off + end + 1]))
            close_pos = (end_close - lowest) / max(peak - lowest, 1e-9)
            score = surge_ret * 0.45 + vol_lift * 12 + close_ret * 0.25 + yang
            if close_pos < 0.55:
                score *= 0.7
            # 更偏向「拉升后还有缩量段」的窗口（强达那种中段），避免只咬住最近的主升尖
            after_len = total - 1 - end
            if after_len >= 4:
                tail_end = min(end + 14, total - 1)
                wr = mean_vol(end + 1, tail_end) / max(vol_s, 1.0)
                if wr <= PILE_WASH_MAX_VOL_RATIO:
                    score += 18 + (PILE_WASH_MAX_VOL_RATIO - wr) * 20
                elif wr <= 0.9:
                    score += 6
            else:
                score *= 0.85
            cand = (score, start, end, surge_ret, vol_lift, base, peak)
            if best is None or cand[0] > best[0]:
                best = cand

    if best is None:
        return None  # 没找到拉升窗口 → 只有可能落在「堆量」那一档，我们不出信号

    _, s0, s1, surge_ret, vol_lift, base, surge_high = best
    last_i = total - 1

    # —— ① 拉升前是否有堆量 ——
    pile_ok = False
    pile_ratio: float | None = None
    pre_start = max(0, s0 - 22)
    pre_len = s0 - pre_start
    if pre_len >= 10:
        quiet_end = max(5, pre_len // 2)  # 相对 pre 的前半段
        quiet_vol = mean_vol(pre_start, pre_start + quiet_end - 1) or 1.0
        pile_vol = mean_vol(pre_start + quiet_end, s0 - 1)
        pile_ratio = pile_vol / quiet_vol
        pre_ret = (
            float(bars.close[off + s0 - 1]) / float(bars.close[off + pre_start]) - 1.0
        ) * 100.0
        pre_range = (
            float(np.max(bars.high[off + pre_start : off + s0]))
            / max(float(np.min(bars.low[off + pre_start : off + s0])), 1e-9)
            - 1.0
        ) * 100.0
        pile_ok = (
            pile_ratio >= PILE_PILE_MIN_RATIO
            and pre_ret > PILE_PILE_MIN_PRE_RET
            and pre_range < PILE_PILE_MAX_PRE_RANGE
        )

    # —— ② 拉升后是不是缩量洗盘 ——
    wash_days = last_i - s1
    phase = "surge"
    wash_vol_ratio: float | None = None
    wash_high: float | None = None
    wash_low: float | None = None
    giveback: float | None = None
    if wash_days >= 3:
        wash_end = min(s1 + 18, last_i)  # 洗盘超过 18 根只取前 18 根
        vol_surge = mean_vol(s0, s1) or 1.0
        vol_wash = mean_vol(s1 + 1, wash_end)
        wash_vol_ratio = vol_wash / vol_surge
        wash_high = float(np.max(bars.high[off + s1 + 1 : off + wash_end + 1]))
        wash_low = float(np.min(bars.low[off + s1 + 1 : off + wash_end + 1]))
        peak_close = float(np.max(bars.close[off + s0 : off + s1 + 1]))
        wash_close = float(bars.close[off + wash_end])
        giveback = (peak_close - wash_close) / max(peak_close - base, 1e-9)
        held = wash_close >= base * PILE_WASH_KEEP_ABOVE_BASE
        not_dump = giveback < PILE_WASH_MAX_GIVEBACK
        vol_shrink = wash_vol_ratio <= PILE_WASH_MAX_VOL_RATIO
        tight = (wash_high / max(wash_low, 1e-9) - 1.0) * 100.0 <= PILE_WASH_MAX_RANGE_PCT

        if vol_shrink and held and not_dump and tight:
            phase = "wash"
            close = float(bars.close[n - 1])
            vol_ratio = _wudao_day_volume_ratio(bars, n - 1)
            pct_now = float(bars.pct_chg[n - 1])
            near = close >= wash_high * PILE_READY_NEAR
            broke = close > wash_high and last_i > s1
            if broke and close > wash_high * PILE_GONE_ABOVE and _ret_pct(
                bars, n - 1, 5
            ) > PILE_GONE_RET5:
                phase = "gone"
            elif broke or (near and vol_ratio >= PILE_READY_MIN_VOL and pct_now > 0):
                phase = "ready"
        elif giveback > 0.75:
            phase = "gone"

    if last_i <= s1:  # 仍在拉升窗内
        phase = "surge"

    metrics = {
        "pile_ok": pile_ok,
        "pile_ratio": pile_ratio,
        "surge_ret": surge_ret,
        "vol_lift": vol_lift,
        "surge_high": surge_high,
        "wash_days": wash_days,
        "wash_vol_ratio": wash_vol_ratio,
        "wash_high": wash_high,
        "wash_low": wash_low,
        "giveback": giveback,
        # 位置维度（2026-10-09 加）：现价 / MA60。见 PILE_WASH_MIN_POS_MA60
        "pos_ma60": float(bars.close[n - 1])
        / max(float(np.mean(bars.close[max(0, n - 60) : n])), 1e-9),
        "surge_start_gap": last_i - s1,  # 拉升段结束距今几根（诊断用）
    }
    return phase, metrics


def _pile_wash_signal(bars: Bars, want: str) -> Signal | None:
    """强达型两个形态的公共出口：只在阶段等于 `want` 时出信号。"""
    result = _pile_wash_phase(bars)
    if result is None:
        return None
    phase, m = result
    if phase != want or m["wash_high"] is None:
        return None
    # 位置门槛（2026-10-09 加）：只卡「缩量洗盘中」这一格 —— 单看结构它就是
    # 全市场平均（安静型标签没有筛选力）。见 PILE_WASH_MIN_POS_MA60 的实测数字。
    if want == "wash" and float(m["pos_ma60"]) < PILE_WASH_MIN_POS_MA60:
        return None

    wash_high = float(m["wash_high"])
    wash_low = float(m["wash_low"]) if m["wash_low"] is not None else None
    shrink = m["wash_vol_ratio"]
    # 打分：洗后可盯（要动手的）> 缩量洗盘中（主观察）。缩得越干净、前面有堆量，分越高
    score = 68.0 if want == "ready" else 56.0
    if shrink is not None:
        score += min(14.0, max(0.0, (PILE_WASH_MAX_VOL_RATIO - float(shrink)) * 40.0))
    if m["pile_ok"]:
        score += 6.0
    score = min(score, 95.0)

    levels: dict[str, float] = {"breakout": wash_high, "wash_high": wash_high}
    if wash_low is not None:
        levels["wash_low"] = wash_low
    detail: dict[str, float | int] = {
        "surge_ret": round(float(m["surge_ret"]), 2),
        "vol_lift": round(float(m["vol_lift"]), 2),
        "wash_days": int(m["wash_days"]),
        "pile_ok": int(bool(m["pile_ok"])),
    }
    if shrink is not None:
        detail["wash_vol_ratio"] = round(float(shrink), 2)
    if m["giveback"] is not None:
        detail["giveback"] = round(float(m["giveback"]), 3)
    if m["pile_ratio"] is not None:
        detail["pile_ratio"] = round(float(m["pile_ratio"]), 2)
    return Signal(f"pile_wash_{want}", score, levels, detail)


def _pile_wash_ready(bars: Bars) -> Signal | None:
    """洗后可盯：缩量洗完，现价刚贴近/越过洗盘高 —— 盘中放量过洗盘高可小仓试。

    判据见 `_pile_wash_phase`；「过洗盘高」那条线在 `key_levels["breakout"]`。
    """
    return _pile_wash_signal(bars, "ready")


def _pile_wash_wash(bars: Bars) -> Signal | None:
    """缩量洗盘中：拉升后横着、量掉回拉升期 —— 主观察，记下洗盘高，缩量别乱砍。

    2026-10-09 起多一道**位置门槛**（现价 ≥ MA60×1.08）：单看结构它等于全市场平均，
    只在「现价站在中期均线上方」这一半里才留，理由与实测见 `PILE_WASH_MIN_POS_MA60`。
    """
    return _pile_wash_signal(bars, "wash")


# ------------------------------------------------- 悟道之路 · 华宝早期（2026-10-08 移植）


def _ema(values: np.ndarray, span: int) -> np.ndarray:
    """指数移动平均，与 pandas `ewm(span, adjust=False)` 同口径（首值取第一个样本）。"""
    out = np.empty(values.size, dtype=float)
    if values.size == 0:
        return out
    alpha = 2.0 / (span + 1.0)
    out[0] = float(values[0])
    for i in range(1, values.size):
        out[i] = alpha * float(values[i]) + (1.0 - alpha) * out[i - 1]
    return out


def _macd_tail(bars: Bars, count: int = 3) -> tuple[list[float], list[float]]:
    """最近 `count` 根的 `(MACD, DIF)`，口径与悟道一致：

    `DIF = EMA12 − EMA26`、`DEA = EMA9(DIF)`、`MACD = (DIF − DEA) × 2`。
    """
    close = bars.close.astype(float)
    dif = _ema(close, 12) - _ema(close, 26)
    dea = _ema(dif, 9)
    macd = (dif - dea) * 2.0
    take = slice(max(0, close.size - count), close.size)
    return [float(x) for x in macd[take]], [float(x) for x in dif[take]]


def _huabao_is_yang(bars: Bars, i: int) -> bool:
    """阳线：收 ≥ 开 **且** 当日涨幅 ≥ 0（只满足一个不算）。"""
    return float(bars.close[i]) >= float(bars.open[i]) and float(bars.pct_chg[i]) >= 0.0


def _huabao_hug_ma5(bars: Bars, i: int) -> bool:
    """贴着 5 日线抬（日线近似，与悟道的 `_hug_ma5` 同一组数字）。

    MA5 取**含当日**的 5 根收盘均值（pandas `rolling(5).mean()` 同口径）。
    """
    if i < 4:
        return False
    ma5 = _safe_mean(bars.close[i - 4 : i + 1])
    if ma5 <= 0:
        return False
    low = float(bars.low[i])
    close = float(bars.close[i])
    open_ = float(bars.open[i])
    high = float(bars.high[i])
    pct = float(bars.pct_chg[i])
    low_gap = (low - ma5) / ma5 * 100.0
    close_gap = (close - ma5) / ma5 * 100.0
    if low_gap < WUDAO_HUABAO_HUG_LOW_GAP[0] or low_gap > WUDAO_HUABAO_HUG_LOW_GAP[1]:
        return False
    if close_gap < WUDAO_HUABAO_HUG_CLOSE_GAP[0] or close_gap > WUDAO_HUABAO_HUG_CLOSE_GAP[1]:
        return False
    span = max(high - low, 1e-9)
    upper = (high - max(open_, close)) / span
    if upper > WUDAO_HUABAO_HUG_MAX_UPPER and pct < 4.0:
        return False
    return pct <= WUDAO_HUABAO_HUG_MAX_PCT


def _huabao_yang_streak(bars: Bars) -> tuple[int, int]:
    """从最近往回数连阳，返回 `(根数, 连阳段起点下标)`。

    末日若是**小阴缩量**（`pct > -2.2` 且 量比 ≤1.35）仍看前一段连阳 —— 与悟道一致。
    最多回看 `WUDAO_HUABAO_MAX_YANG_LOOK` 根。
    """
    n = len(bars.close)
    if n < 8:
        return 0, 0
    start = n - 1
    if not _huabao_is_yang(bars, start):
        if float(bars.pct_chg[start]) > -2.2 and _wudao_day_volume_ratio(bars, start) <= 1.35:
            start -= 1
        else:
            return 0, 0
    i = start
    while i >= 0 and _huabao_is_yang(bars, i) and (start - i + 1) <= WUDAO_HUABAO_MAX_YANG_LOOK:
        i -= 1
    streak = start - i
    if streak <= 0:
        return 0, 0
    return streak, i + 1


def _huabao_vol_wake(bars: Bars, streak_start: int, streak_end: int) -> bool:
    """量由缩转放：连阳前相对安静，或连阳过程里量比上台阶。"""
    vols = [
        _wudao_day_volume_ratio(bars, i) for i in range(streak_start, streak_end + 1)
    ]
    if not vols:
        return False
    quiet = False
    if streak_start >= 3:
        pre = [
            _wudao_day_volume_ratio(bars, i)
            for i in range(max(0, streak_start - 5), streak_start)
        ]
        if pre and min(pre) <= 0.95 and sum(pre) / len(pre) <= 1.2:
            quiet = True
    rising = (
        vols[-1] >= vols[0] * 1.05
        or max(vols) >= vols[0] * 1.2
        or vols[-1] >= 1.2
        or (len(vols) >= 3 and sum(vols[-2:]) / 2 >= sum(vols[:2]) / 2 * 1.08)
    )
    mild = 0.55 <= vols[-1] <= 4.2
    return mild and (quiet or rising)


def _huabao_macd_ok(bars: Bars) -> bool:
    """MACD 抬头：`expanding and dif_up and macd[-1] / close[-1] > -0.0015`。

    ⚠️ 2026-10-10 口径变更：第三条原为绝对元值 `macd[-1] > -0.05`，MACD 由前复权
    序列算出、随价位等比缩放，绝对阈值使判定与股价水平相关 —— 已改成相对量
    `macd[-1] / close[-1]`（见 `WUDAO_HUABAO_MACD_MIN_RATIO` 那段注释的实跑依据）。
    `expanding` / `dif_up` 两条不变（它们是同一序列内的比较，本来就不受尺度影响）。
    """
    macd, dif = _macd_tail(bars, 3)
    if len(macd) < 2 or len(dif) < 2:
        return False
    expanding = macd[-1] > macd[0] or (macd[-1] > 0 and macd[-1] >= macd[-2])
    dif_up = dif[-1] >= dif[0]
    close = float(bars.close[-1])
    if close <= 0:
        return False
    return expanding and dif_up and macd[-1] / close > WUDAO_HUABAO_MACD_MIN_RATIO


def _huabao_early(bars: Bars) -> Signal | None:
    """华宝早期：连阳 + 贴 5 日线 + 量由缩转放 + MACD 抬头（只观察，不直接买）。

    逐条照抄 `yangban-desk/app/huabao_early.py::score_huabao_early` 的**日线部分**：

    1. `ret_20 ≤ 32`、`ret_5 ≤ 22`（已经主升完的不算早期）；贴 20 日高且 `ret_20 > 25` 也剔
    2. 连阳 ≥3 根（末日小阴缩量可容忍）、连阳日子形态相近（均涨 0.4~6.5%、方差 ≤18、
       贴均天数 ≥60%）
    3. 量：`0.55 ≤ 末日量比 ≤ 4.2`，且（连阳前 5 日缩量 或 连阳里量上台阶）
    4. MACD 抬头

    ⚠️ 它还有两步我们**不做**：`fund_flow.flow_on_dates`（大单/主力净额，我们用 iFinD DDE、
    口径不同）与分钟线贴 VWAP 校验（要现拉分钟线）。它自己也把「取不到资金流」当不淘汰处理，
    所以缺这两步只会让清单稍宽一点，不会引入错票。
    """
    n = len(bars.close)
    if n < WUDAO_HUABAO_MIN_BARS:
        return None
    ret_20 = _ret_pct(bars, n - 1, 20)
    ret_5 = _ret_pct(bars, n - 1, 5)
    if ret_20 > WUDAO_HUABAO_MAX_RET_20 or ret_5 > WUDAO_HUABAO_MAX_RET_5:
        return None
    close = float(bars.close[n - 1])
    high_20 = float(np.max(bars.high[max(0, n - 20) : n]))
    # 贴 20 日高、且已经涨得太晚（`ret_20 > 25`）→ 不算早期。
    # 原来这里还带一个 `ret_20 > 18` 的前置条件，但它被 `ret_20 > 25` 蕴含（冗余），
    # 2026-10-10 删掉那一段（逻辑等价，docstring 一直只写了 `> 25`，现在代码与它一致）。
    if close >= high_20 * 0.97 and ret_20 > WUDAO_HUABAO_LATE_RET_20:
        return None

    streak, start = _huabao_yang_streak(bars)
    if streak < WUDAO_HUABAO_MIN_YANG:
        return None

    pcts = [float(bars.pct_chg[i]) for i in range(start, start + streak)]
    avg = sum(pcts) / len(pcts)
    if avg < WUDAO_HUABAO_YANG_AVG[0] or avg > WUDAO_HUABAO_YANG_AVG[1]:
        return None
    var = sum((p - avg) ** 2 for p in pcts) / len(pcts)
    if var > WUDAO_HUABAO_YANG_MAX_VAR:
        return None
    hug_days = sum(1 for i in range(start, start + streak) if _huabao_hug_ma5(bars, i))
    if hug_days < max(2, int(round(streak * 0.6))):
        return None

    if not _huabao_vol_wake(bars, start, start + streak - 1):
        return None
    if not _huabao_macd_ok(bars):
        return None

    vols = [_wudao_day_volume_ratio(bars, i) for i in range(start, start + streak)]
    ma5 = _safe_mean(bars.close[n - 5 : n])
    macd_last, _ = _macd_tail(bars, 1)
    score = 56.0
    if streak >= 4:
        score += 4.0
    if hug_days >= streak:  # 整段都贴着 5 日线，最像
        score += 6.0
    if vols[-1] >= 1.2:
        score += 4.0
    if ret_20 <= 18:
        score += 4.0
    score = min(score, 78.0)

    return Signal(
        "huabao_early",
        score,
        # 连阳段低点是「跌回去就不像了」的参照，MA5 是贴着爬的那条线
        {
            "streak_low": float(np.min(bars.low[start : start + streak])),
            "ma5": ma5,
        },
        {
            "yang_days": int(streak),
            "hug_days": int(hug_days),
            "vol_from": round(vols[0], 2),
            "vol_to": round(vols[-1], 2),
            "macd": round(macd_last[0], 3) if macd_last else 0.0,
            "ret_20": round(ret_20, 1),
            "ret_5": round(ret_5, 1),
        },
    )


# ------------------------------------------------- 新增形态实现（2026-09-25）

def _linfit(values: np.ndarray) -> tuple[float, float]:
    """最小二乘直线拟合，返回 `(斜率, 截距)`，x 取 0..n-1。

    趋势线一律用拟合，而不是「窗口两端的极值连线」：后者对单根毛刺极度敏感 ——
    一根长上影就能把整条轨拉歪；最小二乘会把毛刺摊到整条线上。
    """
    if values.size < 2:
        return 0.0, 0.0
    slope, intercept = np.polyfit(np.arange(values.size, dtype=float), values, 1)
    return float(slope), float(intercept)


def _touches(values: np.ndarray, level: float, tol: float) -> int:
    """序列里「碰到 level」的次数（相对容差）。

    用来确认箱体上下沿是真被反复验证过，而不是取最大/最小时偶然扫到的一根毛刺。
    """
    if level <= 0:
        return 0
    return int(np.sum(np.abs(values / level - 1.0) <= tol))


def _candle(
    bars: Bars, index: int = -1
) -> tuple[float, float, float, float, float, float, float, float]:
    """一根 K 线的 `(开, 高, 低, 收, 实体, 上影, 下影, 振幅)`。

    振幅可能是 0（一字板），调用方必须自己判 —— 除零会让整只票的扫描抛异常。
    """
    open_, high, low, close = (
        float(bars.open[index]),
        float(bars.high[index]),
        float(bars.low[index]),
        float(bars.close[index]),
    )
    return (
        open_,
        high,
        low,
        close,
        abs(close - open_),
        high - max(open_, close),
        min(open_, close) - low,
        high - low,
    )


def _bullish_engulf_confirm(bars: Bars) -> bool:
    """命中日当天是否同时出现「看涨吞没」（含近 5 日回调 ≥3% 的前置条件）。

    2026-10-18 清单 #3 的回测结论：47 个形态 × 3 种蜡烛里，只有「金叉大阳 × 看涨吞没」
    达到决策线 —— 确认组 10 日超额 +1.99%，基础组 +0.83%，差 **+1.16pp**，样本 215
    （≥200）。所以只在金叉大阳的 `detail` 里加 `candle_confirm`，**不恢复独立蜡烛形态**。

    判定与 `scripts/backtest_patterns.py` 里那份逐字一致（回调门槛 + 吞没形状 +
    收盘落在全日振幅上半部），改一处必须同步改另一处。
    """
    if len(bars) < CANDLE_PRIOR_DAYS + 3:
        return False
    base = float(bars.close[-1 - CANDLE_PRIOR_DAYS])
    if base <= 0:
        return False
    if float(base / bars.close[-2] - 1) < CANDLE_PRIOR_DROP:
        return False

    prev_open, _, _, prev_close, prev_body, _, _, prev_span = _candle(bars, -2)
    open_, _, low, close, body, _, _, span = _candle(bars)
    if prev_close >= prev_open or close <= open_:
        return False
    if prev_body <= 0 or prev_span <= 0 or span <= 0:
        return False
    if not (open_ <= prev_close and close >= prev_open):
        return False
    if body / prev_body < ENGULF_MIN_BODY:
        return False
    return (close - low) / span >= ENGULF_MIN_CLOSE_POS


def _ma_squeeze(bars: Bars) -> Signal | None:
    """均线粘合：MA5/10/20/60 挤在极窄区间里横住 —— 方向未定的蓄势。

    与「均线多头排列」正好互补：那个要四线**已发散且向上**（趋势中段），
    这个要四线**挤在一起且没在拉**（趋势起点），两者很少同时命中。
    """
    if len(bars) < MA_PERIODS[-1] + SQUEEZE_DAYS:
        return None
    series = [_align(_ma_series(bars.close, period), period, len(bars)) for period in MA_PERIODS]
    if any(not np.isfinite(item[-1]) for item in series):
        return None

    worst = 0.0
    for offset in range(SQUEEZE_DAYS):
        point = -1 - offset
        values = [float(item[point]) for item in series]
        lowest = min(values)
        if lowest <= 0:
            return None
        worst = max(worst, max(values) / lowest - 1)
    if worst > SQUEEZE_MAX_SPREAD:
        return None

    ma20 = series[2]
    base = float(ma20[-1 - SQUEEZE_DAYS])
    if base <= 0:
        return None
    slope = float(ma20[-1] / base - 1)
    if slope > SQUEEZE_SLOPE_MAX:
        return None  # 均线已经在拉了，那不是粘合

    score = _gate_score(worst, SQUEEZE_MAX_SPREAD, SQUEEZE_IDEAL_SPREAD) * 70
    # 横得越平越像蓄势；向上拉起来或向下破位都扣分
    score += _gate_score(abs(slope), SQUEEZE_SLOPE_MAX, 0.0) * 30

    return Signal(
        "ma_squeeze",
        score,
        {
            "breakout": float(bars.high[-SQUEEZE_DAYS:].max()),
            "support": float(bars.low[-SQUEEZE_DAYS:].min()),
        },
        {"squeeze_width": round(worst, 4), "days": SQUEEZE_DAYS, "ma20_rise": round(slope, 4)},
    )


def _ma_golden_cross(bars: Bars) -> Signal | None:
    """金叉共振：MA5 最近 3 天内上穿 MA10，同时 MA10 向上、MA20 不走弱。

    「共振」指的是两个时间尺度同时转好：短期均线刚金叉（动能刚切），
    中期均线也没在向下（趋势没坏）。只有金叉、而 MA20 还在下行的那种，
    一半是真突破一半是反抽，所以拿 MA20 的五日斜率当否决条件。
    """
    if len(bars) < MA_PERIODS[-1] + CANDLE_PRIOR_DAYS + 1:
        return None
    ma5 = _align(_ma_series(bars.close, 5), 5, len(bars))
    ma10 = _align(_ma_series(bars.close, 10), 10, len(bars))
    ma20 = _align(_ma_series(bars.close, 20), 20, len(bars))
    if not (np.isfinite(ma5[-1]) and np.isfinite(ma10[-1]) and np.isfinite(ma20[-1])):
        return None
    if ma5[-1] <= ma10[-1]:
        return None

    cross_ago = 0
    for offset in range(1, CROSS_LOOKBACK + 1):
        above = float(ma5[-1 - offset])
        below = float(ma10[-1 - offset])
        if not (np.isfinite(above) and np.isfinite(below)):
            return None
        if above <= below:
            cross_ago = offset
            break
    if cross_ago == 0:
        return None  # 这几天一直压着，不是「刚金叉」

    look = CANDLE_PRIOR_DAYS
    base10, base20 = float(ma10[-1 - look]), float(ma20[-1 - look])
    if base10 <= 0 or base20 <= 0 or not np.isfinite(base10) or not np.isfinite(base20):
        return None
    rise10 = float(ma10[-1] / base10 - 1)
    rise20 = float(ma20[-1] / base20 - 1)
    if rise10 <= CROSS_MIN_MA10_RISE or rise20 < CROSS_MIN_MA20_RISE:
        return None

    ratio = _volume_ratio(bars, 5)
    score = (CROSS_LOOKBACK + 1 - cross_ago) / (CROSS_LOOKBACK + 1) * 40
    score += min(rise10 / 0.03, 1.0) * 30
    score += min(max(rise20, 0.0) / 0.02, 1.0) * 20
    score += min(ratio / 2.0, 1.0) * 10

    return Signal(
        "ma_golden_cross",
        min(score, 100.0),
        {"support": float(ma10[-1])},
        {
            "cross_days_ago": cross_ago,
            "ma10_rise": round(rise10, 4),
            "ma20_rise": round(rise20, 4),
            "vol_ratio": round(ratio, 2),
        },
    )


def _ma_volume(bars: Bars) -> Signal | None:
    """均线放量金叉：MA5 今天上穿 MA20，且当日成交量 ≥ 20 日均量的 1.5 倍。

    2026-10-17 移植自 `sngyai/Sequoia-X` 的 `MaVolumeStrategy`。两条必要条件
    照搬，打分按本站 0~100 口径重写（见文件顶部 `MA_VOLUME_*` 那段的分工说明）。
    """
    if len(bars) < MA_VOLUME_SLOW + 1:
        return None

    ma5 = _align(_ma_series(bars.close, MA_VOLUME_FAST), MA_VOLUME_FAST, len(bars))
    ma20 = _align(_ma_series(bars.close, MA_VOLUME_SLOW), MA_VOLUME_SLOW, len(bars))
    now5, now20 = float(ma5[-1]), float(ma20[-1])
    prev5, prev20 = float(ma5[-2]), float(ma20[-2])
    if not all(np.isfinite(value) for value in (now5, now20, prev5, prev20)):
        return None
    if not (prev5 < prev20 and now5 > now20):
        return None

    # 量比分母**含当日**（原式 `rolling(20).mean()` 的口径），别换成 `_volume_ratio`
    base = _safe_mean(bars.volume[-MA_VOLUME_SLOW:])
    ratio = float(bars.volume[-1] / base) if base > 0 else 0.0
    if ratio < MA_VOLUME_MIN_MULT:
        return None

    gap = now5 / now20 - 1
    score = (
        _band_score(ratio, MA_VOLUME_MIN_MULT, MA_VOLUME_IDEAL_MULT, MA_VOLUME_CAP_MULT)
        * 65
    )
    score += _gate_score(gap, 0.0, MA_VOLUME_GAP_IDEAL) * 35

    return Signal(
        "ma_volume",
        min(score, 100.0),
        {"support": now20},
        {"vol_ratio_20": round(ratio, 2), "cross_gap": round(gap, 4)},
    )


def _downtrend_breakout(bars: Bars) -> Signal | None:
    """下降趋势线突破：用近 60 天的**摆动高点**连出一条下降线，今天收盘站上它。

    为什么只认摆动高点（zigzag）而不是窗口最高价：后者连出来是水平线，
    那就把「下降趋势突破」偷换成了「平台突破」，两者含义完全不同。

    ⚠️ 只用**已确认**的摆动点（2026-10-10 修）：`zigzag` 末尾那个极值是**尚未被反向
    确认**的（假设趋势延续，见其 docstring）。它常常就是今天这根冲高的高点 —— 混进来
    之后最高点看着没在降低（`np.diff >= 0`）或把趋势线的斜率带偏，反弹一突破就被系统性
    漏报。所以这里把 `pivots[-1]` 丢掉，只用前面那些已确认的。
    """
    if len(bars) < TRENDLINE_DAYS:
        return None
    pivots = _recent_pivots(bars, TRENDLINE_DAYS)
    highs = [
        (index, price)
        for index, price, direction in pivots[:-1]  # 丢掉末尾未确认的那个
        if direction > 0
    ]
    if len(highs) < TRENDLINE_MIN_PIVOTS:
        return None

    use = highs[-(TRENDLINE_MIN_PIVOTS + 1) :]
    prices = np.array([price for _, price in use], dtype=float)
    if np.any(np.diff(prices) >= 0):
        return None  # 高点没有逐个降低，那就不叫下降趋势

    slope, intercept = np.polyfit(np.array([index for index, _ in use], dtype=float), prices, 1)
    line_now = float(intercept + slope * (len(bars) - 1))
    if line_now <= 0:
        return None
    close = float(bars.close[-1])
    if close <= line_now:
        return None
    excess = close / line_now - 1
    if excess > TRENDLINE_MAX_EXCESS:
        return None

    ratio = _volume_ratio(bars, 5)
    score = _band_score(excess, 0.002, 0.03, TRENDLINE_MAX_EXCESS) * 45
    score += _band_score(ratio, 1.0, 2.5, 6.0) * 35
    score += min(len(use) / 3.0, 1.0) * 20

    return Signal(
        "downtrend_breakout",
        min(score, 100.0),
        {"breakout": line_now},
        {"excess": round(excess, 4), "vol_ratio": round(ratio, 2), "pivots": len(use)},
    )


def _gap_up_breakout(bars: Bars) -> Signal | None:
    """向上跳空缺口突破：今天最低价高于昨天最高价（区间不重叠的真缺口），
    且当天收阳、收盘同时创 20 日新高。

    「真缺口」用**今低 > 昨高**判，不用「今开 > 昨收」—— 后者会把开盘价恰好
    等于昨收的那种漏掉，而前者只要两天成交区间不重叠就成立。
    """
    if len(bars) < GAP_BREAK_HIGH_DAYS + 2:
        return None
    prev_high = float(bars.high[-2])
    today_low = float(bars.low[-1])
    if prev_high <= 0 or today_low <= prev_high:
        return None
    gap = today_low / prev_high - 1
    if gap < GAP_MIN:
        return None
    if float(bars.close[-1]) <= float(bars.open[-1]):
        return None  # 跳空后收阴 = 冲高回落

    prior = float(bars.close[-GAP_BREAK_HIGH_DAYS - 1 : -1].max())
    close = float(bars.close[-1])
    if close <= prior:
        return None
    excess = close / prior - 1
    ratio = _volume_ratio(bars, 5)

    score = _band_score(gap, *GAP_IDEAL, GAP_CAP) * 35
    score += _band_score(ratio, 1.2, 3.0, 7.0) * 35
    score += _band_score(excess, 0.002, 0.03, 0.09) * 30

    return Signal(
        "gap_up_breakout",
        min(score, 100.0),
        {"breakout": prior, "support": prev_high},
        {"gap": round(gap, 4), "vol_ratio": round(ratio, 2), "excess": round(excess, 4)},
    )


def _gap_fill(bars: Bars) -> Signal | None:
    """缺口回补：近期向上跳空留下的缺口，今天回踩进缺口里、但收在缺口下沿之上。

    为什么回补缺口反而更值得看：向上跳空是当时抢筹留下的空白区，回踩到这里
    不破，说明缺口下沿（跳空前的最高价）真成了支撑 —— 比追在缺口上方安全。
    """
    if len(bars) < GAP_FILL_LOOKBACK + 3:
        return None
    total = len(bars)
    for start in range(total - 2, total - 2 - GAP_FILL_LOOKBACK, -1):
        if start < 1:
            break
        base = float(bars.high[start - 1])  # 缺口下沿
        top = float(bars.low[start])  # 缺口上沿
        if base <= 0 or top <= base * (1 + GAP_MIN):
            continue
        # 缺口之后到昨天为止都没被回补过（最低价没碰到下沿）
        if start + 1 <= total - 2 and bool((bars.low[start + 1 : total - 1] <= base).any()):
            continue
        width = top - base
        if width <= 0:
            continue

        today_low = float(bars.low[-1])
        today_close = float(bars.close[-1])
        fill = (top - today_low) / width  # 扎进缺口的深度（占缺口宽度）
        if fill < GAP_FILL_MIN_FILL or fill > GAP_FILL_MAX_FILL:
            continue
        if today_close < base:
            continue  # 收盘丢了缺口下沿 = 破位，不是回踩

        since_high = float(bars.close[start:total].max())
        rise = since_high / base - 1 if base > 0 else 0.0
        ratio = _volume_ratio(bars, 5)
        score = _band_score(fill, 0.2, 0.6, GAP_FILL_MAX_FILL + 0.05) * 45
        score += _band_score(rise, 0.005, 0.08, 0.25) * 30
        # 回踩要缩量：带量砸回缺口的，支撑多半守不住
        score += _gate_score(ratio, 1.5, 0.5) * 25

        return Signal(
            "gap_fill",
            min(score, 100.0),
            {"support": base, "breakout": top},
            {
                "gap": round(top / base - 1, 4),
                "fill": round(fill, 3),
                "rise": round(rise, 4),
                "vol_ratio": round(ratio, 2),
                "days_ago": total - 1 - start,
            },
        )
    return None


def _box_breakout(bars: Bars) -> Signal | None:
    """箱体突破：60 天的箱体、上下沿各被触碰 ≥2 次，今天放量收在箱体上沿之上。

    与「平台突破」的区别：平台看的是 30 天**窄幅**（≤18%），抓的是「横久了的启动」；
    箱体反过来要求**宽度够大**（≥8%）且上下沿被反复验证（各 ≥2 次触碰）——
    一个宽幅震荡了三个月的箱子被向上突破，与一段窄平台被突破，含义不一样。
    """
    if len(bars) < BOX_DAYS + 2:
        return None
    box = slice(len(bars) - 1 - BOX_DAYS, len(bars) - 1)
    top = float(bars.high[box].max())
    bottom = float(bars.low[box].min())
    if bottom <= 0:
        return None
    width = (top - bottom) / bottom
    if width < BOX_MIN_RANGE or width > BOX_MAX_RANGE:
        return None

    touches_top = _touches(bars.high[box], top, BOX_TOUCH_TOL)
    touches_bottom = _touches(bars.low[box], bottom, BOX_TOUCH_TOL)
    if touches_top < BOX_MIN_TOUCHES or touches_bottom < BOX_MIN_TOUCHES:
        return None

    close = float(bars.close[-1])
    if close <= top:
        return None
    excess = close / top - 1
    if excess > BOX_MAX_EXCESS:
        return None
    ratio = _volume_ratio(bars, 5)
    if ratio < BOX_VOL_MULT:
        return None

    score = min((touches_top + touches_bottom) / 6.0, 1.0) * 25
    score += _band_score(ratio, BOX_VOL_MULT, 3.0, 7.0) * 30
    score += _band_score(excess, 0.002, 0.03, BOX_MAX_EXCESS) * 25
    score += _gate_score(width, BOX_MAX_RANGE, BOX_MIN_RANGE) * 20  # 箱子越紧实越好

    return Signal(
        "box_breakout",
        min(score, 100.0),
        {"breakout": top, "support": bottom},
        {
            "box_range": round(width, 4),
            "touches_top": touches_top,
            "touches_bottom": touches_bottom,
            "vol_ratio": round(ratio, 2),
            "excess": round(excess, 4),
        },
    )


def _volume_dry_bottom(bars: Bars) -> Signal | None:
    """地量见底：成交量缩到 60 日最低，同时价格处在低位（距 60 日最高收盘回撤 ≥20%）。

    「地量」与「低位」必须**同时**成立：只有地量可能是没人交易的僵尸股；
    只有低位可能是放量下跌的中继。
    """
    if len(bars) < DRY_BOTTOM_DAYS + 1:
        return None
    window_vol = bars.volume[-DRY_BOTTOM_DAYS:]
    lowest = float(window_vol.min())
    average = _safe_mean(window_vol)
    if lowest <= 0 or average <= 0:
        return None
    today_vol = float(bars.volume[-1])
    if today_vol > lowest * DRY_BOTTOM_VOL_MAX:
        return None
    shrink = today_vol / average

    peak = float(bars.close[-DRY_BOTTOM_DAYS:].max())
    if peak <= 0:
        return None
    drawdown = 1 - float(bars.close[-1]) / peak
    if drawdown < DRY_BOTTOM_MIN_DRAWDOWN:
        return None
    pct = float(bars.pct_chg[-1])
    if pct < -2.0:
        return None  # 还在放量下跌的不算「见底」

    score = _gate_score(shrink, 0.6, 0.2) * 45
    score += _band_score(drawdown, DRY_BOTTOM_MIN_DRAWDOWN, 0.45, 0.7) * 30
    score += _gate_score(pct, -2.0, 2.0) * 25

    return Signal(
        "volume_dry_bottom",
        min(score, 100.0),
        {"support": float(bars.low[-DRY_BOTTOM_DAYS:].min())},
        {
            "vol_shrink": round(shrink, 3),
            "drawdown": round(drawdown, 4),
            "pct_chg": round(pct, 2),
        },
    )


def _shrink_limit_up(bars: Bars) -> Signal | None:
    """缩量涨停：涨停（沿用 `LS_LIMIT_PCT` 的 9.5% 口径）却明显没量 —— 惜售。

    与「放量上涨」正好相反：那个要量能配合，这个要**没量**。缩量涨停说明
    卖盘极少，次日容易接着封；但也常常是「一字板买不进」，所以给的是
    观察价值，别当成可执行的买点。
    """
    if len(bars) < 6:
        return None
    pct = float(bars.pct_chg[-1])
    if pct < LS_LIMIT_PCT:
        return None
    ratio = _volume_ratio(bars, 5)
    if ratio <= 0 or ratio > SHRINK_LIMIT_VOL_MAX:
        return None
    if float(bars.close[-1]) <= float(bars.open[-1]):
        return None

    score = _gate_score(ratio, SHRINK_LIMIT_VOL_MAX, 0.25) * 60
    score += _gate_score(pct, LS_LIMIT_PCT, 12.0) * 40

    return Signal(
        "shrink_limit_up",
        min(score, 100.0),
        {"support": float(bars.low[-1])},
        {"vol_ratio": round(ratio, 3), "pct_chg": round(pct, 2)},
    )


def _volume_stall(bars: Bars) -> Signal | None:
    """放量滞涨：放量（量比 ≥1.8）但价格没动（-1.5%~+2.5%）、还留了长上影。

    ⚠️ 偏**警示类**：高位放量滞涨多半是派发，低位才可能是吸筹。位置只写进 detail
    与打分，不做否决（理由见阈值块里那段）。位置看 detail 的「距高点回撤」。
    """
    if len(bars) < DRY_BOTTOM_DAYS + 1:
        return None
    ratio = _volume_ratio(bars, 5)
    if ratio < STALL_VOL_MULT:
        return None
    pct = float(bars.pct_chg[-1])
    if not STALL_PCT_BAND[0] <= pct <= STALL_PCT_BAND[1]:
        return None
    _, _, _, close, _, upper, _, span = _candle(bars)
    if span <= 0:
        return None
    shadow = upper / span
    if shadow < STALL_SHADOW_MIN:
        return None
    peak = float(bars.close[-DRY_BOTTOM_DAYS:].max())
    if peak <= 0:
        return None
    drawdown = 1 - close / peak

    score = _band_score(ratio, STALL_VOL_MULT, 4.0, 8.0) * 35
    score += _band_score(shadow, STALL_SHADOW_MIN, 0.6, 0.95) * 30
    # 低位才给这 35 分：高位放量滞涨同样会入库，但分数明显更低、排不到前面
    score += _band_score(drawdown, STALL_MIN_DRAWDOWN, 0.45, 0.7) * 35

    return Signal(
        "volume_stall",
        min(score, 100.0),
        {"support": float(bars.low[-1])},
        {
            "vol_ratio": round(ratio, 2),
            "pct_chg": round(pct, 2),
            "upper_shadow": round(shadow, 3),
            "drawdown": round(drawdown, 4),
        },
    )


def _v_bottom(bars: Bars) -> Signal | None:
    """V 型底：急跌 → 快速收复，左右两段基本对称，现在已从低点反弹到左侧跌幅的 60% 以上。

    「对称」是它和「圆弧底」的分界：V 型的下跌段与上涨段**天数接近**（快跌快涨），
    圆弧底是慢慢磨出来的（幅度小、时间长）。
    """
    if len(bars) < V_BOTTOM_DAYS:
        return None
    pivots = _recent_pivots(bars, V_BOTTOM_DAYS)
    lows = [(index, price) for index, price, direction in pivots if direction < 0]
    if not lows:
        return None
    low_index, low_price = min(lows, key=lambda item: item[1])
    if low_price <= 0:
        return None

    left = [(index, price) for index, price, direction in pivots if direction > 0 and index < low_index]
    if not left:
        return None
    peak_index, peak_price = max(left, key=lambda item: item[1])
    if peak_price <= low_price:
        return None
    drop = 1 - low_price / peak_price
    if drop < V_BOTTOM_MIN_DROP:
        return None

    close = float(bars.close[-1])
    recovered = close / low_price - 1
    if recovered / drop < V_BOTTOM_MIN_REBOUND:
        return None

    down_days = low_index - peak_index
    up_days = len(bars) - 1 - low_index
    if down_days <= 0 or up_days <= 0:
        return None
    symmetry = max(down_days, up_days) / min(down_days, up_days)
    if symmetry > V_BOTTOM_SYMMETRY:
        return None

    left_vol = _safe_mean(bars.volume[peak_index : low_index + 1])
    right_vol = _safe_mean(bars.volume[low_index + 1 :])
    boost = right_vol / left_vol if left_vol > 0 else 0.0

    score = _gate_score(recovered / drop, V_BOTTOM_MIN_REBOUND, 1.0) * 45
    score += _gate_score(symmetry, V_BOTTOM_SYMMETRY, 1.0) * 30
    score += min(boost / 1.5, 1.0) * 25

    return Signal(
        "v_bottom",
        min(score, 100.0),
        {"support": low_price, "breakout": peak_price},
        {
            "drop": round(drop, 4),
            "recover_pct": round(recovered, 4),
            "down_days": down_days,
            "up_days": up_days,
            "vol_boost": round(boost, 2),
        },
    )


def _round_bottom(bars: Bars) -> Signal | None:
    """圆弧底：90 天窗口走出一条平缓的凹形曲线，现在已从底部抬起 60% 以上。

    开口方向用二次拟合判（二次项 >0 = 先跌后升），但**打分不看向量大小** ——
    二次项系数的量纲随价格与索引刻度放大，同一个形状在 10 元股和 100 元股上
    能差两个数量级。真正的判据是「振幅够小 + 最低点在窗口中段 + 现在已经抬起来」。
    """
    if len(bars) < ROUND_MIN_DAYS:
        return None
    days = min(ROUND_DAYS, len(bars))
    window = bars.close[-days:]
    lowest = float(window.min())
    highest = float(window.max())
    if lowest <= 0 or highest <= lowest:
        return None
    amplitude = highest / lowest - 1
    if amplitude > ROUND_MAX_AMPLITUDE:
        return None

    quad = float(np.polyfit(np.arange(days, dtype=float), window, 2)[0])
    if quad <= 0:
        return None  # 开口向下 = 圆弧顶

    close = float(bars.close[-1])
    recover = (close - lowest) / (highest - lowest)
    if recover < ROUND_MIN_RECOVER:
        return None
    low_position = float(np.argmin(window)) / (days - 1) if days > 1 else 0.5

    score = _gate_score(recover, ROUND_MIN_RECOVER, 1.0) * 45
    score += _band_score(amplitude, 0.08, 0.25, ROUND_MAX_AMPLITUDE) * 30
    score += _band_score(low_position, 0.3, 0.7, 1.0) * 25

    return Signal(
        "round_bottom",
        min(score, 100.0),
        {"support": lowest, "breakout": highest},
        {
            "days": days,
            "amplitude": round(amplitude, 4),
            "recover_pct": round(recover, 3),
            "low_position": round(low_position, 3),
        },
    )


def _triple_bottom(bars: Bars) -> Signal | None:
    """三重底：三次探底位置彼此接近，且当前已站上两个反弹高点连成的颈线。

    颈线取两个反弹高点里**较低**的那个（更严格）：取高的那个会让「刚过其中一个
    高点」也算突破，而那时价格其实还在另一个高点之下。
    """
    if len(bars) < TRIPLE_DAYS:
        return None
    pivots = _recent_pivots(bars, TRIPLE_DAYS)
    lows = [(index, price) for index, price, direction in pivots if direction < 0]
    if len(lows) < 3:
        return None
    use = lows[-3:]
    prices = [price for _, price in use]
    lowest = min(prices)
    highest = max(prices)
    if lowest <= 0:
        return None
    spread = highest / lowest - 1
    if spread > TRIPLE_LOW_TOL:
        return None

    between = [
        price
        for index, price, direction in pivots
        if direction > 0 and use[0][0] < index < use[-1][0]
    ]
    if not between:
        return None
    neckline = min(between)
    close = float(bars.close[-1])
    if close <= neckline:
        return None
    excess = close / neckline - 1
    if excess > TRIPLE_MAX_EXCESS:
        return None
    ratio = _volume_ratio(bars, 5)

    score = _gate_score(spread, TRIPLE_LOW_TOL, 0.01) * 35
    score += _band_score(excess, 0.002, 0.03, TRIPLE_MAX_EXCESS) * 35
    score += _band_score(ratio, 1.0, 2.5, 6.0) * 30

    return Signal(
        "triple_bottom",
        min(score, 100.0),
        {"breakout": neckline, "support": lowest},
        {
            "low_spread": round(spread, 4),
            "excess": round(excess, 4),
            "vol_ratio": round(ratio, 2),
        },
    )


def _wedge_shape(bars: Bars) -> tuple[float, float, float, float] | None:
    """楔形几何：返回 `(上轨日斜率, 下轨日斜率, 收敛比例, 末端间距/均价)`，不成立则 None。

    上下轨分别对 high / low 序列做最小二乘（理由见 `_linfit`）。要求两轨**同向**
    且间距明显收敛 —— 一上一下那种是收敛三角形（原「三角收敛」形态已删，
    这里的判定不变：它不是楔形）。
    """
    if len(bars) < WEDGE_MIN_DAYS:
        return None
    days = min(WEDGE_DAYS, len(bars))
    mean_close = float(np.mean(bars.close[-days:]))
    if mean_close <= 0:
        return None
    high_slope, high_intercept = _linfit(bars.high[-days:])
    low_slope, low_intercept = _linfit(bars.low[-days:])
    high_daily = high_slope / mean_close
    low_daily = low_slope / mean_close
    if abs(high_daily) < WEDGE_MIN_SLOPE or abs(low_daily) < WEDGE_MIN_SLOPE:
        return None  # 太平，那是箱体
    if high_daily * low_daily <= 0:
        return None  # 一上一下 = 收敛三角形，不是楔形

    end = days - 1
    gap_start = float(high_intercept - low_intercept)
    gap_end = float(
        high_intercept + high_slope * end - (low_intercept + low_slope * end)
    )
    if gap_start <= 0 or gap_end <= 0 or gap_end >= gap_start:
        return None  # 没有收敛
    converge = (gap_start - gap_end) / gap_start
    if converge < WEDGE_MIN_CONVERGE:
        return None

    # 同向两轨要收敛，必然是「下轨比上轨陡」：上升楔形下轨涨得快，
    # 下降楔形上轨跌得快 —— 两种情况都归到这一个判据上
    if high_daily >= low_daily:
        return None

    # 两条轨都要真被碰到过。光要求「同向 + 收敛」太松：实测那样全市场有 8.6%
    # 的票"在下降楔形里"，清单会长到没法看
    index = np.arange(days, dtype=float)
    upper_series = high_intercept + high_slope * index
    lower_series = low_intercept + low_slope * index
    high_touch = int(np.sum(np.abs(bars.high[-days:] / upper_series - 1.0) <= WEDGE_TOUCH_TOL))
    low_touch = int(np.sum(np.abs(bars.low[-days:] / lower_series - 1.0) <= WEDGE_TOUCH_TOL))
    if high_touch < WEDGE_MIN_TOUCHES or low_touch < WEDGE_MIN_TOUCHES:
        return None

    return high_daily, low_daily, converge, gap_end / mean_close


def _rising_wedge(bars: Bars) -> Signal | None:
    """上升楔形：两轨都向上但逐渐收敛 —— **偏空**形态（涨势在衰竭）。

    ⚠️ 与其它形态不同，它给的是**风险提示**而不是买点：上升楔形向上突破的
    成功率偏低，多数以下破告终。照样收录的理由是「持仓时看到它」比「选票时
    看到它」更重要 —— 分数越高表示形态越成熟（越接近变盘）。
    """
    shape = _wedge_shape(bars)
    if shape is None:
        return None
    high_daily, low_daily, converge, gap_ratio = shape
    if high_daily <= 0 or low_daily <= 0:
        return None

    score = _gate_score(converge, WEDGE_MIN_CONVERGE, 0.75) * 45
    score += min(low_daily / 0.006, 1.0) * 25  # 涨得越陡越危险
    score += _gate_score(gap_ratio, 0.12, 0.02) * 30  # 末端越挤越接近变盘

    return Signal(
        "rising_wedge",
        min(score, 100.0),
        {"support": float(bars.low[-1]), "breakout": float(bars.high[-1])},
        {
            "converge": round(converge, 3),
            "upper_slope": round(high_daily, 5),
            "lower_slope": round(low_daily, 5),
            "gap_ratio": round(gap_ratio, 4),
        },
    )


def _diamond(bars: Bars) -> Signal | None:
    """菱形（钻石形）：先扩张后收敛 —— 前两段振幅放大、后两段收窄。

    判法把窗口四等分比各段振幅，这是「情绪先发散、后回归」的可计算版本。
    菱形多出现在转折处，本身不指示方向，所以打分只看形状成熟度与当前位置。
    """
    if len(bars) < DIAMOND_MIN_DAYS:
        return None
    days = min(DIAMOND_DAYS, len(bars))
    quarter = days // 4
    if quarter < 8:
        return None
    ranges = []
    for part in range(4):
        start = len(bars) - days + part * quarter
        segment = slice(start, start + quarter)
        ranges.append(float(bars.high[segment].max() - bars.low[segment].min()))
    if min(ranges) <= 0:
        return None

    expand = ranges[1] / ranges[0] - 1
    contract = (ranges[2] - ranges[3]) / ranges[2]
    if expand < DIAMOND_MIN_EXPAND or contract < DIAMOND_MIN_CONTRACT:
        return None
    # 中段必须明显比两端宽 —— 只看「前段扩张、后段收敛」的话，一段普通波动
    # 也能凑出来（实测全市场 10.7% 的票"是菱形"）
    if min(ranges[1], ranges[2]) < max(ranges[0], ranges[3]) * DIAMOND_MIDDLE_EDGE:
        return None

    tail = slice(len(bars) - quarter, len(bars))
    top = float(bars.high[tail].max())
    bottom = float(bars.low[tail].min())
    position = (float(bars.close[-1]) - bottom) / (top - bottom) if top > bottom else 0.5

    score = _gate_score(expand, DIAMOND_MIN_EXPAND, 0.6) * 35
    score += _gate_score(contract, DIAMOND_MIN_CONTRACT, 0.7) * 35
    score += _band_score(position, 0.4, 0.95, 1.05) * 30

    return Signal(
        "diamond",
        min(score, 100.0),
        {"breakout": top, "support": bottom},
        {
            "days": days,
            "expand": round(expand, 3),
            "contract": round(contract, 3),
            "position": round(position, 3),
        },
    )


def _three_white_soldiers(bars: Bars) -> Signal | None:
    """红三兵：连续三根阳线、实体扎实、收盘逐日抬高、上影短，三日累计涨幅 ≥3%。

    上影短是它的关键特征（每根都被买到收盘），所以把上影占比也当否决条件 ——
    三根都带长上影的「阳线」其实是三根冲高回落，含义正好相反。
    """
    if len(bars) < 4:
        return None
    closes = [float(bars.close[index]) for index in (-3, -2, -1)]
    if not (closes[0] < closes[1] < closes[2]):
        return None

    bodies: list[float] = []
    for index in (-3, -2, -1):
        open_, _, _, close, body, upper, _, span = _candle(bars, index)
        if span <= 0 or close <= open_:
            return None
        if body < span * SOLDIER_MIN_BODY or upper > span * SOLDIER_MAX_SHADOW:
            return None
        bodies.append(body)

    gain = closes[2] / closes[0] - 1
    if gain < SOLDIER_MIN_GAIN:
        return None
    steady = bodies[2] / bodies[0] if bodies[0] > 0 else 0.0
    ratio_vol = _volume_ratio(bars, 5)

    score = _band_score(gain, SOLDIER_MIN_GAIN, 0.08, 0.2) * 45
    score += min(steady, 1.0) * 25  # 第三根实体不缩水（不缩水=1）
    score += min(ratio_vol / 2.0, 1.0) * 30

    return Signal(
        "three_white_soldiers",
        min(score, 100.0),
        {"support": float(bars.low[-3])},
        {
            "gain": round(gain, 4),
            "steady": round(steady, 2),
            "vol_ratio": round(ratio_vol, 2),
        },
    )


def _kneading_line(bars: Bars) -> Signal | None:
    """揉搓线：**昨天长上影、今天长下影**的两根小实体 K，合起来像一根螺旋桨。

    为什么必须两根一起看：单独一根带长影线的小实体已经有了名字（上影是倒锤子、
    下影是锤子），而「先冲高被打回、再砸下去被接回」这一套连着的动作才是搓揉。

    ⚠️ **顺序不能反**（用户两次点名强调）：先长下影、后长上影是另一回事，所以这里对
    **昨天（-2）** 要求长上影、对**今天（-1）** 要求长下影 —— 不是含糊的「两根各带一条
    长影线」。

    ⚠️ **2026-10-14 按用户新标准重写**：只判「形状 + 顺序」——
    两根主影都 ≥ 振幅 × `KNEAD_LONG_SHADOW`，两根实体都落在
    `[KNEAD_MIN_BODY, CANDLE_BODY_MAX] × 振幅`。原来的三条里：
    「两根收盘价相近」**删掉**（众生药业那一对是 1.2016%，擦边 1.2% 被卡掉，而用户的
    标准里没有这条）；「另一侧影线要短」也不单独判了（主影 ≥0.5 + 实体 ≤0.35 已蕴含
    它 ≤0.15）；「主影 ≥ 实体 × 1.5」改成按振幅算（见常量注释）。

    ⚠️ 与前置趋势无关（与锤子线那类不同）：揉搓线讲的是**换手**，出现在哪一段都成立，
    所以这里不加前置涨跌幅门槛。
    """
    if len(bars) < 2:
        return None
    _, _, _, _, prev_body, prev_upper, _prev_lower, prev_span = _candle(bars, -2)
    _, _, _, _, body, _upper, lower, span = _candle(bars)
    if prev_span <= 0 or span <= 0:
        return None
    # 两根都是「看得见的小实体」（下界防退化、上界是「小」）
    if not prev_span * KNEAD_MIN_BODY <= prev_body <= prev_span * CANDLE_BODY_MAX:
        return None
    if not span * KNEAD_MIN_BODY <= body <= span * CANDLE_BODY_MAX:
        return None
    # 形状 + 顺序：昨天长上影、今天长下影
    if prev_upper < prev_span * KNEAD_LONG_SHADOW or lower < span * KNEAD_LONG_SHADOW:
        return None

    score = _gate_score(prev_upper / prev_span, KNEAD_LONG_SHADOW, 0.75) * 35
    score += _gate_score(lower / span, KNEAD_LONG_SHADOW, 0.75) * 35
    # 实体越小越像「螺旋桨」：均值越接近下界越给分（`_gate_score` 的 ideal < gate ⇒ 越小越好）
    score += (
        _gate_score(
            (prev_body / prev_span + body / span) / 2, CANDLE_BODY_MAX, KNEAD_MIN_BODY
        )
        * 30
    )

    return Signal(
        "kneading_line",
        min(score, 100.0),
        {
            # 搓揉的区间就是这两根的高低点：上破才算拧完向上、下破就是搓失败
            "support": min(float(bars.low[-2]), float(bars.low[-1])),
            "breakout": max(float(bars.high[-2]), float(bars.high[-1])),
        },
        {
            "upper_ratio": round(prev_upper / prev_span, 3),
            "lower_ratio": round(lower / span, 3),
            "body_ratio": round((prev_body / prev_span + body / span) / 2, 3),
        },
    )


def _jade_pillar(bars: Bars) -> Signal | None:
    """玉柱擎天：一根长实体大阳线**顶破前期压制**，且明显放量。

    「玉柱」说的是那根柱子本身 —— 实体要够高（≥ 昨收的 5%）、而且要接近**光头光脚**
    （实体占振幅 ≥ 70%、上影 ≤ 15%）。上影短是关键：冲到高位被打回来就不叫「擎天」了，
    那只是一根冲高回落的长阳。

    「擎天」说的是位置 —— 收盘要**站上前 60 日的最高价**（用最高价而不是收盘价当压制位：
    前期那根上影线扎过的高点就是套牢盘所在，顶穿它才算数）。

    ⚠️ 还要**排除已经涨了一大段之后的那根长阳**：那种是加速赶顶，不是玉柱擎天。
    判据是「突破前 60 日的累计涨幅 ≤ 30%」—— 横盘、下跌、温和上行都放行。

    ⚠️ 与 `_volume_breakout`（放量突破前高）的关系：那个按**收盘**突破、且不看 K 线
    形状，所以「冲高回落的长阳」也能命中；这里多两道形状门槛 + 一道位置门槛，
    是它的严格子集方向上的筛法。两个形态都留着 —— 一个抓「放量突破」这个事实，
    一个抓「玉柱」这个形状。
    """
    if len(bars) < YZ_LOOKBACK + 2:
        return None
    open_, _, _, close, body, upper, _, span = _candle(bars)
    prev_close = float(bars.close[-2])
    base = float(bars.close[-YZ_LOOKBACK - 1])
    if prev_close <= 0 or base <= 0 or span <= 0:
        return None
    if close <= open_:
        return None  # 必须收阳
    if body < prev_close * YZ_MIN_BODY_PCT:
        return None  # 柱子不够高
    if body < span * YZ_MIN_BODY_RATIO:
        return None  # 影线太长，不是光头光脚
    if upper > span * YZ_MAX_UPPER:
        return None  # 冲高回落

    prior_high = float(bars.high[-YZ_LOOKBACK - 1 : -1].max())
    if prior_high <= 0 or close <= prior_high:
        return None  # 没顶破压制

    ratio = _volume_ratio(bars, 5)
    if ratio < YZ_MIN_VOL:
        return None  # 不放量不算

    prior_gain = prev_close / base - 1
    if prior_gain > YZ_MAX_PRIOR_GAIN:
        return None  # 前面已经涨了一大段，这是加速

    pct = body / prev_close
    excess = float(close / prior_high - 1)
    # 柱子越高越好（单边）；上影越短越好；量越足越好；位置越低越干净
    score = _gate_score(pct, YZ_MIN_BODY_PCT, 0.10) * 25
    score += _gate_score(upper / span, YZ_MAX_UPPER, 0.02) * 15
    score += _gate_score(ratio, YZ_MIN_VOL, 4.0) * 25
    # 突破幅度是**双向**的：贴着压制位压线突破力度弱，跳得太远又成了追高
    score += _band_score(excess, 0.005, 0.05, 0.12) * 20
    score += _gate_score(prior_gain, YZ_MAX_PRIOR_GAIN, 0.05) * 15

    return Signal(
        "jade_pillar",
        min(score, 100.0),
        {"breakout": prior_high, "support": float(bars.low[-1])},
        {
            "body_pct": round(pct, 4),
            "upper_ratio": round(upper / span, 3),
            "vol_ratio": round(ratio, 2),
            "excess": round(excess, 4),
            "prior_gain": round(prior_gain, 4),
        },
    )


def _wilder_rsi(close: np.ndarray, period: int = 6) -> np.ndarray:
    """Wilder 平滑 RSI，与通达信 `SMA(X,N,1)` 同口径。

    公式里 `RSI6:=SMA(MAX(C-LC,0),6,1)/SMA(ABS(C-LC),6,1)*100` —— 分母
    `SMA(ABS(涨跌),6,1)` 恒等于 `SMA(涨,6,1) + SMA(跌,6,1)`（SMA 是线性的），
    所以这就是标准 Wilder RSI，递推式 `Y[i] = Y[i-1] + (X[i] - Y[i-1]) / N`。

    首根没有 RSI（公式里 `REF(C,1)` 不存在）；`total == 0`（整段没有波动）也返回
    NaN —— NaN 参与比较恒为 False，等于那一条不通过，比随手给 0 或 100 安全
    （实际上「今日涨幅 ≥4%」已经让分母不可能为 0，这条只是兜底）。
    """
    n = close.size
    out = np.full(n, np.nan)
    if n < period + 1:
        return out
    delta = np.diff(close)
    gain = np.where(delta > 0.0, delta, 0.0)
    loss = np.where(delta < 0.0, -delta, 0.0)
    alpha = 1.0 / period
    up = np.empty(n)
    down = np.empty(n)
    up[0] = down[0] = 0.0
    for i in range(1, n):
        up[i] = up[i - 1] + alpha * (gain[i - 1] - up[i - 1])
        down[i] = down[i - 1] + alpha * (loss[i - 1] - down[i - 1])
    total = up + down
    out[1:] = np.divide(
        100.0 * up[1:], total[1:], out=np.full(n - 1, np.nan), where=total[1:] > 0
    )
    return out


def _ma_cross_big_yang(bars: Bars) -> Signal | None:
    """金叉大阳：MA3 上穿 MA5 的当天，收出一根「低 RSI 的短上影大阳」。

    逐字落自用户给的通达信公式（2026-10-10）：

        买入 := CROSS(MA(C,3),MA(C,5)) AND 涨幅>=4% AND RSI6<60 AND 上影/振幅<=0.2;

    四条要一起看：
    - **金叉**（MA3 上穿 MA5）给「短期动能刚切」这个时点，且必须是**今天**穿上去的
      （`CROSS` 的定义：今天 MA3 > MA5 且昨天 MA3 ≤ MA5），不是「已经在多头排列」；
    - **涨幅 ≥4%** 把「金叉但只是横盘抖动」滤掉 —— 要的是一根真的大阳；
    - **上影 ≤ 振幅 20%** 要求这根大阳是**收上去**的，而不是冲高被打回来的长上影；
    - **RSI6 < 60** 是反向约束：涨了 4% 还没到超买，后面的空间没被透支。

    ⚠️ 公式里的涨幅取 `C/REF(C,1)-1`（真实收益率），这里直接用 `pct_chg`：
    本模块的 `close` 是前复权净值序列，`close[i]/close[i-1]-1` 与 `pct_chg`
    **完全相等**（见 `build_bars`），所以两者同口径。

    ⚠️ 上影比的分母带一个 `1e-4` 的尾巴，是照抄公式 `H-L+0.0001` 的写法
    （防一字板除零）；一字板会因此算出 0、判成「短上影」，与公式一致。

    ⚠️ 这是布尔与形态，没有「更像」的分级空间，所以底分 60（高过 `MIN_SCORE`）
    保证命中全部入库，剩下 40 分按过线幅度分级、只用于排序。

    ⚠️ 2026-10-18 清单 #3：命中日若同时是「看涨吞没」，`detail` 多一个
    `candle_confirm`。这来自 47 形态 × 3 种蜡烛的回测 —— 只有「金叉大阳 × 看涨吞没」
    达到决策线（10 日超额 +1.16pp、样本 215），**不是**把蜡烛形态又注册回来。
    """
    if len(bars) < GCB_MIN_BARS:
        return None
    ma3 = _align(_ma_series(bars.close, 3), 3, len(bars))
    ma5 = _align(_ma_series(bars.close, 5), 5, len(bars))
    if not (
        np.isfinite(ma3[-1])
        and np.isfinite(ma5[-1])
        and np.isfinite(ma3[-2])
        and np.isfinite(ma5[-2])
    ):
        return None
    if not (ma3[-1] > ma5[-1] and ma3[-2] <= ma5[-2]):  # CROSS(MA3, MA5)
        return None

    gain = float(bars.pct_chg[-1]) / 100.0
    if gain < GCB_GAIN_MIN:
        return None

    _, _, _, _, _, upper, _, span = _candle(bars)
    upper_ratio = upper / (span + GCB_SPAN_EPS)
    if upper_ratio > GCB_UPPER_MAX:
        return None

    rsi6 = float(_wilder_rsi(bars.close, 6)[-1])
    if not (rsi6 < GCB_RSI_MAX):  # NaN 也走这里（见 `_wilder_rsi`）
        return None

    score = 60.0
    score += _gate_score(gain, GCB_GAIN_MIN, GCB_GAIN_IDEAL) * 15
    score += _gate_score(upper_ratio, GCB_UPPER_MAX, 0.0) * 10
    score += _gate_score(rsi6, GCB_RSI_MAX, GCB_RSI_IDEAL) * 15

    detail: dict[str, float | int | str] = {
        "gain": round(gain, 4),
        "rsi6": round(rsi6, 1),
        "upper_ratio": round(upper_ratio, 3),
        "ma3": round(float(ma3[-1]), 2),
        "ma5": round(float(ma5[-1]), 2),
    }
    # 2026-10-18 清单 #3：只有这个组合的确认组达到决策线（理由见
    # `_bullish_engulf_confirm` 的 docstring）。其它形态不加这个标签。
    if _bullish_engulf_confirm(bars):
        detail["candle_confirm"] = "看涨吞没"

    return Signal(
        "ma_cross_big_yang",
        min(score, 100.0),
        {"support": float(ma5[-1])},
        detail,
    )


@dataclass(slots=True)
class TBuyState:
    """`t_buy_state` 的逐根中间量，长度与 K 线一致。

    为什么要抽出来：`_t_buy` 只判**最后一根**，而「上涨结构内的 B 点」要问的是
    「**某一段区间里**出现过 B 点没有」—— 不抽的话就得把这套公式抄第二遍。
    """

    gap: np.ndarray  # 距 MA20 的乖离（%）
    buy0: np.ndarray  # 原式的 `买0`
    buy_t: np.ndarray  # 过了冷却的 `买T`
    points: np.ndarray  # **任一一档 B 点**（就是「深B」，三档层层包含）
    star_b: np.ndarray  # 「★B」
    double_b: np.ndarray  # 「双B」
    dip: np.ndarray
    gold2_low: np.ndarray
    gold_only_low: np.ndarray
    base_buy: np.ndarray
    weak: np.ndarray
    overdropped: np.ndarray
    ma20: np.ndarray
    ma5: np.ndarray
    vol_ma20: np.ndarray


def t_buy_state(bars: Bars) -> TBuyState | None:
    """用户「V5 日线做T」主图公式里的 B 点，**逐根**算一遍；根数不足返回 None。

    逐条落自通达信原式（2026-10-10）的**买方向**：

        底背   := SUM(底观察,5)>0 AND C>REF(HHV(H,3),1) AND 乖离<-2
        零下二金:= 金叉 AND 零下 AND COUNT(金叉 AND DIF<0,30)>=2 AND DIF>LLV(DIF,30)*0.85
        双零金 := 金叉 AND 零下 AND NOT(零下二金)
        基买   := (绿缩 OR 红攻) AND 乖离<-3 AND 缩量 AND MA5升
        买0    := IF(超跌, 底背 OR 零下二金,
                     底背 OR 零下二金 OR (双零金 AND NOT(强空)) OR (基买 AND NOT(强空)))
        买T    := 买0 AND REF(BARSLAST(买0),1) > IF(超跌,7,5)
        深B    := 买T AND 阳线
        ★B     := EXIST(MA3金叉MA5,3) AND 买T AND C>=MA5 AND 阳线
        双B    := ★B AND MA3金叉MA5

    三档**层层包含**（双B ⊂ ★B ⊂ 深B），所以一根 K 线只会报最高那一档 ——
    与公式里 `显示深B := 深B AND NOT(★B)` 那套互斥写法是同一个结果。

    几处口径说明：

    - `阳线` 就按原式取 `C>=O`，**不复用** `_huabao_is_yang`（那个还要求涨幅 ≥0）。
    - `BARSLAST` 在「买0 从未出现过」时按冷却已满足处理（见 `_barslast`）。
    - 超跌（乖离<-15）当天只留「底背离 / 零下二金」两条，冷却也从 5 天放宽到 7 天 ——
      这两条原式就是 `IF(超跌,…)` 的两个分支，照抄。
    - `MACD.DIF/DEA/柱` 用 `_ema` 现算，与 `_macd_tail`（悟道口径）同一套数字。
    """
    n = len(bars)
    if n < T_BUY_MIN_BARS:
        return None

    close = bars.close.astype(float)
    open_ = bars.open.astype(float)
    high = bars.high.astype(float)
    low = bars.low.astype(float)
    volume = bars.volume.astype(float)

    ma3 = _align(_ma_series(close, 3), 3, n)
    ma5 = _align(_ma_series(close, 5), 5, n)
    ma20 = _align(_ma_series(close, 20), 20, n)
    if not (np.isfinite(ma3[-1]) and np.isfinite(ma5[-1]) and np.isfinite(ma20[-1])):
        return None

    gap = np.divide(close - ma20, ma20, out=np.full(n, np.nan), where=ma20 > 0) * 100.0
    dif = _ema(close, 12) - _ema(close, 26)
    dea = _ema(dif, 9)
    macd = (dif - dea) * 2.0

    vol_ma20 = _align(_ma_series(volume, 20), 20, n)
    shrink = volume < vol_ma20 * T_BUY_SHRINK

    # ---- 底背离：120 日那两档 + 10 日那两档 + MACD 柱那一档（原式的 `底观察`）----
    close_lo = _rolling(close, T_BUY_DIVERGE_DAYS, "min")
    dif_lo = _rolling(dif, T_BUY_DIVERGE_DAYS, "min")
    vol_hi = _rolling(volume, T_BUY_DIVERGE_DAYS, "max")
    low3_lo = _rolling(low, 3, "min")
    low10_lo = _shift(_rolling(low, 10, "min"), 3)
    dif10_lo = _shift(_rolling(dif, 10, "min"), 3)
    vol10_hi = _shift(_rolling(volume, 10, "max"), 3)
    close10_lo = _rolling(close, 10, "min")
    macd10_lo = _rolling(macd, 10, "min")

    near_low = close <= close_lo * (1 + T_BUY_NEAR_TOL)
    near_low_short = low3_lo <= low10_lo * (1 + T_BUY_SHORT_TOL)
    bottom_obs = (
        (near_low & (dif > dif_lo * T_BUY_DIF_RATIO))
        | (near_low & (volume < vol_hi * T_BUY_VOL_RATIO))
        | (near_low_short & (dif > dif10_lo))
        | (near_low_short & (volume < vol10_hi * T_BUY_VOL_RATIO))
        | (
            (close <= close10_lo * (1 + T_BUY_SHORT_TOL))
            & (macd > macd10_lo * T_BUY_HIST_RATIO)
        )
    )
    dip = (
        (_rolling(bottom_obs.astype(float), T_BUY_OBSERVE_DAYS, "sum") > 0)
        & (close > _shift(_rolling(high, 3, "max"), 1))
        & (gap < T_BUY_GAP_DIP)
    )

    # ---- 金叉体系 ----
    gold = _cross(dif, dea)
    below = (dif < 0) & (dea < 0)
    gold2_low = (
        gold
        & below
        & (
            _rolling((gold & (dif < 0)).astype(float), T_BUY_MACD_DAYS, "sum")
            >= T_BUY_MACD_REPEAT
        )
        & (dif > _rolling(dif, T_BUY_MACD_DAYS, "min") * T_BUY_DIF_RATIO)
    )
    gold_only_low = gold & below & ~gold2_low

    # ---- 基买：MACD 柱转向 + 乖离更深 + 缩量 + MA5 抬头 ----
    macd_wake = ((macd < 0) & (macd > _shift(macd, 1))) | (
        (macd > 0) & (macd > _shift(macd, 1)) & (dif > _shift(dif, 1))
    )
    base_buy = macd_wake & (gap < T_BUY_GAP_BASE) & shrink & (ma5 > _shift(ma5, 3))

    pct = bars.pct_chg.astype(float)
    weak = pct < -T_BUY_STRONG
    overdropped = gap < T_BUY_OVERDROP

    core = dip | gold2_low
    extra = (gold_only_low & ~weak) | (base_buy & ~weak)
    buy0 = np.where(overdropped, core, core | extra)
    cooldown = np.where(overdropped, T_BUY_COOLDOWN_DEEP, T_BUY_COOLDOWN)

    buy_t = buy0 & (_shift(_barslast(buy0), 1) > cooldown)

    # ---- 三档 B 点：层层包含（双B ⊂ ★B ⊂ 深B），所以「有没有 B 点」= `points` ----
    points = buy_t & (close >= open_)  # 深B（原式 `深B:=买T AND 阳线`）
    fresh_cross = _cross(ma3, ma5)
    star_b = (
        points
        & (_rolling(fresh_cross.astype(float), T_BUY_CROSS_DAYS, "sum") > 0)
        & (close >= ma5)
    )
    double_b = star_b & fresh_cross

    return TBuyState(
        gap=gap,
        buy0=buy0,
        buy_t=buy_t,
        points=points,
        star_b=star_b,
        double_b=double_b,
        dip=dip,
        gold2_low=gold2_low,
        gold_only_low=gold_only_low,
        base_buy=base_buy,
        weak=weak,
        overdropped=overdropped,
        ma20=ma20,
        ma5=ma5,
        vol_ma20=vol_ma20,
    )


def _t_buy(bars: Bars) -> Signal | None:
    """做T买点：只判**最后一根**，报 深B / ★B / 双B 三档。

    公式本身在 `t_buy_state`（那份 docstring 有逐条口径说明），这里只做判定与打分。

    ⚠️ 门槛用 `points` 而不是 `buy_t`：`points` 就是「深B」，已经含了原式里的
    `阳线`（`深B:=买T AND 阳线`）—— 只看 `buy_t` 的话收阴那天也会报出档位。
    """
    state = t_buy_state(bars)
    if state is None or not state.points[-1]:
        return None

    volume = bars.volume.astype(float)
    tier = "双B" if state.double_b[-1] else ("★B" if state.star_b[-1] else "深B")

    score = T_BUY_BASE_SCORE + T_BUY_TIER_SCORE[tier]
    score += (
        _gate_score(float(state.gap[-1]), T_BUY_GAP_DIP, T_BUY_GAP_IDEAL) * T_BUY_GAP_SCORE
    )

    # 「为什么算」要跟 `买0` 的分支一致：超跌那天原式是
    # `买0 := IF(超跌, 底背 OR 零下二金, …)` —— **双零金与基买被整段排除**，
    # 所以明细里也不能把它们列成原因（2026-10-11 审 `_t_buy` 时修）。
    deep = bool(state.overdropped[-1])
    fired = [
        label
        for flag, label in (
            (state.dip[-1], "底背离"),
            (state.gold2_low[-1], "零下二金"),
            (state.gold_only_low[-1] and not state.weak[-1] and not deep, "双零金"),
            (state.base_buy[-1] and not state.weak[-1] and not deep, "基买"),
        )
        if flag
    ]
    ratio = float(volume[-1] / state.vol_ma20[-1]) if state.vol_ma20[-1] > 0 else 0.0

    return Signal(
        "t_buy",
        min(score, 100.0),
        {"support": float(state.ma20[-1])},
        {
            "tier": tier,
            "trigger": " + ".join(fired) if fired else "—",
            "ma20_gap": round(float(state.gap[-1]), 2),
            "vol_ratio_20": round(ratio, 2),
        },
    )


# ---------------------------------------------------------------- 知行超级B1

# 「知行超级B1 V1203（ZGNB）」（2026-10-13 用户给的同花顺公式；副图 / 主图叠加 /
# 条件选股三份同逻辑）。原式的 `选股` 是 7 个子信号取或：
#
#   选股 := 超卖缩量拐头B OR 超卖缩量B OR 原始B1 OR 超卖超缩量B
#           OR 回踩白线B OR 回踩超级B OR 回踩黄线B;
#
# 这里把 7 个子信号**各落成一个形态**（而不是合成一个「知行B1」）：它们在图上是
# 七种不同的买点、分色画七种标签，合成一个就再也分不出是哪一种。
#
# **7 个现在都是「当天」口径**（2026-10-15 用户要求，整组改回原式那种「今天这根成立」）。
#
# ⚠️ 这条换过三轮，别只看这一版就下结论：
#   原式 = 当天 → 2026-10-13 整组换成「近 N 个交易日出现过」（理由：原式这几个信号全市场
#   只有几到几十只，盘后只看当天太窄，而「一周里出过的那几只」才是「最近刚出现、还在
#   消化」的票）→ 2026-10-15 又整组改回当天（用户看了名单之后要求）。
#   窗口由各 `Pattern` 的 `window` 决定，现在都是 1；判定只有一份（`_zgb1_signal`），
#   不会两处口径漂移。
#
# 与原文的差异（就近在代码里也注明）：
# 1. 「宽幅板」要判**代码前缀**（原式 `STRFIND(CODE,'30',1)=1` 那一串）。`Bars` 原来
#    不带代码，2026-10-13 加了 `code` 字段；扫描与回测都会传，个股页取 K 线不传
#    （那里不跑形态）。
# 2. `SMA(X,N,M)`（KDJ 的 K/D）与 3 日 RSI 就地复算 —— 同花顺版已经把跨指标引用
#    去掉了，这里用 `_sma` / `_wilder_rsi(close, 3)` 对齐口径。
# 3. `BARSLAST(CROSS(C,大哥黄线))>12`：从未上穿过按「已满足」处理（`_barslast` 给 inf）。
#
# 回测（`python scripts/backtest_patterns.py --pattern zgnb_xxx`，2026-10-13，
# 4846 只 · 260 个交易日（2025-09-08 ~ 2026-10-09）· 剔 ST 127 只；超额 = 该档收益
# 减去同日全市场均值）：
#
# ⚠️ **下表是 2026-10-13 那版「近 5 日 / 近 10 日」窗口口径的数字，已不代表生产** ——
# 2026-10-15 整组改回「当天」之后信号数少约 1/4（prod 口径实测 **3305 → 2412**；
# 10-13 那次全市场口径是 3863 → 2907）。⚠️ 别把「1/4」套到 live 库上 —— 那边掉得多得多：
# 窗口口径同一个信号连挂 5 天，那 7 个形态 35 个交易日是 **23372 行 → 6173 行**（−74%）。
# 表原样留着是为了跟当天版对照；要新口径的完整数字就重跑（`--board all` 才是这里
# 4846 只的那个口径，`--board prod` 是页面全量表的口径，两者别混）。
#
# | 信号 | 条数 | 5 日 | 10 日 | 20 日 | 60 日 | 胜率(5/10/20/60) |
# | --- | --- | --- | --- | --- | --- | --- |
# | 缩量拐头B1 `zgnb_turn` | 405 | +0.11 | +1.31 | +2.65 | −4.21 | 33/32/35/21 |
# | 缩量B1 `zgnb_shrink` | 1062 | +0.53 | −0.09 | +0.64 | −5.72 | 34/31/33/20 |
# | 原始B1 `zgnb_origin` | 1243 | −0.11 | −2.33 | −3.03 | −8.34 | 33/28/29/17 |
# | 超级缩量B1 `zgnb_super_shrink` | 215 | +0.49 | +1.37 | +3.09 | −4.66 | 33/36/37/22 |
# | 回踩白线B1 `zgnb_pull_white` | 173 | +0.13 | −1.82 | −3.13 | −7.82 | 34/33/31/20 |
# | 超牛股回踩白线B1（窗口 10 日） `zgnb_pull_super` | 58 | −0.68 | −0.44 | +7.77 | −2.33 | 31/31/45/19 |
# | 回踩黄线B1 `zgnb_pull_yellow` | 707 | −0.15 | −2.23 | −2.86 | −6.30 | 35/29/26/20 |
#
# （上表那一版的窗口：除「超牛股回踩白线B1」是 10 个交易日外，其余都是 5 个。）
#
# （**当天口径**的条数是 255/819/939/175/131/27/561 —— 窗口版约 1.5~2 倍，符合预期；
#  60 日超额仍无一为正。这一组数字是 2026-10-13 逐根改造时复核过的，**现在的口径就是
#  它**：`ZGNB_RECENT_DAYS` / `ZGNB_RARE_RECENT_DAYS` 都已改回 1。）
#
# （形态名自 2026-10-15 起**不再带「·近N日」后缀** —— 那个后缀会跟形态页的「窗口」
#  选择器撞词；窗口口径由形态页的口径说明交代。同日下午的又一次改动见 `ZGNB_RECENT_DAYS`。）
#
# ⚠️ **七条的中位数全负、胜率多在 30~40%，60 日超额没有一条为正**；样本区间
# （2025-09 ~ 2026-10）整体是下跌/震荡市（基准 5/20/60 日约 −1.7%/−4.3%/−4.8%），
# 抄底型信号在这种行情里天生吃亏 —— 定位与「做T买点 / 地量见底」同档：
# **一份左侧观察清单，不是买点信号**。10/20 日超额为正的三条（缩量拐头B1 /
# 缩量B1 / 超级缩量B1）是右尾驱动（20 日最好一单 +88%~+176%），别当胜率读。
# 原式是用户点名要的，先按它落库；要收紧的话最该动的是「要求离区间低点更远」，
# 或给 `move_ok` 补一条「大盘不在急跌段」。
ZGNB_MIN_BARS = 170  # MA144 预热 + EVERY(…,20) + EVERY(…,13)
#: **2026-10-15 起整组改回「当天」口径**（用户要求；同日下午先只改了名字，晚上要求连窗口
#: 一起改）。这个常量换过三轮：原式本来画的就是「当天出的信号」→ 2026-10-13 整组换成
#: 「近 N 个交易日出现过」→ 2026-10-15 又换回当天。
#:
#: 现在 `window = 1`：**只有当天这一根成立才算命中**，报的就是今天这根。`ago` 明细因此
#: 恒为 0 —— 字段**留着**，因为 `pattern_track._picks` 还在按 `ago = 0` 过滤（那里会变成
#: 空操作，但留着才能让「哪天再放宽窗口」时不用两处一起改）。
ZGNB_RECENT_DAYS = 1
#: 「超牛股回踩白线B1」曾经单独放宽到 10 个交易日：它比其余几个稀约 10 倍（全市场约
#: 0.1 条/天），5 日窗口常常一只都没有（10-09 当天 0 条）。2026-10-15 整组改回当天时
#: 一并收回成 1。**留这个常量是留个挂点** —— 哪天想给稀有档单独放宽，改这里 +
#: `_zgnb_pull_super` 的入参即可，不用再翻历史。
ZGNB_RARE_RECENT_DAYS = 1
#: 「宽幅板」（20cm）的代码前缀，对应原式那几个 `STRFIND(CODE,'xx',1)=1`：
#: 30 创业板 / 68 科创板 / 4 与 8 北交所 / 9 沪 B。
ZGNB_WIDE_PREFIXES = ("30", "68", "4", "8", "9")
#: 另一条宽幅判据 `EXIST(C/REF(C,1)>1.15,200)`：近 200 日有过 >15% 的单日涨幅。
#: 本模块的 `pct_chg` 就是真实收益率（百分数），所以直接比 15.0。
ZGNB_WIDE_DAYS = 200
ZGNB_WIDE_PCT = 15.0
ZGNB_RANGE_WIDE = 8.0  # 振幅区间（宽幅板）
ZGNB_RANGE_NARROW = 5.0  # 振幅区间（非宽幅板）
ZGNB_FACTOR_WIDE = 0.9  # 放宽系数（宽幅板）
ZGNB_FACTOR_NARROW = 1.0
#: 7 个子信号都是**布尔与**，命中即入库；底分 60（> `MIN_SCORE`），余下 40 分只用于
#: 排序 —— 不给梯度的话每个命中都是同一个分数，清单没法看（做法同金叉大阳 / 做T买点）。
ZGNB_BASE_SCORE = 60.0
#: 「回踩白线」那两档的支撑就是白线；其余五档都要求站稳黄线（`C>=大哥黄线`），支撑取黄线。
ZGNB_WHITE_SUPPORT_KEYS = ("zgnb_pull_white", "zgnb_pull_super")
#: 明细字段：`(键, 小数位, 缩放)`。缩放 0.01 的是「百分数 ÷ 100 存成比率」那一类 ——
#: 前端 `DETAIL_FIELDS` 的 `isRatio` 会再乘回 100 显示成百分号（两处要对齐）。
_ZGNB_DETAIL_FIELDS = (
    ("rsi3", 1, 1.0),
    ("kdj_j", 1, 1.0),
    ("amp20", 4, 0.01),
    ("amp50", 4, 0.01),
    ("vol_shrink", 3, 1.0),
    ("dist_white", 4, 0.01),
    ("dist_yellow", 4, 0.01),
    ("dist_bbi", 4, 0.01),
    ("day_amp", 4, 0.01),
)


def _zgb1_gate(values: np.ndarray, gate: float, ideal: float) -> np.ndarray:
    """`_gate_score` 的**数组版**（逐元素同一条分段线性映射；NaN 原样传出）。

    三个分支写成 clip：`ideal < gate` 是「越小越好」→ `clip((gate-v)/(gate-ideal))`，
    反之「越大越好」→ `clip((v-gate)/(ideal-gate))`。
    """
    if gate == ideal:
        return np.ones_like(values, dtype=float)
    if ideal < gate:
        return np.clip((gate - values) / (gate - ideal), 0.0, 1.0)
    return np.clip((values - gate) / (ideal - gate), 0.0, 1.0)


_ZGB1_MEMO: tuple[Bars, dict] | None = None


def _zgb1_common(bars: Bars) -> dict:
    """「知行超级B1」的公共前置量 + 这一组形态的判定与排序加成（**逐根**，都是数组）。

    `evaluate` 会挨个调用这一组的每个 detect：每个都从零算一遍趋势白线 / 大哥黄线 /
    KDJ / 3 日 RSI 的话，同一条序列要重算 7 遍 —— 这几条都是 Python 级递推（`_ema`
    与 `_sma` 各几百次循环），全市场扫描会明显变慢。所以这里做**单条缓存**：只记住
    「上一次算过的那只票」，用 `is` 比较（同时持有强引用，不存在 id 被复用的问题）。

    返回 `{"enough", "fired", "extra", "fields", "white", "yellow"}`：`fired` 是
    `键 → 逐根布尔数组`（在册形态只看 `[-1]`，窗口形态看最近 N 根），`extra` 是逐根的
    排序加成，`fields` 是逐根的明细读数（好让窗口形态取「信号那根」而不是「今天」）。
    """
    global _ZGB1_MEMO
    if _ZGB1_MEMO is not None and _ZGB1_MEMO[0] is bars:
        return _ZGB1_MEMO[1]
    computed = _compute_zgb1(bars)
    _ZGB1_MEMO = (bars, computed)
    return computed


def _compute_zgb1(bars: Bars) -> dict:
    """逐条落自同花顺原式的判定，**铺成整条序列的逐根数组**。

    7 个形态都是窗口口径（`_zgb1_signal` 看最近 N 根里有没有成立），所以判定必须
    逐根算 —— 顺带让「一份前置只算一次」更划算：知行B1 那一组共用这一份数组。
    """
    n = len(bars)
    empty = {
        "enough": False,
        "fired": {},
        "extra": {},
        "fields": {},
        "white": np.zeros(0),
        "yellow": np.zeros(0),
    }
    if n < ZGNB_MIN_BARS:
        return empty

    close = bars.close.astype(float)
    open_ = bars.open.astype(float)
    high = bars.high.astype(float)
    low = bars.low.astype(float)
    volume = bars.volume.astype(float)
    prev_close = _shift(close, 1)  # REF(C,1)
    prev_vol = _shift(volume, 1)  # REF(V,1)

    # ---- 三条线：趋势白线（牵牛绳）/ 大哥黄线（多空线）/ BBI ----
    white = _ema(_ema(close, 10), 10)
    yellow = (
        _align(_ma_series(close, 14), 14, n)
        + _align(_ma_series(close, 28), 28, n)
        + _align(_ma_series(close, 57), 57, n)
        + _align(_ma_series(close, 144), 144, n)
    ) / 4.0
    bbi = (
        _align(_ma_series(close, 3), 3, n)
        + _align(_ma_series(close, 6), 6, n)
        + _align(_ma_series(close, 12), 12, n)
        + _align(_ma_series(close, 24), 24, n)
    ) / 4.0
    ma60 = _align(_ma_series(close, 60), 60, n)
    if not (np.isfinite(yellow[-1]) and np.isfinite(ma60[-1])):
        return empty

    # ---- 短期 / 长期（原式是「LLV 取最低价、HHV 取收盘价」的混搭，照抄）----
    llv_l14 = _rolling(low, 14, "min")
    llv_l28 = _rolling(low, 28, "min")
    span14 = _rolling(close, 14, "max") - llv_l14
    span28 = _rolling(close, 28, "max") - llv_l28
    # 分母为 0（连续一字板让窗口内高低点重合）时给 NaN，与 `_ma_series` 的口径一致：
    # 算不出来就是算不出来，不假装有一个数
    short_term = np.divide(
        100.0 * (close - llv_l14), span14, out=np.full(n, np.nan), where=span14 > 0
    )
    long_term = np.divide(
        100.0 * (close - llv_l28), span28, out=np.full(n, np.nan), where=span28 > 0
    )

    # ---- 洗盘异动的三个构件（单针下20 / 聚宝盆 / 双叉戟）与红肥绿瘦 ----
    needle = ((short_term <= 20.0) & (long_term >= 75.0)) | ((long_term - short_term) >= 70.0)
    jewel = (
        (_count(long_term >= 75.0, 8) >= 6)
        & (_count(short_term <= 70.0, 7) >= 4)
        & (_count(short_term <= 50.0, 8) >= 1)
    )
    trident = (
        _every(long_term >= 75.0, 8)
        & (_count(short_term <= 50.0, 6) >= 2)
        & (_count(short_term <= 20.0, 7) >= 1)
    )
    fat_thin = (_count(close >= open_, 15) > 7) | (_count(close > prev_close, 11) > 5)
    wash = (_count(needle, 10) >= 2) | jewel | trident

    # ---- KDJ 与 3 日 RSI（就地复算）----
    llv_l9 = _rolling(low, 9, "min")
    span9 = _rolling(high, 9, "max") - llv_l9
    rsv = np.divide(100.0 * (close - llv_l9), span9, out=np.full(n, np.nan), where=span9 > 0)
    k = _sma(rsv, 3, 1)
    d = _sma(k, 3, 1)
    j = 3.0 * k - 2.0 * d
    # 原式 `SMA(MAX(C-LC,0),3,1)/SMA(ABS(C-LC),3,1)*100` 就是 3 日 Wilder RSI
    rsi = _wilder_rsi(close, 3)

    # ---- 量能四档 ----
    hhv20 = _rolling(volume, 20, "max")
    hhv30 = _rolling(volume, 30, "max")
    hhv50 = _rolling(volume, 50, "max")
    shrink = (volume < hhv20 * 0.416) | (volume < hhv50 / 3.0)
    pull_shrink = (volume < hhv20 * 0.45) | (volume < hhv50 / 3.0)
    proper_shrink = (volume < hhv20 * 0.618) | (volume < hhv50 / 3.0)
    super_shrink = (volume < hhv30 / 4.0) | (volume < hhv50 / 6.0)

    # ---- 振幅与异动（N=20 / M=50）----
    hi12 = _rolling(high, 12, "max")
    hi20 = _rolling(high, 20, "max")
    hi50 = _rolling(high, 50, "max")
    lo20 = _rolling(low, 20, "min")
    lo50 = _rolling(low, 50, "min")
    recent_amp = (hi20 - lo20) / lo20 * 100.0
    near_move = (hi12 - llv_l14) / llv_l14 * 100.0
    recent_move = (recent_amp >= 15.0) | (near_move >= 11.0)
    far_amp = (hi50 - lo50) / lo50 * 100.0
    far_move = far_amp >= 30.0
    super_move = recent_amp >= 60.0
    move_ok = recent_move | far_move | wash

    # ---- 宽幅板 ----
    wide = bars.code.startswith(ZGNB_WIDE_PREFIXES) or bool(
        np.any(bars.pct_chg[-ZGNB_WIDE_DAYS:] > ZGNB_WIDE_PCT)
    )
    span_cap = ZGNB_RANGE_WIDE if wide else ZGNB_RANGE_NARROW
    factor = ZGNB_FACTOR_WIDE if wide else ZGNB_FACTOR_NARROW

    # ---- 当日量价（逐根）----
    # ⚠️ 比率的**运算顺序照抄原式**（`ABS(C-REF(C,1))/REF(C,1)*100` 是先除后乘），
    # 别顺手改写成 `(差*100)/分母` —— 浮点上两者差 1 个 ULP，而这一条判的是
    # 「< 2.5」这种边界；实测改顺序后 `zgnb_shrink` 的回测信号从 819 变成 820。
    day_amp = np.divide(high - low, low, out=np.full(n, np.nan), where=low > 0) * 100.0
    day_chg = (
        np.divide(np.abs(close - prev_close), prev_close, out=np.full(n, np.nan), where=prev_close > 0)
        * 100.0
        * factor
    )
    body_scaled = (
        np.divide(np.abs(close - open_), open_, out=np.full(n, np.nan), where=open_ > 0)
        * 100.0
        * factor
    )
    doji = (close > prev_close) & (body_scaled < 1.8)
    body_pct = np.divide(
        np.abs(close - open_) * 100.0, open_, out=np.full(n, np.nan), where=open_ > 0
    )

    # ---- 大绿棒：量峰那根是不是「大绿棒」，或那根已经离得够远 ----
    # ⚠️ `VDAY` 是**逐根**的（每根各自看它前面 40 根的量峰），所以 `REF(C,VDAY)` 得用
    # 花式下标去取 —— 原来只算最后一根是够用的（判定只看最后一根），现在要看窗口
    # 就必须铺开。`peak` = 量峰那根的下标；`vday < 下标` 保证 `peak-1 ≥ 0`。
    vday = _hhvbars(volume, 40)
    peak = np.zeros(n, dtype=int)
    known = np.isfinite(vday) & (vday < np.arange(n))
    peak[known] = (np.arange(n)[known] - vday[known]).astype(int)
    not_big_green = np.ones(n, dtype=bool)  # 数据不足的前段一律放行（那几根不在任何窗口里）
    not_big_green[known] = (close[peak[known]] >= close[peak[known] - 1]) | (
        close[peak[known]] >= open_[peak[known]]
    )
    # `不是大绿棒 OR 大绿棒离得远`：后者要求「是大绿棒」，也就是前者的否定，
    # 所以整条等价于「不是大绿棒 或 量峰在 15 根以前」
    green_ok = not_big_green | (vday >= 15)

    # ---- 趋势、超牛股与回踩距离（逐根）----
    white_up = white >= _shift(white, 1)
    yellow_notdown = yellow >= _shift(yellow, 1) * 0.999
    up_trend = (white >= yellow) & ((close >= yellow) | ((close > yellow * 0.975) & (close > open_)))
    strong_trend = (
        _every(yellow_notdown, 13)
        & white_up
        & _every(white > yellow, 20)
        & _every(white_up, 11)
        & fat_thin
    )
    super_bull = (
        (_every(bbi >= _shift(bbi, 1) * 0.999, 20) | (_count(bbi >= _shift(bbi, 1), 25) >= 23))
        & ((recent_amp >= 30.0) | (far_amp > 80.0))
        & (_barslast(_cross(close, yellow)) > 12.0)
    )

    white_d = np.divide(np.abs(close - white), close, out=np.full(n, np.nan), where=close > 0) * 100.0
    white_ld = np.divide(np.abs(low - white), white, out=np.full(n, np.nan), where=white > 0) * 100.0
    bbi_d = np.divide(np.abs(close - bbi), close, out=np.full(n, np.nan), where=close > 0) * 100.0
    bbi_ld = np.divide(np.abs(low - bbi), bbi, out=np.full(n, np.nan), where=bbi > 0) * 100.0
    yellow_d = (
        np.divide(np.abs(close - yellow), yellow, out=np.full(n, np.nan), where=yellow > 0) * 100.0
    )

    pull_white = (
        ((close >= white) & (white_d <= 2.0))
        | ((close < white) & (white_d < 0.8))
        | (
            (close >= bbi)
            & (bbi_d < 2.5)
            & (bbi_ld < 1.0)
            & (white_d <= 3.0)
            & (day_chg < 1.0)
            & (close > prev_close)
        )
    )
    white_support = (close >= white) & (white_d < 1.5)
    strong_pull = ((white_ld < 1.0) | (bbi_ld < 0.5)) & (close > white) & (white_d <= 3.5)
    pull_yellow = (
        ((close >= yellow) & ((yellow_d <= 1.5) | ((yellow_d <= 2.0) & (day_chg < 1.0))))
        | ((close < yellow) & (yellow_d <= 0.8))
    )

    # ---- 超卖读数（逐根）----
    rsi_prev = _shift(rsi, 1)  # REF(RSI,1)
    j_prev = _shift(j, 1)  # REF(J,1)
    yellow_prev = _shift(yellow, 1)
    ma60_prev = _shift(ma60, 1)
    rs = rsi + j
    llv_j20 = _rolling(j, 20, "min")
    llv_r14 = _rolling(rsi, 14, "min")
    llv_rs15 = _rolling(rs, 15, "min")
    llv_rs25 = _rolling(rs, 25, "min")
    llv_v20 = _rolling(volume, 20, "min")

    fired = {
        # 超卖缩量拐头B：RSI 当天回升 ≥15 点，且前一日还在超卖区
        "zgnb_turn": (
            up_trend
            & ((rsi - 15.0) >= rsi_prev)
            & ((rsi_prev < 20.0) | (j_prev < 14.0))
            & (day_amp < span_cap + 0.5)
            & ((day_chg < 2.3) | (doji & (day_chg < 4.0)))
            & green_ok
            & move_ok
            & (close >= yellow)
        ),
        # 超卖缩量B
        "zgnb_shrink": (
            up_trend
            & ((j < 14.0) | (rsi < 23.0))
            & ((rs < 55.0) | (j <= llv_j20))
            & (day_amp < span_cap)
            & ((day_chg < 2.5) | doji)
            & green_ok
            & (shrink | (proper_shrink & (day_chg < 1.0)))
            & move_ok
        ),
        # 原始B1
        "zgnb_origin": (
            (white > yellow)
            & (close >= yellow * 0.99)
            & (yellow >= yellow_prev)
            & ((j < 13.0) | (rsi < 21.0))
            & (rs < llv_rs15 * 1.5)
            & proper_shrink
            & green_ok
            & (
                (body_pct < 1.5)
                | super_shrink
                | (proper_shrink & (volume < llv_v20 * 1.1) & (j <= llv_j20))
                | (proper_shrink & ((white_d < 1.8) | (bbi_d < 1.5) | (yellow_d < 2.8)))
            )
            & move_ok
        ),
        # 超卖超缩量B
        "zgnb_super_shrink": (
            up_trend
            & ((j < 14.0) | (rsi < 23.0))
            & (rs < 60.0)
            & (far_amp >= 45.0)
            & (
                (day_amp < span_cap)
                | (super_move & (day_amp < span_cap + 3.2) & (close > open_) & (close > white))
            )
            & (((close < open_) & (volume < prev_vol) & (close >= yellow)) | (close >= open_))
            & ((day_chg < 2.0) | doji)
            & green_ok
            & super_shrink
            & move_ok
        ),
        # 回踩白线B
        "zgnb_pull_white": (
            strong_trend
            & ((j < 30.0) | (rsi < 40.0) | wash)
            & (rs < 70.0)
            & ((day_amp < span_cap + 0.5) | (white_d < 1.0) | (bbi_d < 1.0))
            & pull_white
            & ((day_chg < 2.0) | ((day_chg < 5.0) & white_support))
            & green_ok
            & pull_shrink
            & move_ok
            & (low <= prev_close)
        ),
        # 回踩超级B（超牛股回踩白线B1）
        "zgnb_pull_super": (
            super_bull
            & ((j < 35.0) | (rsi < 45.0) | wash)
            & (rs < 80.0)
            & (rs <= llv_rs25)
            & (day_amp < span_cap + 1.0)
            & ((day_chg < 2.5) | (white_d < 2.0))
            & strong_pull
            & green_ok
            & move_ok
            & proper_shrink
        ),
        # 回踩黄线B
        "zgnb_pull_yellow": (
            (white >= yellow)
            & (close >= yellow * 0.975)
            & ((j < 13.0) | (rsi < 18.0))
            & pull_yellow
            & green_ok
            & (shrink | (proper_shrink & ((j <= llv_j20) | (rsi <= llv_r14))))
            & (yellow >= yellow_prev * 0.997)
            & (ma60 >= ma60_prev)
            & (recent_amp >= 11.9)
            & (far_amp >= 19.5)
        ),
    }

    # 排序用的加成（0~40）。都取自原式自己已经算过的量：**过线越典型分越高**，
    # 不改「是否命中」—— 与金叉大阳 / 做T买点同一套做法。同样逐根算，因为
    # `zgnb_pull_super_10d` 要报「最近一次成立那根」的分数。
    shrink_ratio = np.divide(volume, hhv20, out=np.ones(n), where=hhv20 > 0)
    extra = {
        "zgnb_turn": _zgb1_gate(rsi - rsi_prev, 15.0, 30.0) * 20.0
        + _zgb1_gate(day_amp, span_cap + 0.5, 0.0) * 10.0
        + _zgb1_gate(day_chg, 2.3, 0.0) * 10.0,
        "zgnb_shrink": _zgb1_gate(rs, 55.0, 25.0) * 20.0
        + _zgb1_gate(shrink_ratio, 0.618, 0.2) * 10.0
        + _zgb1_gate(day_chg, 2.5, 0.0) * 10.0,
        "zgnb_origin": _zgb1_gate(rs, 40.0, 15.0) * 20.0
        + _zgb1_gate(shrink_ratio, 0.618, 0.2) * 10.0
        + _zgb1_gate(body_pct, 1.5, 0.0) * 10.0,
        "zgnb_super_shrink": _zgb1_gate(far_amp, 45.0, 120.0) * 20.0
        + _zgb1_gate(shrink_ratio, 0.25, 0.08) * 10.0
        + _zgb1_gate(day_chg, 2.0, 0.0) * 10.0,
        "zgnb_pull_white": _zgb1_gate(white_d, 3.5, 0.3) * 20.0
        + _zgb1_gate(shrink_ratio, 0.618, 0.2) * 10.0
        + _zgb1_gate(day_amp, span_cap + 0.5, 0.0) * 10.0,
        "zgnb_pull_super": _zgb1_gate(rs, 80.0, 25.0) * 20.0
        + _zgb1_gate(white_d, 3.5, 0.3) * 10.0
        + _zgb1_gate(shrink_ratio, 0.618, 0.2) * 10.0,
        "zgnb_pull_yellow": _zgb1_gate(yellow_d, 2.0, 0.0) * 20.0
        + _zgb1_gate(shrink_ratio, 0.618, 0.2) * 10.0
        + _zgb1_gate(recent_amp, 11.9, 40.0) * 10.0,
    }

    # 明细读数：同样逐根存，好让窗口形态能取「信号那根」而不是「今天」的值
    fields = {
        "rsi3": rsi,
        "kdj_j": j,
        "amp20": recent_amp,
        "amp50": far_amp,
        "vol_shrink": shrink_ratio,
        "dist_white": white_d,
        "dist_yellow": yellow_d,
        "dist_bbi": bbi_d,
        "day_amp": day_amp,
    }
    return {
        "enough": True,
        "fired": fired,
        "extra": extra,
        "fields": fields,
        "white": white,
        "yellow": yellow,
    }


def _zgb1_detail(fields: dict[str, np.ndarray], idx: int) -> dict[str, float]:
    """把 `fields` 上第 `idx` 根（负数下标）读成明细字典。"""
    return {
        name: round(float(fields[name][idx]) * scale, digits)
        for name, digits, scale in _ZGNB_DETAIL_FIELDS
    }


def _zgb1_signal(bars: Bars, key: str, *, window: int) -> Signal | None:
    """知行B1 各形态共用的出口：**最近 `window` 个交易日里出现过** `key` 就算命中。

    ⚠️ 现在 `window = 1`（2026-10-15 用户要求整组改回「当天」）—— 也就是**只有今天这根
    成立才算**，`idx` 恒为最后一根、`ago` 恒为 0。函数仍按窗口写，是为了 `window > 1`
    随时能回去：报「最近一次成立那根」的分数与读数，明细里附 `ago` = 距今几个交易日。
    （见 `ZGNB_RECENT_DAYS` 的说明：这个常量换过三轮。）
    """
    common = _zgb1_common(bars)
    if not common["enough"]:
        return None
    hit = np.flatnonzero(common["fired"][key][-window:])
    if hit.size == 0:
        return None
    idx = int(hit[-1]) - window  # 负数下标，指到整条序列上
    support = common["white"] if key in ZGNB_WHITE_SUPPORT_KEYS else common["yellow"]
    score = ZGNB_BASE_SCORE + float(common["extra"][key][idx])
    detail = _zgb1_detail(common["fields"], idx)
    detail["ago"] = -1 - idx
    return Signal(key, min(score, 100.0), {"support": float(support[idx])}, detail)


def _zgnb_turn(bars: Bars) -> Signal | None:
    """缩量拐头B1（原式 `超卖缩量拐头B`）：RSI 一天回升 ≥15 点，前一日还在超卖区。"""
    return _zgb1_signal(bars, "zgnb_turn", window=ZGNB_RECENT_DAYS)


def _zgnb_shrink(bars: Bars) -> Signal | None:
    """缩量B1（原式 `超卖缩量B`）：超卖区里的缩量止跌。"""
    return _zgb1_signal(bars, "zgnb_shrink", window=ZGNB_RECENT_DAYS)


def _zgnb_origin(bars: Bars) -> Signal | None:
    """原始B1：白线在黄线上方的多头上行里，超卖 + 缩量 + 小实体。"""
    return _zgb1_signal(bars, "zgnb_origin", window=ZGNB_RECENT_DAYS)


def _zgnb_super_shrink(bars: Bars) -> Signal | None:
    """超级缩量B1（原式 `超卖超缩量B`）：远期振幅 ≥45% 的票，超缩量。"""
    return _zgb1_signal(bars, "zgnb_super_shrink", window=ZGNB_RECENT_DAYS)


def _zgnb_pull_white(bars: Bars) -> Signal | None:
    """回踩白线B1（原式 `回踩白线B`）：强趋势股缩量回踩白线不破。"""
    return _zgb1_signal(bars, "zgnb_pull_white", window=ZGNB_RECENT_DAYS)


def _zgnb_pull_super(bars: Bars) -> Signal | None:
    """超牛股回踩白线B1（原式 `回踩超级B`）。

    ⚠️ 这一档全市场约 0.1 条/天，**经常整天空榜**（2026-10-13 曾因此把它的窗口独自
    放宽到 10 个交易日；2026-10-15 整组改回「当天」时又收回成 1）。现在走
    `ZGNB_RARE_RECENT_DAYS` 这个挂点，想重新放宽只改那个常量。
    """
    return _zgb1_signal(bars, "zgnb_pull_super", window=ZGNB_RARE_RECENT_DAYS)


def _zgnb_pull_yellow(bars: Bars) -> Signal | None:
    """回踩黄线B1（原式 `回踩黄线B`）：回踩多空线（大哥黄线）不破。"""
    return _zgb1_signal(bars, "zgnb_pull_yellow", window=ZGNB_RECENT_DAYS)


